#ifndef FACE_ANIMATOR_H
#define FACE_ANIMATOR_H

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ── OLED Config ──
#define OLED_WIDTH    128
#define OLED_HEIGHT   64
#define OLED_ADDR     0x3C   // JMD1.3A: 0x78 (8-bit) = 0x3C (7-bit)
#define OLED_RESET    -1

Adafruit_SSD1306 display(OLED_WIDTH, OLED_HEIGHT, &Wire, OLED_RESET);

// ── Ekspresi ──
typedef enum {
  EXPR_IDLE,
  EXPR_HAPPY,
  EXPR_SAD,
  EXPR_ANGRY,
  EXPR_SCARED,
  EXPR_SLEEPY,
  EXPR_BLINK,
  EXPR_CONFUSED
} Expression;

// ── State internal ──
static Expression currentExpr     = EXPR_IDLE;
static Expression pendingExpr     = EXPR_IDLE;
static bool       isBlinking      = false;
static uint8_t    blinkState      = 0;   // 0=open 1=half 2=closed
static unsigned long lastBlinkMs  = 0;
static unsigned long blinkInterval= 4000;
static unsigned long lastIdleMs   = 0;

// Pupil offset (dikontrol servo pan)
static int8_t pupilOffsetX = 0;
static int8_t pupilOffsetY = 0;

// ────────────────────────────────────────────
//  INTERNAL DRAW HELPERS
// ────────────────────────────────────────────

// Gambar satu mata lengkap
// cx,cy = pusat mata  ew=lebar eh=tinggi
// openRatio: 1.0=full open, 0.0=closed
// px,py = offset pupil
void _drawEye(int16_t cx, int16_t cy,
              int16_t ew, int16_t eh,
              float openRatio,
              int8_t px, int8_t py,
              bool angry = false, bool sad = false) {

  int16_t halfW = ew / 2;
  int16_t halfH = (int16_t)(eh * openRatio / 2);
  if (halfH < 1) halfH = 1;

  // Outline mata
  display.drawRoundRect(cx - halfW, cy - halfH,
                        ew, halfH * 2, 3, SSD1306_WHITE);

  // Kelopak atas untuk angry (miring ke dalam)
  if (angry && openRatio > 0.3) {
    display.drawLine(cx - halfW, cy - halfH,
                     cx,          cy - halfH + 4, SSD1306_WHITE);
  }
  // Kelopak bawah untuk sad (miring ke luar)
  if (sad && openRatio > 0.3) {
    display.drawLine(cx - halfW, cy - halfH,
                     cx,          cy - halfH - 3, SSD1306_WHITE);
  }

  // Pupil (hanya kalau cukup terbuka)
  if (openRatio > 0.35) {
    int16_t pr   = (int16_t)(halfH * 0.55);
    if (pr < 2) pr = 2;
    int16_t pcx  = cx + constrain((int16_t)px, (int16_t)(-halfW + pr + 1), (int16_t)(halfW - pr - 1));
    int16_t pcy  = cy + constrain((int16_t)py, (int16_t)(-halfH + pr + 1), (int16_t)(halfH - pr - 1));
    display.fillCircle(pcx, pcy, pr, SSD1306_WHITE);
    // Highlight
    if (pr >= 3)
      display.fillCircle(pcx + pr / 2, pcy - pr / 2, 1, SSD1306_BLACK);
  }
}

// ────────────────────────────────────────────
//  DRAW PER EKSPRESI
// ────────────────────────────────────────────

void _drawIdle(float blinkRatio = 1.0) {
  // Mata normal, pupil tengah
  _drawEye(40, 32, 28, 20, blinkRatio, pupilOffsetX, pupilOffsetY);
  _drawEye(88, 32, 28, 20, blinkRatio, pupilOffsetX, pupilOffsetY);
}

void _drawHappy(float blinkRatio = 1.0) {
  // Mata berbentuk arc ke atas (^_^)
  int16_t ey = 32;
  for (int i = 0; i < 2; i++) {
    int16_t cx = (i == 0) ? 40 : 88;
    // Gambar arc senyum sebagai "mata senang"
    display.drawRoundRect(cx - 14, ey - (int16_t)(10 * blinkRatio),
                          28, (int16_t)(20 * blinkRatio), 8, SSD1306_WHITE);
    // Tutup bagian bawah = mata ^ shape
    if (blinkRatio > 0.5)
      display.fillRect(cx - 15, ey, 30, 12, SSD1306_BLACK);
  }
  // Pipi / blush dots
  if (blinkRatio > 0.7) {
    for (int d = 0; d < 3; d++) {
      display.drawPixel(22 + d * 3, 44, SSD1306_WHITE);
      display.drawPixel(98 + d * 3, 44, SSD1306_WHITE);
    }
  }
}

void _drawSad(float blinkRatio = 1.0) {
  // Mata sedikit tertutup + pupil ke bawah + alis sedih
  _drawEye(40, 34, 26, 18, blinkRatio * 0.75,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2), false, true);
  _drawEye(88, 34, 26, 18, blinkRatio * 0.75,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2), false, true);
  // Garis air mata
  if (blinkRatio > 0.6) {
    display.drawLine(35, 46, 33, 54, SSD1306_WHITE);
    display.drawLine(83, 46, 81, 54, SSD1306_WHITE);
  }
}

void _drawAngry(float blinkRatio = 1.0) {
  // Mata kecil + alis miring ke dalam
  _drawEye(40, 32, 26, 18, blinkRatio * 0.65,
           pupilOffsetX, pupilOffsetY, true, false);
  _drawEye(88, 32, 26, 18, blinkRatio * 0.65,
           pupilOffsetX, pupilOffsetY, true, false);
  // Alis marah (V shape dari luar ke dalam turun)
  display.drawLine(26, 18, 40, 24, SSD1306_WHITE);
  display.drawLine(102, 18, 88, 24, SSD1306_WHITE);
}

void _drawScared(float blinkRatio = 1.0) {
  // Mata sangat besar + pupil kecil di tengah
  _drawEye(40, 32, 30, 24, blinkRatio, 0, 0);
  _drawEye(88, 32, 30, 24, blinkRatio, 0, 0);
  // Garis bergetar di mulut
  if (blinkRatio > 0.5) {
    for (int x = 50; x < 80; x += 4) {
      display.drawLine(x, 54, x + 2, 56, SSD1306_WHITE);
      display.drawLine(x + 2, 56, x + 4, 54, SSD1306_WHITE);
    }
  }
}

void _drawSleepy(float blinkRatio = 1.0) {
  // Mata setengah tertutup + pupil ke bawah
  float ratio = blinkRatio * 0.45;
  if (ratio < 0.1) ratio = 0.1;
  _drawEye(40, 34, 26, 20, ratio, 0, 3);
  _drawEye(88, 34, 26, 20, ratio, 0, 3);
  // ZZZ
  if (blinkRatio > 0.6) {
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(100, 10);
    display.print("z");
    display.setCursor(106, 5);
    display.print("Z");
  }
}

void _drawConfused(float blinkRatio = 1.0) {
  // Satu mata normal, satu mata lebih kecil
  _drawEye(40, 32, 28, 20, blinkRatio, -2, 0);
  _drawEye(88, 32, 22, 16, blinkRatio * 0.8, 2, -2);
  // Tanda tanya
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(60, 50);
  display.print("?");
}

// ────────────────────────────────────────────
//  PUBLIC API
// ────────────────────────────────────────────

bool faceBegin() {
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    return false;
  }
  display.clearDisplay();
  display.display();
  return true;
}

// Set offset pupil dari servo pan (panAngle 0-180, center=90)
void faceSetPupil(int panAngle, int tiltAngle) {
  // Map 0-180 → -6 to +6 pixel
  pupilOffsetX = (int8_t)map(panAngle,  0, 180, -6, 6);
  pupilOffsetY = (int8_t)map(tiltAngle, 0, 180, -4, 4);
}

// Set ekspresi — akan ditampilkan di render loop
void faceSetExpression(Expression expr) {
  currentExpr = expr;
}

// Trigger blink manual
void faceBlink() {
  isBlinking  = true;
  blinkState  = 0;
  lastBlinkMs = millis();
}

// Render — panggil di loop() setiap ~50ms
void faceRender() {
  unsigned long now = millis();

  // Auto blink timer
  if (!isBlinking && (now - lastBlinkMs > blinkInterval)) {
    isBlinking    = true;
    blinkState    = 0;
    lastBlinkMs   = now;
    blinkInterval = random(3000, 6000);
  }

  // Hitung blink ratio
  float blinkRatio = 1.0;
  if (isBlinking) {
    unsigned long elapsed = now - lastBlinkMs;
    if (blinkState == 0) {                      // tutup (150ms)
      blinkRatio = 1.0 - (float)elapsed / 150.0;
      if (elapsed >= 150) { blinkState = 1; lastBlinkMs = now; }
    } else if (blinkState == 1) {               // buka (150ms)
      blinkRatio = (float)elapsed / 150.0;
      if (elapsed >= 150) { isBlinking = false; blinkRatio = 1.0; }
    }
    blinkRatio = constrain(blinkRatio, 0.05, 1.0);
  }

  // Draw
  display.clearDisplay();

  switch (currentExpr) {
    case EXPR_IDLE:     _drawIdle(blinkRatio);    break;
    case EXPR_HAPPY:    _drawHappy(blinkRatio);   break;
    case EXPR_SAD:      _drawSad(blinkRatio);     break;
    case EXPR_ANGRY:    _drawAngry(blinkRatio);   break;
    case EXPR_SCARED:   _drawScared(blinkRatio);  break;
    case EXPR_SLEEPY:   _drawSleepy(blinkRatio);  break;
    case EXPR_CONFUSED: _drawConfused(blinkRatio);break;
    case EXPR_BLINK:    _drawIdle(blinkRatio);    break;
    default:            _drawIdle(blinkRatio);    break;
  }

  display.display();
}

#endif // FACE_ANIMATOR_H

