#ifndef MOVEMENT_H
#define MOVEMENT_H

// ── Pin L298N ──
#define PIN_IN1  14   // Motor kiri
#define PIN_IN2  27
#define PIN_IN3  26   // Motor kanan
#define PIN_IN4  25
#define PIN_ENA  32   // PWM kiri  (opsional — bisa jumper ke 5V di L298N)
#define PIN_ENB  33   // PWM kanan (opsional)

// LEDC channel untuk PWM ESP32
#define PWM_FREQ   1000
#define PWM_RES    8       // 8-bit = 0-255
#define CH_ENA     2
#define CH_ENB     3

#define SPEED_DEFAULT  180
#define SPEED_SLOW     110
#define SPEED_TURN     150

static int  currentSpeedL = 0;
static int  currentSpeedR = 0;
static int  targetSpeedL  = 0;
static int  targetSpeedR  = 0;
static unsigned long lastRampMs = 0;

// ────────────────────────────────────────────
void movementBegin() {
  pinMode(PIN_IN1, OUTPUT);
  pinMode(PIN_IN2, OUTPUT);
  pinMode(PIN_IN3, OUTPUT);
  pinMode(PIN_IN4, OUTPUT);

  // Setup LEDC PWM untuk ENA dan ENB
  ledcSetup(CH_ENA, PWM_FREQ, PWM_RES);
  ledcSetup(CH_ENB, PWM_FREQ, PWM_RES);
  ledcAttachPin(PIN_ENA, CH_ENA);
  ledcAttachPin(PIN_ENB, CH_ENB);

  ledcWrite(CH_ENA, 0);
  ledcWrite(CH_ENB, 0);

  digitalWrite(PIN_IN1, LOW);
  digitalWrite(PIN_IN2, LOW);
  digitalWrite(PIN_IN3, LOW);
  digitalWrite(PIN_IN4, LOW);
}

// Set arah & target speed langsung
void _setMotors(int speedL, int speedR) {
  // Motor kiri
  if (speedL > 0) {
    digitalWrite(PIN_IN1, HIGH);
    digitalWrite(PIN_IN2, LOW);
  } else if (speedL < 0) {
    digitalWrite(PIN_IN1, LOW);
    digitalWrite(PIN_IN2, HIGH);
  } else {
    digitalWrite(PIN_IN1, LOW);
    digitalWrite(PIN_IN2, LOW);
  }
  // Motor kanan
  if (speedR > 0) {
    digitalWrite(PIN_IN3, HIGH);
    digitalWrite(PIN_IN4, LOW);
  } else if (speedR < 0) {
    digitalWrite(PIN_IN3, LOW);
    digitalWrite(PIN_IN4, HIGH);
  } else {
    digitalWrite(PIN_IN3, LOW);
    digitalWrite(PIN_IN4, LOW);
  }
  ledcWrite(CH_ENA, abs(speedL));
  ledcWrite(CH_ENB, abs(speedR));
}

// ────────────────────────────────────────────
// Perintah gerak — set target, ramp dihandle di update()
void moveForward(int speed = SPEED_DEFAULT) {
  targetSpeedL =  speed;
  targetSpeedR =  speed;
}
void moveBackward(int speed = SPEED_DEFAULT) {
  targetSpeedL = -speed;
  targetSpeedR = -speed;
}
void turnLeft(int speed = SPEED_TURN) {
  targetSpeedL = -speed;
  targetSpeedR =  speed;
}
void turnRight(int speed = SPEED_TURN) {
  targetSpeedL =  speed;
  targetSpeedR = -speed;
}
void moveStop() {
  targetSpeedL = 0;
  targetSpeedR = 0;
}

// Dance move — sequence sederhana
static uint8_t  danceStep    = 0;
static bool     danceActive  = false;
static unsigned long danceMs = 0;

void moveDance() {
  danceActive = true;
  danceStep   = 0;
  danceMs     = millis();
}

// ────────────────────────────────────────────
// Update — panggil di loop() tiap ~30ms
// ────────────────────────────────────────────
void movementUpdate() {
  unsigned long now = millis();

  // Dance sequence
  if (danceActive) {
    if (now - danceMs > 400) {
      danceMs = now;
      danceStep++;
      switch (danceStep % 8) {
        case 0: targetSpeedL =  160; targetSpeedR =  160; break;
        case 1: targetSpeedL = -160; targetSpeedR = -160; break;
        case 2: targetSpeedL =  150; targetSpeedR = -150; break;
        case 3: targetSpeedL = -150; targetSpeedR =  150; break;
        case 4: targetSpeedL =  160; targetSpeedR =  160; break;
        case 5: targetSpeedL = -160; targetSpeedR = -160; break;
        case 6: targetSpeedL =  150; targetSpeedR = -150; break;
        case 7:
          targetSpeedL = 0; targetSpeedR = 0;
          danceActive = false;
          break;
      }
    }
  }

  // Ramp speed (akselerasi halus)
  if (now - lastRampMs >= 20) {
    lastRampMs = now;
    int rampStep = 18;
    if (currentSpeedL < targetSpeedL)
      currentSpeedL = min(currentSpeedL + rampStep, targetSpeedL);
    else if (currentSpeedL > targetSpeedL)
      currentSpeedL = max(currentSpeedL - rampStep, targetSpeedL);

    if (currentSpeedR < targetSpeedR)
      currentSpeedR = min(currentSpeedR + rampStep, targetSpeedR);
    else if (currentSpeedR > targetSpeedR)
      currentSpeedR = max(currentSpeedR - rampStep, targetSpeedR);

    _setMotors(currentSpeedL, currentSpeedR);
  }
}

bool isDancing() { return danceActive; }
bool isMoving()  { return (currentSpeedL != 0 || currentSpeedR != 0); }

#endif // MOVEMENT_H

