#ifndef AUDIO_PLAYER_H
#define AUDIO_PLAYER_H

#include <DFRobotDFPlayerMini.h>
#include <HardwareSerial.h>

// ── Pin DFPlayer ──
// DFPlayer TX → ESP32 GPIO16 (RX2)
// DFPlayer RX → ESP32 GPIO17 (TX2) via resistor 1k
#define DFPLAYER_RX  16
#define DFPLAYER_TX  17

HardwareSerial dfSerial(2);   // UART2
DFRobotDFPlayerMini dfPlayer;

static bool dfReady = false;

// ── Nomor track di microSD ──
// Simpan file MP3 di folder /mp3/ dengan nama 0001.mp3 dst
// atau langsung di root: 001.mp3, 002.mp3, ...
#define SFX_HAPPY     1   // suara senang / "yay"
#define SFX_SAD       2   // suara sedih / "hmm"
#define SFX_ANGRY     3   // suara kesal / "grr"
#define SFX_SCARED    4   // suara kaget / "aah!"
#define SFX_SLEEPY    5   // suara ngantuk / "zzz"
#define SFX_IDLE_1    6   // "hmm..." random idle
#define SFX_IDLE_2    7   // "oh..." random idle
#define SFX_IDLE_3    8   // suara kecil random
#define SFX_GREET     9   // saat dipanggil / sambut
#define SFX_CONFUSED  10  // "huh?"

// ────────────────────────────────────────────
bool audioBegin() {
  dfSerial.begin(9600, SERIAL_8N1, DFPLAYER_RX, DFPLAYER_TX);
  delay(1000);
  if (!dfPlayer.begin(dfSerial, true, true)) {
    dfReady = false;
    return false;
  }
  dfPlayer.volume(20);   // Volume 0-30
  dfReady = true;
  return true;
}

void audioPlay(uint8_t track) {
  if (!dfReady) return;
  dfPlayer.play(track);
}

void audioPlayIdle() {
  if (!dfReady) return;
  // Pilih random dari 3 suara idle
  uint8_t t = random(SFX_IDLE_1, SFX_IDLE_3 + 1);
  dfPlayer.play(t);
}

void audioSetVolume(uint8_t vol) {
  if (!dfReady) return;
  dfPlayer.volume(constrain(vol, 0, 30));
}

void audioStop() {
  if (!dfReady) return;
  dfPlayer.stop();
}

bool audioIsReady() { return dfReady; }

#endif // AUDIO_PLAYER_H

