  if (faceDetected) {
    lastInteractMs = millis();
    if (robotState == STATE_LONELY || robotState == STATE_SLEEPY) {
      _enterState(STATE_HAPPY);
    }
    headTrackFace(faceX, faceY);

    // Follow mode: dekati wajah jika jauh
    if (followMode && obstacleDistCm > DIST_FOLLOW_STOP_CM) {
