<div class="status"><span id="connDot">●</span> <span id="stateText">IDLE</span> &nbsp;|&nbsp; Jarak: <span id="distText">--</span> cm &nbsp;|&nbsp; Wajah: <span id="faceText">tidak ada</span></div>

<!-- GERAK -->
<div class="card">
  <div class="card-title">▶ Gerak</div>
  <div class="dpad">
    <div class="empty"></div>
    <div class="btn" id="btn-fwd" ontouchstart="hold('forward')" ontouchend="release()" onmousedown="hold('forward')" onmouseup="release()">▲</div>
    <div class="empty"></div>
    <div class="btn" id="btn-left" ontouchstart="hold('left')" ontouchend="release()" onmousedown="hold('left')" onmouseup="release()">◀</div>
    <div class="btn btn-stop" onclick="send('stop')">■</div>
    <div class="btn" id="btn-right" ontouchstart="hold('right')" ontouchend="release()" onmousedown="hold('right')" onmouseup="release()">▶</div>
    <div class="empty"></div>
    <div class="btn" id="btn-back" ontouchstart="hold('backward')" ontouchend="release()" onmousedown="hold('backward')" onmouseup="release()">▼</div>
    <div class="empty"></div>
  </div>
</div>

<!-- PERINTAH -->
<div class="card">
  <div class="card-title">▶ Perintah</div>
  <div class="cmd-grid">
    <div class="btn-cmd" onclick="send('come')">📍 Kemari</div>
    <div class="btn-cmd" onclick="toggleFollow()">🔄 <span id="followTxt">Ikuti</span></div>
    <div class="btn-cmd btn-dance" onclick="send('dance')">🕺 Dance</div>
    <div class="btn-cmd" onclick="send('stop')">⏹ Berhenti</div>
  </div>
</div>

<!-- EKSPRESI -->
<div class="card">
  <div class="card-title">▶ Ekspresi (sementara 4 detik)</div>
  <div class="expr-row">
    <div class="btn-expr" onclick="send('expr_happy')" title="Senang">😊</div>
    <div class="btn-expr" onclick="send('expr_sad')" title="Sedih">😢</div>
    <div class="btn-expr" onclick="send('expr_angry')" title="Marah">😠</div>
    <div class="btn-expr" onclick="send('expr_scared')" title="Kaget">😲</div>
    <div class="btn-expr" onclick="send('expr_sleepy')" title="Ngantuk">😴</div>
  </div>
</div>

<!-- STATUS -->
<div class="card">
  <div class="card-title">▶ Status Robot</div>
  <div class="state-row"><span class="state-label">STATE</span><span class="state-val" id="stateVal">IDLE</span></div>
  <div class="state-row"><span class="state-label">WAJAH TERDETEKSI</span><span class="state-val" id="faceVal">–</span></div>
  <div class="state-row"><span class="state-label">JARAK DEPAN</span><span class="state-val" id="distVal">– cm</span></div>
  <div class="state-row"><span class="state-label">FOLLOW MODE</span><span class="state-val" id="followVal">OFF</span></div>
</div>

<script>
let holdInterval = null;
let followActive = false;

function send(cmd) {
  fetch('/cmd?action=' + cmd).catch(()=>{});
}

function hold(cmd) {
  send(cmd);
  holdInterval = setInterval(()=>send(cmd), 120);
}

function release() {
  clearInterval(holdInterval);
  holdInterval = null;
  send('stop');
}

function toggleFollow() {
  followActive = !followActive;
  document.getElementById('followTxt').textContent = followActive ? 'Stop Ikut' : 'Ikuti';
  send(followActive ? 'follow' : 'stop');
}

// Poll status setiap 800ms
function pollStatus() {
  fetch('/status')
    .then(r => r.json())
    .then(d => {
      document.getElementById('stateText').textContent = d.state;
      document.getElementById('stateVal').textContent  = d.state;
      document.getElementById('faceVal').textContent   = d.face ? 'YA ✓' : 'Tidak';
      document.getElementById('faceText').textContent  = d.face ? 'ada' : 'tidak ada';
      document.getElementById('distVal').textContent   = d.dist + ' cm';
      document.getElementById('distText').textContent  = d.dist;
      document.getElementById('followVal').textContent = d.follow ? 'ON' : 'OFF';
    })
    .catch(()=>{});
}

setInterval(pollStatus, 800);
pollStatus();
</script>
</body>
</html>
)rawhtml";

// ────────────────────────────────────────────
//  HANDLER HTTP
// ────────────────────────────────────────────
void handleRoot() {
  server.send_P(200, "text/html", HTML_PAGE);
}

void handleCmd() {
  if (!server.hasArg("action")) {
    server.send(400, "text/plain", "no action");
    return;
  }
  String action = server.arg("action");

  if      (action == "forward")      pendingCommand = CMD_FORWARD;
  else if (action == "backward")     pendingCommand = CMD_BACKWARD;
  else if (action == "left")         pendingCommand = CMD_LEFT;
  else if (action == "right")        pendingCommand = CMD_RIGHT;
  else if (action == "stop")         pendingCommand = CMD_STOP;
  else if (action == "come")         pendingCommand = CMD_COME;
  else if (action == "follow")       pendingCommand = CMD_FOLLOW;
  else if (action == "dance")        pendingCommand = CMD_DANCE;
  else if (action == "expr_happy")   pendingCommand = CMD_EXPR_HAPPY;
  else if (action == "expr_sad")     pendingCommand = CMD_EXPR_SAD;
  else if (action == "expr_angry")   pendingCommand = CMD_EXPR_ANGRY;
  else if (action == "expr_scared")  pendingCommand = CMD_EXPR_SCARED;
  else if (action == "expr_sleepy")  pendingCommand = CMD_EXPR_SLEEPY;

  server.send(200, "text/plain", "ok");
}

void handleStatus() {
  // Buat JSON status
  String stateStr;
  switch (robotState) {
    case STATE_IDLE:    stateStr = "IDLE";    break;
    case STATE_HAPPY:   stateStr = "HAPPY";   break;
    case STATE_LONELY:  stateStr = "LONELY";  break;
    case STATE_ANNOYED: stateStr = "ANNOYED"; break;
    case STATE_SCARED:  stateStr = "SCARED";  break;
    case STATE_SLEEPY:  stateStr = "SLEEPY";  break;
    default:            stateStr = "IDLE";    break;
  }
  String json = "{\"state\":\"" + stateStr + "\","
                + "\"face\":"  + (faceDetected ? "true" : "false") + ","
                + "\"dist\":"  + String(obstacleDistCm) + ","
                + "\"follow\":" + (followMode ? "true" : "false") + "}";
  server.send(200, "application/json", json);
}

void handleNotFound() {
  server.send(404, "text/plain", "not found");
}

// ────────────────────────────────────────────
void wifiControllerBegin() {
  WiFi.softAP(WIFI_SSID, WIFI_PASS);
  server.on("/",       handleRoot);
  server.on("/cmd",    handleCmd);
  server.on("/status", handleStatus);
  server.onNotFound(handleNotFound);
  server.begin();
}

// Panggil di task WiFi
void wifiControllerHandle() {
  server.handleClient();
}

#endif // WIFI_CONTROLLER_H

