/*
 * ══════════════════════════════════════════════════════
 *   ROBOT EMO DIY — Main Controller (ESP32)
 *   Hardware:
 *     - ESP32 Dev Module (30-pin)
 *     - OLED 1.3" I2C JMD1.3A (SSD1306/SH1106, addr 0x3C)
 *     - Servo SG90 x2 (pan-tilt kepala)
 *     - Motor TT x2 + L298N
 *     - HC-SR04
 *     - DFPlayer Mini + Speaker 1W
 *     - LM2596 step-down 11.1V → 5V
 *     - ESP32-CAM (board terpisah, UART komunikasi)
 *
 *   Library yang dibutuhkan (install via Library Manager):
 *     - Adafruit SSD1306
 *     - Adafruit GFX Library
 *     - ESP32Servo
 *     - DFRobotDFPlayerMini
 *     - NewPing
 * ══════════════════════════════════════════════════════
 */

// Urutan include PENTING — jangan diubah
#include "FaceAnimator.h"
#include "HeadMotion.h"
#include "Movement.h"
#include "AudioPlayer.h"
#include "StateMachine.h"
#include "WiFiController.h"

// ── HC-SR04 ──
#include <NewPing.h>
#define PIN_TRIG    12
#define PIN_ECHO    13
#define SONAR_MAX   200
NewPing sonar(PIN_TRIG, PIN_ECHO, SONAR_MAX);

// ── ESP32-CAM komunikasi via UART ──
// ESP32-CAM TX → ESP32 GPIO3 (RX0) — gunakan Serial (UART0) hanya untuk debug
// Lebih baik pakai Serial1 agar tidak konflik dengan Serial monitor
#define CAM_SERIAL_RX  35   // ESP32 terima data dari CAM
#define CAM_SERIAL_TX  -1   // tidak perlu kirim ke CAM (hanya terima)
HardwareSerial camSerial(1);  // UART1

// ── Timing loop ──
unsigned long prevFaceMs   = 0;
unsigned long prevSonarMs  = 0;
unsigned long prevStateMs  = 0;
unsigned long prevHeadMs   = 0;
unsigned long prevFaceRenderMs = 0;
unsigned long prevMotorMs  = 0;

// ══════════════════════════════════════════════════════
//  TASK WIFI — berjalan di Core 1
// ══════════════════════════════════════════════════════
void taskWiFi(void *param) {
  wifiControllerBegin();
  for (;;) {
    wifiControllerHandle();
    vTaskDelay(10 / portTICK_PERIOD_MS);
  }
}

// ══════════════════════════════════════════════════════
//  PARSE DATA DARI ESP32-CAM
//  Format: "F,x,y\n"  = wajah ditemukan di koordinat x,y
//          "N\n"       = tidak ada wajah
// ══════════════════════════════════════════════════════
void parseCamData() {
  if (!camSerial.available()) return;

  String line = camSerial.readStringUntil('\n');
  line.trim();

  if (line.startsWith("F,")) {
    // Parse x,y
    int comma1 = line.indexOf(',');
    int comma2 = line.indexOf(',', comma1 + 1);
    if (comma1 > 0 && comma2 > comma1) {
      int x = line.substring(comma1 + 1, comma2).toInt();
      int y = line.substring(comma2 + 1).toInt();
      faceDetected = true;
      faceX        = x;
      faceY        = y;
    }
  } else if (line == "N") {
    faceDetected = false;
  }
}

// ══════════════════════════════════════════════════════
//  SETUP
// ══════════════════════════════════════════════════════
void setup() {
  Serial.begin(115200);
  Serial.println("\n[EMO] Booting...");

  // UART ke ESP32-CAM
  camSerial.begin(115200, SERIAL_8N1, CAM_SERIAL_RX, -1);

  // Init OLED
  if (!faceBegin()) {
    Serial.println("[EMO] OLED gagal! Cek wiring SDA/SCL dan alamat 0x3C");
  } else {
    Serial.println("[EMO] OLED OK");
  }

  // Init servo
  headBegin();
  Serial.println("[EMO] Servo OK");

  // Init motor
  movementBegin();
  Serial.println("[EMO] Motor OK");

  // Init DFPlayer
  if (!audioBegin()) {
    Serial.println("[EMO] DFPlayer gagal atau tidak ada SD card");
  } else {
    Serial.println("[EMO] DFPlayer OK");
  }

  // Init state machine
  stateMachineBegin();
  Serial.println("[EMO] State machine OK");

  // WiFi task di Core 1
  xTaskCreatePinnedToCore(
    taskWiFi,      // fungsi task
    "WiFiTask",    // nama
    8192,          // stack size
    NULL,          // parameter
    1,             // prioritas
    NULL,          // handle
    1              // Core 1
  );
  Serial.println("[EMO] WiFi task started");
  Serial.println("[EMO] SSID: RobotEMO | Pass: emo12345");
  Serial.println("[EMO] IP: 192.168.4.1");
  Serial.println("[EMO] Ready!");
}

// ══════════════════════════════════════════════════════
//  LOOP — berjalan di Core 0 (Autonomous Core)
// ══════════════════════════════════════════════════════
void loop() {
  unsigned long now = millis();

  // ── Baca kamera setiap 30ms ──
  if (now - prevFaceMs >= 30) {
    prevFaceMs = now;
    parseCamData();
  }

  // ── Baca sonar setiap 60ms ──
  if (now - prevSonarMs >= 60) {
    prevSonarMs = now;
    unsigned int dist = sonar.ping_cm();
    if (dist == 0) dist = 999;  // 0 = out of range → anggap jauh
    obstacleDistCm = dist;
  }

