#ifndef FACE_ANIMATOR_H
#define FACE_ANIMATOR_H

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>

// ── OLED Config ──
// JMD1.3A = SH1106 128x64, I2C addr 0x78 (8-bit) = 0x3C (7-bit)
// U8g2: SH1106 full buffer mode, hardware I2C
U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

// ── Ekspresi ──
typedef enum {
  EXPR_IDLE,
  EXPR_HAPPY,
  EXPR_SAD,
  EXPR_ANGRY,
  EXPR_SCARED,
  EXPR_SLEEPY,
  EXPR_BLINK,
  EXPR_CONFUSED
} Expression;

// ── State internal ──
static Expression currentExpr      = EXPR_IDLE;
static bool       isBlinking       = false;
static uint8_t    blinkState       = 0;
static unsigned long lastBlinkMs   = 0;
static unsigned long blinkInterval = 4000;

// Pupil offset dari servo pan/tilt
static int8_t pupilOffsetX = 0;
static int8_t pupilOffsetY = 0;

// ────────────────────────────────────────────
//  INTERNAL DRAW HELPERS
// ────────────────────────────────────────────

// Gambar satu mata
// cx,cy=pusat, ew=lebar, eh=tinggi, openRatio=0.0-1.0
void _drawEye(int16_t cx, int16_t cy,
              int16_t ew, int16_t eh,
              float openRatio,
              int8_t px, int8_t py,
              bool angry = false,
              bool sad   = false) {

  int16_t halfW = ew / 2;
  int16_t halfH = max((int16_t)1, (int16_t)(eh * openRatio / 2));

  // Outline mata
  u8g2.drawRBox(cx - halfW, cy - halfH, ew, halfH * 2, 3);

  // Alis angry
  if (angry && openRatio > 0.3) {
    u8g2.drawLine(cx - halfW, cy - halfH - 3,
                  cx,          cy - halfH + 1);
  }
  // Alis sad
  if (sad && openRatio > 0.3) {
    u8g2.drawLine(cx - halfW, cy - halfH - 1,
                  cx,          cy - halfH - 4);
  }

  // Pupil
  if (openRatio > 0.3) {
    int16_t pr  = max((int16_t)2, (int16_t)(halfH * 0.55));
    int16_t pcx = cx + (int16_t)constrain((int16_t)px,
                        (int16_t)(-halfW + pr + 1),
                        (int16_t)(halfW  - pr - 1));
    int16_t pcy = cy + (int16_t)constrain((int16_t)py,
                        (int16_t)(-halfH + pr + 1),
                        (int16_t)(halfH  - pr - 1));
    // Pupil hitam (XOR dengan outline putih)
    u8g2.setDrawColor(0);
    u8g2.drawDisc(pcx, pcy, pr);
    // Highlight
    u8g2.setDrawColor(1);
    if (pr >= 3)
      u8g2.drawPixel(pcx + pr / 2, pcy - pr / 2);
    u8g2.setDrawColor(1);
  }
}

// ────────────────────────────────────────────
//  DRAW PER EKSPRESI
// ────────────────────────────────────────────

void _drawIdle(float br = 1.0) {
  _drawEye(36, 32, 28, 22, br, pupilOffsetX, pupilOffsetY);
  _drawEye(92, 32, 28, 22, br, pupilOffsetX, pupilOffsetY);
}

void _drawHappy(float br = 1.0) {
  // Mata melengkung ke atas (^_^)
  int16_t h = (int16_t)(12 * br);
  if (h < 1) h = 1;
  // Kiri
  u8g2.drawRBox(22, 32 - h / 2, 28, h, 4);
  u8g2.setDrawColor(0);
  u8g2.drawBox(22, 32, 28, h / 2 + 2);
  u8g2.setDrawColor(1);
  // Kanan
  u8g2.drawRBox(78, 32 - h / 2, 28, h, 4);
  u8g2.setDrawColor(0);
  u8g2.drawBox(78, 32, 28, h / 2 + 2);
  u8g2.setDrawColor(1);
  // Pipi dots
  if (br > 0.7) {
    u8g2.drawDisc(18, 44, 2);
    u8g2.drawDisc(110, 44, 2);
  }
}

void _drawSad(float br = 1.0) {
  _drawEye(36, 35, 26, 18, br * 0.7,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2),
           false, true);
  _drawEye(92, 35, 26, 18, br * 0.7,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2),
           false, true);
  // Air mata
  if (br > 0.6) {
    u8g2.drawLine(31, 47, 29, 56);
    u8g2.drawLine(87, 47, 85, 56);
  }
}

void _drawAngry(float br = 1.0) {
  _drawEye(36, 32, 26, 18, br * 0.6,
           pupilOffsetX, pupilOffsetY, true, false);
  _drawEye(92, 32, 26, 18, br * 0.6,
           pupilOffsetX, pupilOffsetY, true, false);
  // Alis tegas
  u8g2.drawLine(20, 16, 38, 22);
  u8g2.drawLine(108, 16, 90, 22);
  u8g2.drawLine(20, 17, 38, 23);
}

void _drawScared(float br = 1.0) {
  // Mata sangat besar
  _drawEye(36, 32, 32, 26, br, 0, 0);
  _drawEye(92, 32, 32, 26, br, 0, 0);
  // Mulut gemetar
  if (br > 0.5) {
    for (int x = 44; x < 84; x += 4) {
      u8g2.drawLine(x,     54, x + 2, 57);
      u8g2.drawLine(x + 2, 57, x + 4, 54);
    }
  }
}

void _drawSleepy(float br = 1.0) {
  float ratio = max(0.1f, br * 0.4f);
  _drawEye(36, 35, 26, 20, ratio, 0, 3);
  _drawEye(92, 35, 26, 20, ratio, 0, 3);
  // ZZZ
  if (br > 0.5) {
    u8g2.setFont(u8g2_font_6x10_tr);
    u8g2.drawStr(100, 18, "z");
    u8g2.drawStr(106, 12, "Z");
  }
}

void _drawConfused(float br = 1.0) {
  _drawEye(36, 32, 28, 20, br,       -2, 0);
  _drawEye(92, 32, 22, 16, br * 0.8,  2, -2);
  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.drawStr(58, 58, "?");
}

// ────────────────────────────────────────────
//  PUBLIC API
// ────────────────────────────────────────────

bool faceBegin() {
  u8g2.begin();
  u8g2.setDrawColor(1);
  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.clearBuffer();
  u8g2.sendBuffer();
  return true;  // U8g2 tidak return false — selalu true
}

void faceSetPupil(int panAngle, int tiltAngle) {
  pupilOffsetX = (int8_t)map(panAngle,  0, 180, -6,  6);
  pupilOffsetY = (int8_t)map(tiltAngle, 0, 180, -4,  4);
}

void faceSetExpression(Expression expr) {
  currentExpr = expr;
}

void faceBlink() {
  isBlinking  = true;
  blinkState  = 0;
  lastBlinkMs = millis();
}

// Render — panggil di loop() tiap ~50ms
void faceRender() {
  unsigned long now = millis();

  // Auto blink
  if (!isBlinking && (now - lastBlinkMs > blinkInterval)) {
    isBlinking    = true;
    blinkState    = 0;
    lastBlinkMs   = now;
    blinkInterval = random(3000, 6000);
  }

  // Hitung blink ratio
  float blinkRatio = 1.0f;
  if (isBlinking) {
    unsigned long elapsed = now - lastBlinkMs;
    if (blinkState == 0) {
      blinkRatio = 1.0f - (float)elapsed / 150.0f;
      if (elapsed >= 150) { blinkState = 1; lastBlinkMs = now; }
    } else {
      blinkRatio = (float)elapsed / 150.0f;
      if (elapsed >= 150) { isBlinking = false; blinkRatio = 1.0f; }
    }
    blinkRatio = constrain(blinkRatio, 0.05f, 1.0f);
  }

  // Draw ke buffer
  u8g2.clearBuffer();
  u8g2.setDrawColor(1);

  switch (currentExpr) {
    case EXPR_IDLE:     _drawIdle(blinkRatio);     break;
    case EXPR_HAPPY:    _drawHappy(blinkRatio);    break;
    case EXPR_SAD:      _drawSad(blinkRatio);      break;
    case EXPR_ANGRY:    _drawAngry(blinkRatio);    break;
    case EXPR_SCARED:   _drawScared(blinkRatio);   break;
    case EXPR_SLEEPY:   _drawSleepy(blinkRatio);   break;
    case EXPR_CONFUSED: _drawConfused(blinkRatio); break;
    case EXPR_BLINK:    _drawIdle(blinkRatio);     break;
    default:            _drawIdle(blinkRatio);     break;
  }

  u8g2.sendBuffer();
}

#endif // FACE_ANIMATOR_H
ENDOFFILE
echo "Done"

