#ifndef FACE_ANIMATOR_H
#define FACE_ANIMATOR_H

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>

// ── OLED SH1106 128x64 landscape ──
U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

typedef enum {
  EXPR_IDLE,
  EXPR_HAPPY,
  EXPR_SAD,
  EXPR_ANGRY,
  EXPR_SCARED,
  EXPR_SLEEPY,
  EXPR_BLINK,
  EXPR_CONFUSED
} Expression;

static Expression    currentExpr    = EXPR_IDLE;
static bool          isBlinking     = false;
static uint8_t       blinkState     = 0;
static unsigned long lastBlinkMs    = 0;
static unsigned long blinkInterval  = 4000;
static int8_t        pupilOffsetX   = 0;
static int8_t        pupilOffsetY   = 0;

// ────────────────────────────────────────────
//  DRAW SATU MATA
//  cx,cy  = pusat mata
//  ew     = lebar penuh mata (pixel)
//  eh     = tinggi penuh mata saat terbuka (pixel)
//  openRatio = 0.0 (tertutup) .. 1.0 (terbuka penuh)
//  px,py  = offset pupil
// ────────────────────────────────────────────
void _drawEye(int16_t cx, int16_t cy,
              int16_t ew, int16_t eh,
              float   openRatio,
              int8_t  px, int8_t py,
              bool angry = false,
              bool sad   = false) {

  // Tinggi aktual saat ini (HANYA berubah vertikal saat kedip)
  int16_t halfW = ew / 2;
  int16_t halfH = (int16_t)(eh * openRatio / 2.0f);
  if (halfH < 1) halfH = 1;

  int16_t x0 = cx - halfW;
  int16_t y0 = cy - halfH;
  int16_t w  = ew;
  int16_t h  = halfH * 2;

  // Outline putih
  u8g2.setDrawColor(1);
  u8g2.drawRFrame(x0, y0, w, h, 3);

  // Fill putih
  u8g2.drawRBox(x0 + 1, y0 + 1, w - 2, h - 2, 2);

  // Alis angry — garis hitam di sudut atas dalam
  if (angry && openRatio > 0.4f) {
    u8g2.setDrawColor(0);
    u8g2.drawLine(cx - halfW + 1, cy - halfH,
                  cx,              cy - halfH + 4);
    u8g2.setDrawColor(1);
  }

  // Alis sad — garis di sudut atas luar
  if (sad && openRatio > 0.4f) {
    u8g2.setDrawColor(0);
    u8g2.drawLine(cx - halfW + 1, cy - halfH + 3,
                  cx,              cy - halfH);
    u8g2.setDrawColor(1);
  }

  // Pupil (bulat hitam di tengah area putih)
  if (openRatio > 0.25f) {
    int16_t pr  = max((int16_t)2, (int16_t)(halfH * 0.6f));
    // Batasi pupil agar tidak keluar area mata
    int16_t pcx = cx + (int16_t)constrain((int)px,
                         -(halfW - pr - 2),
                          (halfW - pr - 2));
    int16_t pcy = cy + (int16_t)constrain((int)py,
                         -(halfH - pr - 1),
                          (halfH - pr - 1));
    u8g2.setDrawColor(0);
    u8g2.drawDisc(pcx, pcy, pr);
    // Highlight kecil putih
    u8g2.setDrawColor(1);
    if (pr >= 3)
      u8g2.drawDisc(pcx + pr / 2, pcy - pr / 2, 1);
  }

  // Selalu kembalikan draw color ke 1
  u8g2.setDrawColor(1);
}

// ────────────────────────────────────────────
//  EKSPRESI
// ────────────────────────────────────────────

// IDLE — mata normal, pupil ikut servo
void _drawIdle(float br) {
  _drawEye(36, 32, 30, 22, br, pupilOffsetX, pupilOffsetY);
  _drawEye(92, 32, 30, 22, br, pupilOffsetX, pupilOffsetY);
}

// HAPPY — mata melengkung atas (^_^), tidak ikut blink normal
void _drawHappy(float br) {
  // Arc mata: gambar kotak penuh lalu hapus bagian bawah
  int16_t h = max((int16_t)2, (int16_t)(20 * br));
  // Kiri
  u8g2.setDrawColor(1);
  u8g2.drawRBox(21, 32 - h, 30, h, 4);
  u8g2.setDrawColor(0);
  u8g2.drawBox(21, 32 - h / 2, 30, h);    // hapus setengah bawah
  u8g2.setDrawColor(1);
  // Kanan
  u8g2.drawRBox(77, 32 - h, 30, h, 4);
  u8g2.setDrawColor(0);
  u8g2.drawBox(77, 32 - h / 2, 30, h);
  u8g2.setDrawColor(1);
  // Pipi dots
  if (br > 0.6f) {
    u8g2.drawDisc(16, 44, 2);
    u8g2.drawDisc(112, 44, 2);
  }
}

// SAD — mata setengah tutup + alis sedih + air mata
void _drawSad(float br) {
  _drawEye(36, 34, 28, 20, br * 0.65f,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2),
           false, true);
  _drawEye(92, 34, 28, 20, br * 0.65f,
           pupilOffsetX, (int8_t)(pupilOffsetY + 2),
           false, true);
