  u8g2.setDrawColor(1);
  u8g2.drawLine(20, 15, 40, 21);
  u8g2.drawLine(20, 16, 40, 22);
  u8g2.drawLine(108, 15, 88, 21);
  u8g2.drawLine(108, 16, 88, 22);
}

// SCARED — mata sangat besar + mulut gemetar
void _drawScared(float br) {
  _drawEye(36, 30, 34, 28, br, 0, 0);
  _drawEye(92, 30, 34, 28, br, 0, 0);
