  // Gunakan animasi terpisah: mata menutup pelan seiring waktu
  static float sleepyClose = 0.45f;
  static unsigned long lastSleepMs = 0;
  unsigned long now = millis();
  if (now - lastSleepMs > 2000) {
    lastSleepMs = now;
    sleepyClose -= 0.05f;
    if (sleepyClose < 0.15f) sleepyClose = 0.15f;
  }
  float ratio = sleepyClose * br;
  if (ratio < 0.1f) ratio = 0.1f;

  _drawEye(36, 34, 28, 22, ratio, 0, 3);
  _drawEye(92, 34, 28, 22, ratio, 0, 3);
