  _drawEye(92, 32, 22, 16, br * 0.75f, 2, -2);
  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.setDrawColor(1);
  u8g2.drawStr(58, 58, "?");
}

// ────────────────────────────────────────────
//  PUBLIC API
// ────────────────────────────────────────────

bool faceBegin() {
  u8g2.begin();
  u8g2.setDrawColor(1);
  u8g2.clearBuffer();
  u8g2.sendBuffer();
  return true;
}

void faceSetPupil(int panAngle, int tiltAngle) {
  pupilOffsetX = (int8_t)map(panAngle,  0, 180, -5,  5);
  pupilOffsetY = (int8_t)map(tiltAngle, 0, 180, -3,  3);
}

void faceSetExpression(Expression expr) {
  currentExpr = expr;
}

void faceBlink() {
  if (!isBlinking) {
    isBlinking  = true;
    blinkState  = 0;
    lastBlinkMs = millis();
  }
}

// Render — panggil tiap ~50ms
void faceRender() {
  unsigned long now = millis();

  // ── Auto blink timer ──
  if (!isBlinking && (now - lastBlinkMs > blinkInterval)) {
    isBlinking    = true;
    blinkState    = 0;
    lastBlinkMs   = now;
    blinkInterval = (unsigned long)random(3000, 6500);
  }

  // ── Hitung blink ratio ──
  // Kedip = tutup mata (tinggi mengecil ke 0), bukan melebar!
  float blinkRatio = 1.0f;
  if (isBlinking) {
    unsigned long el = now - lastBlinkMs;
    if (blinkState == 0) {
      // Fase tutup: 120ms
      blinkRatio = 1.0f - ((float)el / 120.0f);
      if (el >= 120) {
        blinkState  = 1;
        lastBlinkMs = now;
        blinkRatio  = 0.05f;
      }
    } else if (blinkState == 1) {
      // Tahan tutup: 40ms
      blinkRatio = 0.05f;
      if (el >= 40) {
        blinkState  = 2;
        lastBlinkMs = now;
      }
    } else {
      // Fase buka: 150ms
      blinkRatio = (float)el / 150.0f;
      if (el >= 150) {
        isBlinking = false;
        blinkRatio = 1.0f;
      }
    }
    blinkRatio = constrain(blinkRatio, 0.04f, 1.0f);
  }

  // ── Draw ke buffer ──
  u8g2.clearBuffer();
  u8g2.setDrawColor(1);   // reset setiap frame — cegah glitch

  switch (currentExpr) {
    case EXPR_IDLE:     _drawIdle(blinkRatio);     break;
    case EXPR_HAPPY:    _drawHappy(blinkRatio);    break;
    case EXPR_SAD:      _drawSad(blinkRatio);      break;
    case EXPR_ANGRY:    _drawAngry(blinkRatio);    break;
    case EXPR_SCARED:   _drawScared(blinkRatio);   break;
    case EXPR_SLEEPY:   _drawSleepy(blinkRatio);   break;
    case EXPR_CONFUSED: _drawConfused(blinkRatio); break;
    case EXPR_BLINK:    _drawIdle(blinkRatio);     break;
    default:            _drawIdle(blinkRatio);     break;
  }

  u8g2.sendBuffer();
}

#endif // FACE_ANIMATOR_H
ENDOFFILE
echo "Done"

