#ifndef FACE_ANIMATOR_H
#define FACE_ANIMATOR_H

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>

// SH1106 128x64
U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

typedef enum {
  EXPR_IDLE,
  EXPR_HAPPY,
  EXPR_SAD,
  EXPR_ANGRY,
  EXPR_SCARED,
  EXPR_SLEEPY,
  EXPR_BLINK,
  EXPR_CONFUSED
} Expression;

static Expression    currentExpr   = EXPR_IDLE;
static bool          isBlinking    = false;
static uint8_t       blinkPhase    = 0;  // 0=tutup 1=tahan 2=buka
static unsigned long lastBlinkMs   = 0;
static unsigned long blinkInterval = 4000;
static int8_t        pupilOffsetX  = 0;
static int8_t        pupilOffsetY  = 0;

// ── Posisi mata ──
// Layar 128x64, dua mata landscape kiri-kanan
// Mata kiri center: (38, 32)
// Mata kanan center: (90, 32)
#define EYE_L_X  38
#define EYE_R_X  90
#define EYE_Y    32
#define EYE_W    24   // lebar mata
#define EYE_H    20   // tinggi mata saat penuh terbuka

// ────────────────────────────────────────────
// Gambar satu mata dengan eyelid atas-bawah
// openH = tinggi bukaan saat ini (0=tutup, EYE_H=penuh)
// ────────────────────────────────────────────
void _eye(int16_t cx, int16_t cy,
          int16_t openH,
          int8_t  px, int8_t py) {

  if (openH <= 0) return;  // mata tertutup total — tidak gambar apapun

  int16_t hw = EYE_W / 2;
  int16_t hh = openH / 2;
  if (hh < 1) hh = 1;

  int16_t x0 = cx - hw;
  int16_t y0 = cy - hh;
  int16_t w  = EYE_W;
  int16_t h  = hh * 2;

  // Pastikan tidak keluar layar
  if (y0 < 0) { h += y0; y0 = 0; }
  if (y0 + h > 64) h = 64 - y0;
  if (h <= 0) return;

  // Fill putih (mata terbuka)
  u8g2.setDrawColor(1);
  u8g2.drawRBox(x0, y0, w, h, 4);

  // Pupil hitam — hanya gambar kalau mata cukup terbuka
  if (openH >= 6) {
    int16_t pr  = max(2, (int)hh - 3);
    if (pr > 7) pr = 7;
    int16_t pcx = cx + constrain((int)px, -(hw - pr - 2), (hw - pr - 2));
    int16_t pcy = cy + constrain((int)py, -(hh - pr - 1), (hh - pr - 1));

    // Klem pupil agar dalam batas area putih
    if (pcx - pr < x0 + 1)     pcx = x0 + 1 + pr;
    if (pcx + pr > x0 + w - 1) pcx = x0 + w - 1 - pr;
    if (pcy - pr < y0 + 1)     pcy = y0 + 1 + pr;
    if (pcy + pr > y0 + h - 1) pcy = y0 + h - 1 - pr;

    u8g2.setDrawColor(0);
    u8g2.drawDisc(pcx, pcy, pr);

    // Highlight
    u8g2.setDrawColor(1);
    u8g2.drawPixel(pcx + pr / 2, pcy - pr / 2);
  }

  u8g2.setDrawColor(1);
}

// ────────────────────────────────────────────
// Helper: gambar garis eyelid (tutup dari atas)
// fraction 0.0=tidak ada tutup, 1.0=tutup penuh
// ────────────────────────────────────────────
void _eyelid(int16_t cx, int16_t cy, float fraction) {
  if (fraction <= 0.0f) return;
  int16_t hw     = EYE_W / 2;
  int16_t lidH   = (int16_t)(EYE_H * fraction);
  int16_t y0     = cy - EYE_H / 2;
  u8g2.setDrawColor(0);
  u8g2.drawBox(cx - hw, y0, EYE_W, lidH);
  u8g2.setDrawColor(1);
}

// ────────────────────────────────────────────
// EKSPRESI
// ────────────────────────────────────────────

void _drawIdle(int16_t openH) {
  _eye(EYE_L_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);
  _eye(EYE_R_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);
}

void _drawHappy(int16_t openH) {
  // Mata ^ shape: gambar penuh lalu hapus bagian bawah
  _eye(EYE_L_X, EYE_Y, openH, 0, 0);
  _eye(EYE_R_X, EYE_Y, openH, 0, 0);
  // Hapus bagian bawah → bentuk ^
  int16_t cutY = EYE_Y;
  int16_t cutH = openH / 2 + 2;
  u8g2.setDrawColor(0);
  u8g2.drawBox(EYE_L_X - EYE_W/2, cutY, EYE_W, cutH);
  u8g2.drawBox(EYE_R_X - EYE_W/2, cutY, EYE_W, cutH);
  u8g2.setDrawColor(1);
  // Pipi
  if (openH > 8) {
    u8g2.drawDisc(14, 46, 3);
    u8g2.drawDisc(114, 46, 3);
  }
}

void _drawSad(int16_t openH) {
  int16_t sadH = max((int16_t)2, (int16_t)(openH * 6 / 10));
  _eye(EYE_L_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));
  _eye(EYE_R_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));
  // Alis sedih (miring ke luar-atas)
  if (openH > 6) {
    u8g2.drawLine(EYE_L_X - 10, EYE_Y - 14, EYE_L_X + 2, EYE_Y - 18);
    u8g2.drawLine(EYE_R_X + 10, EYE_Y - 14, EYE_R_X - 2, EYE_Y - 18);
  }
  // Air mata
  if (openH > 4) {
