// ────────────────────────────────────────────
//  HANDLER HTTP
// ────────────────────────────────────────────
void handleRoot() {
  server.send_P(200, "text/html", HTML_PAGE);
}

void handleCmd() {
  if (!server.hasArg("action")) {
    server.send(400, "text/plain", "no action");
    return;
  }
  String action = server.arg("action");

  if      (action == "forward")      pendingCommand = CMD_FORWARD;
  else if (action == "backward")     pendingCommand = CMD_BACKWARD;
  else if (action == "left")         pendingCommand = CMD_LEFT;
  else if (action == "right")        pendingCommand = CMD_RIGHT;
  else if (action == "stop")         pendingCommand = CMD_STOP;
  else if (action == "come")         pendingCommand = CMD_COME;
  else if (action == "follow")       pendingCommand = CMD_FOLLOW;
  else if (action == "dance")        pendingCommand = CMD_DANCE;
  else if (action == "expr_happy")   pendingCommand = CMD_EXPR_HAPPY;
  else if (action == "expr_sad")     pendingCommand = CMD_EXPR_SAD;
  else if (action == "expr_angry")   pendingCommand = CMD_EXPR_ANGRY;
  else if (action == "expr_scared")  pendingCommand = CMD_EXPR_SCARED;
  else if (action == "expr_sleepy")  pendingCommand = CMD_EXPR_SLEEPY;

  server.send(200, "text/plain", "ok");
}

void handleStatus() {
  // Buat JSON status
  String stateStr;
  switch (robotState) {
    case STATE_IDLE:    stateStr = "IDLE";    break;
    case STATE_HAPPY:   stateStr = "HAPPY";   break;
    case STATE_LONELY:  stateStr = "LONELY";  break;
    case STATE_ANNOYED: stateStr = "ANNOYED"; break;
    case STATE_SCARED:  stateStr = "SCARED";  break;
    case STATE_SLEEPY:  stateStr = "SLEEPY";  break;
    default:            stateStr = "IDLE";    break;
  }
  String json = "{\"state\":\"" + stateStr + "\","
                + "\"face\":"  + (faceDetected ? "true" : "false") + ","
                + "\"dist\":"  + String(obstacleDistCm) + ","
                + "\"follow\":" + (followMode ? "true" : "false") + "}";
  server.send(200, "application/json", json);
}

void handleNotFound() {
  server.send(404, "text/plain", "not found");
}

// ────────────────────────────────────────────
void wifiControllerBegin() {
  WiFi.softAP(WIFI_SSID, WIFI_PASS);
  server.on("/",       handleRoot);
  server.on("/cmd",    handleCmd);
  server.on("/status", handleStatus);
  server.onNotFound(handleNotFound);
  server.begin();
}

// Panggil di task WiFi
void wifiControllerHandle() {
  server.handleClient();
}

