/*
 * ══════════════════════════════════════════════════════
 *   ESP32-CAM — Face Detection Board
 *   Upload ke board: AI Thinker ESP32-CAM
 *
 *   Koneksi ke ESP32 utama:
 *     ESP32-CAM GPIO1 (TX) → ESP32 GPIO35 (RX1)
 *     GND → GND (wajib common ground!)
 *     5V  → 5V dari LM2596
 *
 *   Output Serial (115200 baud):
 *     "F,x,y\n"  = wajah terdeteksi di posisi x,y
 *     "N\n"       = tidak ada wajah
 *
 *   Cara upload ESP32-CAM:
 *     1. Sambung GPIO0 ke GND (mode flash)
 *     2. Upload via FTDI programmer (RX-TX, TX-RX, 3.3V, GND)
 *     3. Lepas GPIO0 dari GND setelah upload
 *     4. Reset
 * ══════════════════════════════════════════════════════
 */

#include "esp_camera.h"
#include "esp_timer.h"
#include "img_converters.h"
#include "Arduino.h"
#include "fb_gfx.h"
#include "esp_http_server.h"

// ── Konfigurasi pin AI Thinker ESP32-CAM ──
#define PWDN_GPIO_NUM     32
#define RESET_GPIO_NUM    -1
#define XCLK_GPIO_NUM      0
#define SIOD_GPIO_NUM     26
#define SIOC_GPIO_NUM     27
#define Y9_GPIO_NUM       35
#define Y8_GPIO_NUM       34
#define Y7_GPIO_NUM       39
#define Y6_GPIO_NUM       36
#define Y5_GPIO_NUM       21
#define Y4_GPIO_NUM       19
#define Y3_GPIO_NUM       18
#define Y2_GPIO_NUM        5
#define VSYNC_GPIO_NUM    25
#define HREF_GPIO_NUM     23
#define PCLK_GPIO_NUM     22

// LED flash (opsional, bisa di-disable)
#define LED_GPIO_NUM       4

// ── Ukuran frame ──
// QVGA = 320x240, cukup untuk face detection dan ringan
#define FRAME_W  320
#define FRAME_H  240

// ── Face detection sederhana dengan color/motion heuristic ──
// Karena esp-who perlu setup yang lebih kompleks,
// kita pakai pendekatan deteksi sederhana via brightness centroid
// yang cukup untuk mengarahkan servo

static camera_fb_t *fb = NULL;

bool initCamera() {
  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer   = LEDC_TIMER_0;
  config.pin_d0       = Y2_GPIO_NUM;
  config.pin_d1       = Y3_GPIO_NUM;
  config.pin_d2       = Y4_GPIO_NUM;
  config.pin_d3       = Y5_GPIO_NUM;
  config.pin_d4       = Y6_GPIO_NUM;
  config.pin_d5       = Y7_GPIO_NUM;
  config.pin_d6       = Y8_GPIO_NUM;
  config.pin_d7       = Y9_GPIO_NUM;
  config.pin_xclk     = XCLK_GPIO_NUM;
  config.pin_pclk     = PCLK_GPIO_NUM;
  config.pin_vsync    = VSYNC_GPIO_NUM;
  config.pin_href     = HREF_GPIO_NUM;
  config.pin_sscb_sda = SIOD_GPIO_NUM;
  config.pin_sscb_scl = SIOC_GPIO_NUM;
  config.pin_pwdn     = PWDN_GPIO_NUM;
  config.pin_reset    = RESET_GPIO_NUM;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_GRAYSCALE;  // Grayscale lebih ringan
  config.frame_size   = FRAMESIZE_QVGA;       // 320x240
  config.jpeg_quality = 10;
  config.fb_count     = 1;

  esp_err_t err = esp_camera_init(&config);
  return (err == ESP_OK);
}

// ── Deteksi "blob cerah" sebagai proxy wajah ──
// Metode: cari region dengan pixel terang yang terkumpul
// Tidak seakurat Haar Cascade tapi jalan tanpa library tambahan
bool detectBrightBlob(int &outX, int &outY) {
  fb = esp_camera_fb_get();
  if (!fb) return false;

  uint8_t *buf = fb->buf;
  int     w    = fb->width;
  int     h    = fb->height;

  // Threshold brightness
  const uint8_t THRESH = 140;
  long sumX = 0, sumY = 0, count = 0;

  // Sample setiap 4 pixel untuk kecepatan
  for (int y = 20; y < h - 20; y += 4) {
    for (int x = 20; x < w - 20; x += 4) {
      uint8_t px = buf[y * w + x];
      if (px > THRESH) {
        sumX  += x;
        sumY  += y;
        count++;
      }
    }
  }

  esp_camera_fb_return(fb);
  fb = NULL;

  if (count > 80) {   // minimal 80 pixel terang dianggap ada objek
    outX = (int)(sumX / count);
    outY = (int)(sumY / count);
    return true;
  }
  return false;
}

void setup() {
  Serial.begin(115200);

  // Matikan LED flash agar tidak ganggu kamera
  pinMode(LED_GPIO_NUM, OUTPUT);
  digitalWrite(LED_GPIO_NUM, LOW);

  if (!initCamera()) {
    Serial.println("CAM_ERR");
    // Coba terus
    while (true) {
      delay(5000);
      if (initCamera()) break;
    }
  }
  Serial.println("CAM_OK");
}

unsigned long prevSendMs = 0;

void loop() {
  // Kirim data setiap 80ms (~12fps)
  unsigned long now = millis();
  if (now - prevSendMs < 80) return;
  prevSendMs = now;

  int fx = 0, fy = 0;
  if (detectBrightBlob(fx, fy)) {
    // Format: "F,x,y\n"
    Serial.print("F,");
    Serial.print(fx);
    Serial.print(",");
    Serial.println(fy);
  } else {
    Serial.println("N");
  }
}esp 32 cam

