- HC-SR04

- DFPlayer Mini + Speaker 1W

- LM2596 step-down 11.1V → 5V

- ESP32-CAM (board terpisah, UART komunikasi)

Library yang dibutuhkan (install via Library Manager):

- Adafruit SSD1306

- Adafruit GFX Library

- ESP32Servo

- DFRobotDFPlayerMini

- NewPing

══════════════════════════════════════════════════════


*/

// Urutan include PENTING — jangan diubah

#include "FaceAnimator.h"

#include "HeadMotion.h"

#include "Movement.h"

#include "AudioPlayer.h"

#include "StateMachine.h"

#include "WiFiController.h"

// ── HC-SR04 ──

#include <NewPing.h>

#define PIN_TRIG    18

#define PIN_ECHO    19

#define SONAR_MAX   200

NewPing sonar(PIN_TRIG, PIN_ECHO, SONAR_MAX);

// ── ESP32-CAM komunikasi via UART ──

// ESP32-CAM TX → ESP32 GPIO3 (RX0) — gunakan Serial (UART0) hanya untuk debug

// Lebih baik pakai Serial1 agar tidak konflik dengan Serial monitor

#define CAM_SERIAL_RX  35   // ESP32 terima data dari CAM

#define CAM_SERIAL_TX  -1   // tidak perlu kirim ke CAM (hanya terima)

HardwareSerial camSerial(1);  // UART1

// ── Timing loop ──

unsigned long prevFaceMs   = 0;

unsigned long prevSonarMs  = 0;

unsigned long prevStateMs  = 0;

unsigned long prevHeadMs   = 0;

unsigned long prevFaceRenderMs = 0;

unsigned long prevMotorMs  = 0;

// ══════════════════════════════════════════════════════

//  TASK WIFI — berjalan di Core 1

// ══════════════════════════════════════════════════════

void taskWiFi(void *param) {

wifiControllerBegin();

for (;;) {

wifiControllerHandle();

vTaskDelay(10 / portTICK_PERIOD_MS);

}

}

// ══════════════════════════════════════════════════════

//  PARSE DATA DARI ESP32-CAM

//  Format: "F,x,y\n"  = wajah ditemukan di koordinat x,y

//          "N\n"       = tidak ada wajah

// ══════════════════════════════════════════════════════

void parseCamData() {

if (!camSerial.available()) return;

String line = camSerial.readStringUntil('\n');

line.trim();

if (line.startsWith("F,")) {

// Parse x,y

int comma1 = line.indexOf(',');

int comma2 = line.indexOf(',', comma1 + 1);

if (comma1 > 0 && comma2 > comma1) {

  int x = line.substring(comma1 + 1, comma2).toInt();

  int y = line.substring(comma2 + 1).toInt();

  faceDetected = true;

  faceX        = x;

  faceY        = y;

}

} else if (line == "N") {

faceDetected = false;

}

}

// ══════════════════════════════════════════════════════

//  SETUP

// ══════════════════════════════════════════════════════

void setup() {

Serial.begin(115200);

Serial.println("\n[N.O.V.A] Booting...");

// UART ke ESP32-CAM

camSerial.begin(115200, SERIAL_8N1, CAM_SERIAL_RX, -1);

// Init OLED

if (!faceBegin()) {

Serial.println("[N.O.V.A] OLED gagal! Cek wiring SDA/SCL dan alamat 0x3C");

} else {

Serial.println("[N.O.V.A] OLED OK");

}

// Init servo

headBegin();

Serial.println("[N.O.V.A] Servo OK");

// Init motor

movementBegin();

Serial.println("[N.O.V.A] Motor OK");

// Init DFPlayer

if (!audioBegin()) {

Serial.println("[N.O.V.A] DFPlayer gagal atau tidak ada SD card");

} else {

Serial.println("[N.O.V.A] DFPlayer OK");

}

// Init state machine

stateMachineBegin();

Serial.println("[N.O.V.A] State machine OK");

// WiFi task di Core 1

xTaskCreatePinnedToCore(

taskWiFi,      // fungsi task

"WiFiTask",    // nama

8192,          // stack size

NULL,          // parameter

1,             // prioritas

NULL,          // handle

1              // Core 1

);

Serial.println("[N.O.V.A] WiFi task started");

Serial.println("[N.O.V.A] SSID: N.O.V.A | Pass: nova12345");

Serial.println("[N.O.V.A] IP: 192.168.4.1");

Serial.println("[N.O.V.A] Ready!");

}

// ══════════════════════════════════════════════════════

//  LOOP — berjalan di Core 0 (Autonomous Core)

// ══════════════════════════════════════════════════════

void loop() {

unsigned long now = millis();

// ── Baca kamera setiap 30ms ──

if (now - prevFaceMs >= 30) {

prevFaceMs = now;

parseCamData();

}

// ── Baca sonar setiap 60ms ──

if (now - prevSonarMs >= 60) {

prevSonarMs = now;

unsigned int dist = sonar.ping_cm();

// Jika gagal baca

if (dist == 0 || dist > 200) {

  dist = 200;

}

// Inisialisasi awal

if (stableDistCm == 999) {

  stableDistCm = dist;

}

// Smooth filter

stableDistCm = (stableDistCm * 3 + dist) / 4;

obstacleDistCm = stableDistCm;

Serial.print("SONAR: ");

Serial.println(obstacleDistCm);

}

// ── Update state machine setiap 50ms ──

if (now - prevStateMs >= 50) {

prevStateMs = now;

stateMachineUpdate();

}

// ── Update servo head setiap 20ms ──

if (now - prevHeadMs >= 20) {

prevHeadMs = now;

headUpdate();

// Sinkronkan pupil dengan posisi servo

faceSetPupil(headGetPan(), headGetTilt());

}

// ── Update motor setiap 30ms ──

if (now - prevMotorMs >= 30) {

prevMotorMs = now;

movementUpdate();

}

// ── Render wajah OLED setiap 50ms (~20fps) ──

if (now - prevFaceRenderMs >= 50) {

prevFaceRenderMs = now;

faceRender();

}

}

#ifndef AUDIO_PLAYER_H

#define AUDIO_PLAYER_H

#include <DFRobotDFPlayerMini.h>

#include <HardwareSerial.h>

// ── Pin DFPlayer ──

// DFPlayer TX → ESP32 GPIO16 (RX2)

// DFPlayer RX → ESP32 GPIO17 (TX2) via resistor 1k

#define DFPLAYER_RX  16

#define DFPLAYER_TX  17

HardwareSerial dfSerial(2);   // UART2

DFRobotDFPlayerMini dfPlayer;

static bool dfReady = false;

// ── Nomor track di microSD ──

// Simpan file MP3 di folder /mp3/ dengan nama 0001.mp3 dst

// atau langsung di root: 001.mp3, 002.mp3, ...

#define SFX_HAPPY     1   // suara senang / "yay"

#define SFX_SAD       2   // suara sedih / "hmm"

#define SFX_ANGRY     3   // suara kesal / "grr"

#define SFX_SCARED    4   // suara kaget / "aah!"

#define SFX_SLEEPY    5   // suara ngantuk / "zzz"

#define SFX_IDLE_1    6   // "hmm..." random idle

#define SFX_IDLE_2    7   // "oh..." random idle

#define SFX_IDLE_3    8   // suara kecil random

#define SFX_GREET     9   // saat dipanggil / sambut

#define SFX_CONFUSED  10  // "huh?"

// ────────────────────────────────────────────

bool audioBegin() {

dfSerial.begin(9600, SERIAL_8N1, DFPLAYER_RX, DFPLAYER_TX);

delay(1000);

if (!dfPlayer.begin(dfSerial, true, true)) {

dfReady = false;

return false;

}

dfPlayer.volume(20);   // Volume 0-30

dfReady = true;

return true;

}

void audioPlay(uint8_t track) {

if (!dfReady) return;

dfPlayer.play(track);

}

void audioPlayIdle() {

if (!dfReady) return;

// Pilih random dari 3 suara idle

uint8_t t = random(SFX_IDLE_1, SFX_IDLE_3 + 1);

dfPlayer.play(t);

}

void audioSetVolume(uint8_t vol) {

if (!dfReady) return;

dfPlayer.volume(constrain(vol, 0, 30));

}

void audioStop() {

if (!dfReady) return;

dfPlayer.stop();

}

bool audioIsReady() { return dfReady; }

#endif // AUDIO_PLAYER_H

#ifndef HEAD_MOTION_H

#define HEAD_MOTION_H

#include <ESP32Servo.h>

// ── Pin Servo ──

#define PIN_SERVO_PAN   4

#define PIN_SERVO_TILT  5

// ── Range Sudut ──

#define PAN_MIN    30

#define PAN_MAX   150

#define PAN_CENTER 90

#define TILT_MIN   60

#define TILT_MAX  120

#define TILT_CENTER 90

Servo servoPan;

Servo servoTilt;

// State sudut saat ini & target

static float panCurrent  = PAN_CENTER;

static float tiltCurrent = TILT_CENTER;

static float panTarget   = PAN_CENTER;

static float tiltTarget  = TILT_CENTER;

// Idle motion

static float   idlePanOffset  = 0;

static float   idleTiltOffset = 0;

static int8_t  idlePanDir     = 1;

static int8_t  idleTiltDir    = 1;

static unsigned long lastIdleUpdateMs = 0;

static bool    idleMotionEnabled = true;

// ────────────────────────────────────────────

void headBegin() {

ESP32PWM::allocateTimer(0);

ESP32PWM::allocateTimer(1);

servoPan.setPeriodHertz(50);

servoTilt.setPeriodHertz(50);

servoPan.attach(PIN_SERVO_PAN,   500, 2400);

servoTilt.attach(PIN_SERVO_TILT, 500, 2400);

servoPan.write(PAN_CENTER);

servoTilt.write(TILT_CENTER);

panCurrent  = PAN_CENTER;

tiltCurrent = TILT_CENTER;

panTarget   = PAN_CENTER;

tiltTarget  = TILT_CENTER;

}

// Set target sudut — servo akan bergerak smooth

void headSetTarget(int pan, int tilt) {

panTarget  = constrain(pan,  PAN_MIN,  PAN_MAX);

tiltTarget = constrain(tilt, TILT_MIN, TILT_MAX);

}

void headCenter() {

headSetTarget(PAN_CENTER, TILT_CENTER);

}

void headLookLeft()  { headSetTarget(PAN_MIN + 20, TILT_CENTER); }

void headLookRight() { headSetTarget(PAN_MAX - 20, TILT_CENTER); }

void headLookUp()    { headSetTarget(PAN_CENTER, TILT_MIN + 10); }

void headLookDown()  { headSetTarget(PAN_CENTER, TILT_MAX - 10); }

// Geleng-geleng (untuk state ANNOYED)

static int   shakeCount = 0;

static bool  shakeActive = false;

static unsigned long lastShakeMs = 0;

void headShake() {

shakeActive = true;

shakeCount  = 0;

idleMotionEnabled = false;

}

// Ganti pupil di FaceAnimator sesuai posisi servo

int headGetPan()  { return (int)panCurrent;  }

int headGetTilt() { return (int)tiltCurrent; }

void headEnableIdle(bool en) { idleMotionEnabled = en; }

// ────────────────────────────────────────────

// Update — panggil di loop() setiap ~20ms

// ────────────────────────────────────────────

void headUpdate() {

unsigned long now = millis();

// Shake animation

if (shakeActive) {

if (now - lastShakeMs > 120) {

  lastShakeMs = now;

  shakeCount++;

  if (shakeCount % 2 == 0)

    panTarget = PAN_CENTER - 25;

  else

    panTarget = PAN_CENTER + 25;

  if (shakeCount >= 6) {

    shakeActive = false;

    panTarget   = PAN_CENTER;

    idleMotionEnabled = true;

  }

}

}

// Idle motion (±3° lambat)

if (idleMotionEnabled && !shakeActive && (now - lastIdleUpdateMs > 80)) {

lastIdleUpdateMs = now;

idlePanOffset  += idlePanDir  * 0.4f;

idleTiltOffset += idleTiltDir * 0.2f;

if (idlePanOffset  >  3.0f || idlePanOffset  < -3.0f) idlePanDir  *= -1;

if (idleTiltOffset >  2.0f || idleTiltOffset < -2.0f) idleTiltDir *= -1;

}

float effectivePan  = panTarget  + (idleMotionEnabled ? idlePanOffset  : 0);

float effectiveTilt = tiltTarget + (idleMotionEnabled ? idleTiltOffset : 0);

effectivePan  = constrain(effectivePan,  (float)PAN_MIN,  (float)PAN_MAX);

effectiveTilt = constrain(effectiveTilt, (float)TILT_MIN, (float)TILT_MAX);

// Easing (lerp factor 0.12)

panCurrent  += (effectivePan  - panCurrent)  * 0.12f;

tiltCurrent += (effectiveTilt - tiltCurrent) * 0.12f;

servoPan.write((int)panCurrent);

servoTilt.write((int)tiltCurrent);

}

// Tracking wajah dari koordinat kamera

// faceX, faceY: 0-320, 0-240 (resolusi OV2640 QVGA)

void headTrackFace(int faceX, int faceY) {

idleMotionEnabled = false;

int centerX = 160, centerY = 120;

int errX = faceX - centerX;

int errY = faceY - centerY;

int newPan  = (int)panTarget  - (errX / 20);

int newTilt = (int)tiltTarget + (errY / 25);

headSetTarget(newPan, newTilt);

}

void headStopTracking() {

idleMotionEnabled = true;

}

