//  HANDLER HTTP

// ────────────────────────────────────────────

void handleRoot() {

server.send_P(200, "text/html", HTML_PAGE);

}

void handleCmd() {

if (!server.hasArg("action")) {

server.send(400, "text/plain", "no action");

return;

}

String action = server.arg("action");

if      (action == "forward")      pendingCommand = CMD_FORWARD;

else if (action == "backward")     pendingCommand = CMD_BACKWARD;

else if (action == "left")         pendingCommand = CMD_LEFT;

else if (action == "right")        pendingCommand = CMD_RIGHT;

else if (action == "stop")         pendingCommand = CMD_STOP;

else if (action == "come")         pendingCommand = CMD_COME;

else if (action == "follow")       pendingCommand = CMD_FOLLOW;

else if (action == "dance")        pendingCommand = CMD_DANCE;

else if (action == "expr_happy")   pendingCommand = CMD_EXPR_HAPPY;

else if (action == "expr_sad")     pendingCommand = CMD_EXPR_SAD;

else if (action == "expr_angry")   pendingCommand = CMD_EXPR_ANGRY;

else if (action == "expr_scared")  pendingCommand = CMD_EXPR_SCARED;

else if (action == "expr_sleepy")  pendingCommand = CMD_EXPR_SLEEPY;

server.send(200, "text/plain", "ok");

}

void handleStatus() {

// Buat JSON status

String stateStr;

switch (robotState) {

case STATE_IDLE:    stateStr = "IDLE";    break;

case STATE_HAPPY:   stateStr = "HAPPY";   break;

case STATE_LONELY:  stateStr = "LONELY";  break;

case STATE_ANNOYED: stateStr = "ANNOYED"; break;

case STATE_SCARED:  stateStr = "SCARED";  break;

case STATE_SLEEPY:  stateStr = "SLEEPY";  break;

default:            stateStr = "IDLE";    break;

}

String json = "{"state":"" + stateStr + "","

+ "\"face\":"  + (faceDetected ? "true" : "false") + ","

            + "\"dist\":"  + String(obstacleDistCm) + ","

            + "\"follow\":" + (followMode ? "true" : "false") + "}";

server.send(200, "application/json", json);

}

void handleNotFound() {

server.send(404, "text/plain", "not found");

}

// ────────────────────────────────────────────

void wifiControllerBegin() {

WiFi.softAP(WIFI_SSID, WIFI_PASS);

server.on("/",       handleRoot);

server.on("/cmd",    handleCmd);

server.on("/status", handleStatus);

server.onNotFound(handleNotFound);

server.begin();

}

// Panggil di task WiFi

void wifiControllerHandle() {

server.handleClient();

}

#endif // WIFI_CONTROLLER_H#ifndef MOVEMENT_H

#define MOVEMENT_H

// ── Pin L298N ──

#define PIN_IN1  14   // Motor kiri

#define PIN_IN2  27

#define PIN_IN3  26   // Motor kanan

#define PIN_IN4  25

#define PIN_ENA  32   // PWM kiri  (opsional — bisa jumper ke 5V di L298N)

#define PIN_ENB  33   // PWM kanan (opsional)

// LEDC channel untuk PWM ESP32

#define PWM_FREQ   1000

#define PWM_RES    8       // 8-bit = 0-255

#define CH_ENA     2

#define CH_ENB     3

// ── Kecepatan ──

#define SPEED_DEFAULT   85

#define SPEED_SLOW      55

#define SPEED_TURN      70

// Koreksi arah lurus

#define MOTOR_LEFT_TRIM    0

#define MOTOR_RIGHT_TRIM  -5

// Ramp

#define RAMP_STEP          2

#define RAMP_INTERVAL_MS  20

static int  currentSpeedL = 0;

static int  currentSpeedR = 0;

static int  targetSpeedL  = 0;

static int  targetSpeedR  = 0;

static unsigned long lastRampMs = 0;

// ────────────────────────────────────────────

void movementBegin() {

pinMode(PIN_IN1, OUTPUT);

pinMode(PIN_IN2, OUTPUT);

pinMode(PIN_IN3, OUTPUT);

pinMode(PIN_IN4, OUTPUT);

// ESP32 core v3.x — API baru (ledcAttach menggantikan ledcSetup+ledcAttachPin)

ledcAttach(PIN_ENA, PWM_FREQ, PWM_RES);

ledcAttach(PIN_ENB, PWM_FREQ, PWM_RES);

ledcWrite(PIN_ENA, 0);

ledcWrite(PIN_ENB, 0);

digitalWrite(PIN_IN1, LOW);

digitalWrite(PIN_IN2, LOW);

digitalWrite(PIN_IN3, LOW);

digitalWrite(PIN_IN4, LOW);

}

// Mengirim arah dan kecepatan motor ke driver L298N

void _setMotors(int speedL, int speedR) {

// Motor kiri

if (speedL > 0) {

digitalWrite(PIN_IN1, HIGH);

digitalWrite(PIN_IN2, LOW);

}

else if (speedL < 0) {

digitalWrite(PIN_IN1, LOW);

digitalWrite(PIN_IN2, HIGH);

}

else {

digitalWrite(PIN_IN1, LOW);

digitalWrite(PIN_IN2, LOW);

}

// Motor kanan

if (speedR > 0) {

digitalWrite(PIN_IN3, HIGH);

digitalWrite(PIN_IN4, LOW);

}

else if (speedR < 0) {

digitalWrite(PIN_IN3, LOW);

digitalWrite(PIN_IN4, HIGH);

}

else {

digitalWrite(PIN_IN3, LOW);

digitalWrite(PIN_IN4, LOW);

}

int pwmL = constrain(abs(speedL) + MOTOR_LEFT_TRIM, 0, 255);

int pwmR = constrain(abs(speedR) + MOTOR_RIGHT_TRIM, 0, 255);

ledcWrite(PIN_ENA, pwmL);

ledcWrite(PIN_ENB, pwmR);

}

// ────────────────────────────────────────────

// Perintah gerak — set target, ramp dihandle di update()

void moveForward(int speed = SPEED_DEFAULT) {

targetSpeedL =  speed;

targetSpeedR =  speed;

}

void moveBackward(int speed = SPEED_DEFAULT) {

targetSpeedL = -speed;

targetSpeedR = -speed;

}

void turnLeft(int speed = SPEED_TURN) {

targetSpeedL = speed * 0.45;

targetSpeedR = speed;

}

void turnRight(int speed = SPEED_TURN) {

targetSpeedL = speed;

targetSpeedR = speed * 0.45;

}

void spinLeft(int speed = SPEED_TURN) {

targetSpeedL = -speed;

targetSpeedR = speed;

}

void spinRight(int speed = SPEED_TURN) {

targetSpeedL = speed;

targetSpeedR = -speed;

}

void moveStop() {

targetSpeedL = 0;

targetSpeedR = 0;

}

// Dance move — sequence sederhana

static uint8_t  danceStep    = 0;

static bool     danceActive  = false;

static unsigned long danceMs = 0;

void moveDance() {

danceActive = true;

danceStep   = 0;

danceMs     = millis();

}

// ────────────────────────────────────────────

// Update — panggil di loop() tiap ~30ms

// ────────────────────────────────────────────

void movementUpdate() {

unsigned long now = millis();

// Dance sequence

if (danceActive) {

if (now - danceMs > 400) {

  danceMs = now;

  danceStep++;

  switch (danceStep) {

      case 0: targetSpeedL =  80; targetSpeedR =  80; break;

      case 1: targetSpeedL = -80; targetSpeedR = -80; break;

      case 2: targetSpeedL =  70; targetSpeedR = -70; break;

      case 3: targetSpeedL = -70; targetSpeedR =  70; break;

      case 4: targetSpeedL =  80; targetSpeedR =  80; break;

      case 5: targetSpeedL = -80; targetSpeedR = -80; break;

      case 6: targetSpeedL =  70; targetSpeedR = -70; break;

      case 7: targetSpeedL =   0; targetSpeedR =   0; 

      danceActive = false;

      danceStep = 0;

      break;

  }

}

}

// Ramp speed (akselerasi halus)

if (now - lastRampMs >= RAMP_INTERVAL_MS) {

lastRampMs = now;

if (currentSpeedL < targetSpeedL)

currentSpeedL = min(currentSpeedL + RAMP_STEP, targetSpeedL);

else if (currentSpeedL > targetSpeedL)

currentSpeedL = max(currentSpeedL - RAMP_STEP, targetSpeedL);

if (currentSpeedR < targetSpeedR)

currentSpeedR = min(currentSpeedR + RAMP_STEP, targetSpeedR);

else if (currentSpeedR > targetSpeedR)

currentSpeedR = max(currentSpeedR - RAMP_STEP, targetSpeedR);

_setMotors(currentSpeedL, currentSpeedR);

}

}

bool isDancing() { return danceActive; }

bool isMoving()  { return (currentSpeedL != 0 || currentSpeedR != 0); }

#endif // MOVEMENT_H

#ifndef FACE_ANIMATOR_H

#define FACE_ANIMATOR_H

#include <Arduino.h>

#include <Wire.h>

#include <U8g2lib.h>

// SH1106 128x64

U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

typedef enum {

EXPR_IDLE,

EXPR_HAPPY,

EXPR_SAD,

EXPR_ANGRY,

EXPR_SCARED,

EXPR_SLEEPY,

EXPR_BLINK,

EXPR_CONFUSED

} Expression;

static Expression    currentExpr   = EXPR_IDLE;

static bool          isBlinking    = false;

static uint8_t       blinkPhase    = 0;  // 0=tutup 1=tahan 2=buka

static unsigned long lastBlinkMs   = 0;

static unsigned long blinkInterval = 4000;

static int8_t        pupilOffsetX  = 0;

static int8_t        pupilOffsetY  = 0;

// ── Posisi mata ──

// Layar 128x64, dua mata landscape kiri-kanan

// Mata kiri center: (38, 32)

// Mata kanan center: (90, 32)

#define EYE_L_X  38

#define EYE_R_X  90

#define EYE_Y    32

#define EYE_W    24   // lebar mata

#define EYE_H    20   // tinggi mata saat penuh terbuka

// ────────────────────────────────────────────

// Gambar satu mata dengan eyelid atas-bawah

// openH = tinggi bukaan saat ini (0=tutup, EYE_H=penuh)

// ────────────────────────────────────────────

void _eye(int16_t cx, int16_t cy,

int16_t openH,

      int8_t  px, int8_t py) {

if (openH <= 1) {

u8g2.drawLine(

      cx - EYE_W/2,

      cy,

      cx + EYE_W/2,

      cy

  );

  return;

}  // MATA TIDAK TERTUTUP TOTAL, ADA GARIS

int16_t hw = EYE_W / 2;

int16_t hh = openH / 2;

if (hh < 1) hh = 1;

int16_t x0 = cx - hw;

int16_t y0 = cy - hh;

int16_t w  = EYE_W;

int16_t h  = hh * 2;

// Pastikan tidak keluar layar

if (y0 < 0) { h += y0; y0 = 0; }

if (y0 + h > 64) h = 64 - y0;

if (h <= 0) return;

// Fill putih (mata terbuka)

u8g2.setDrawColor(1);

uint8_t radius = min(4, h / 2);

if (radius < 1) radius = 1;

u8g2.drawRBox(x0, y0, w, h, radius);

// Pupil hitam — hanya gambar kalau mata cukup terbuka

if (openH >= 6) {

int16_t pr  = max(2, (int)hh - 3);

if (pr > 7) pr = 7;

int16_t pcx = cx + constrain((int)px, -(hw - pr - 2), (hw - pr - 2));

int16_t pcy = cy + constrain((int)py, -(hh - pr - 1), (hh - pr - 1));



// Klem pupil agar dalam batas area putih

if (pcx - pr < x0 + 1)     pcx = x0 + 1 + pr;

if (pcx + pr > x0 + w - 1) pcx = x0 + w - 1 - pr;

if (pcy - pr < y0 + 1)     pcy = y0 + 1 + pr;

if (pcy + pr > y0 + h - 1) pcy = y0 + h - 1 - pr;



u8g2.setDrawColor(0);

u8g2.drawDisc(pcx, pcy, pr);



// Highlight

u8g2.setDrawColor(1);

u8g2.drawPixel(pcx + pr / 2, pcy - pr / 2);

}

u8g2.setDrawColor(1);

}

// ────────────────────────────────────────────

// Helper: gambar garis eyelid (tutup dari atas)

// fraction 0.0=tidak ada tutup, 1.0=tutup penuh

// ────────────────────────────────────────────

void _eyelid(int16_t cx, int16_t cy, float fraction) {

if (fraction <= 0.0f) return;

int16_t hw     = EYE_W / 2;

int16_t lidH   = (int16_t)(EYE_H * fraction);

int16_t y0     = cy - EYE_H / 2;

u8g2.setDrawColor(0);

u8g2.drawBox(cx - hw, y0, EYE_W, lidH);

u8g2.setDrawColor(1);

}

// ────────────────────────────────────────────

// EKSPRESI

// ────────────────────────────────────────────

void _drawIdle(int16_t openH) {

_eye(EYE_L_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);

_eye(EYE_R_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);

}

void _drawHappy(int16_t openH) {

// Mata ^ shape: gambar penuh lalu hapus bagian bawah

_eye(EYE_L_X, EYE_Y, openH, 0, 0);

_eye(EYE_R_X, EYE_Y, openH, 0, 0);

// Hapus bagian bawah → bentuk ^

int16_t cutY = EYE_Y;

int16_t cutH = openH / 2 + 2;

u8g2.setDrawColor(0);

u8g2.drawBox(EYE_L_X - EYE_W/2, cutY, EYE_W, cutH);

u8g2.drawBox(EYE_R_X - EYE_W/2, cutY, EYE_W, cutH);

u8g2.setDrawColor(1);

// Pipi

if (openH > 8) {

u8g2.drawDisc(14, 46, 3);

u8g2.drawDisc(114, 46, 3);

}

}

void _drawSad(int16_t openH) {

int16_t sadH = max((int16_t)2, (int16_t)(openH * 6 / 10));

_eye(EYE_L_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));

_eye(EYE_R_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));

// Alis sedih (miring ke luar-atas)

if (openH > 6) {

u8g2.drawLine(EYE_L_X - 10, EYE_Y - 14, EYE_L_X + 2, EYE_Y - 18);

u8g2.drawLine(EYE_R_X + 10, EYE_Y - 14, EYE_R_X - 2, EYE_Y - 18);

}

// Air mata

if (openH > 4) {

u8g2.drawLine(EYE_L_X - 4, EYE_Y + sadH/2 + 1, EYE_L_X - 6, EYE_Y + sadH/2 + 8);

u8g2.drawLine(EYE_R_X - 4, EYE_Y + sadH/2 + 1, EYE_R_X - 6, EYE_Y + sadH/2 + 8);

}

}

void _drawAngry(int16_t openH) {

int16_t angryH = max((int16_t)2, (int16_t)(openH * 55 / 100));

_eye(EYE_L_X, EYE_Y, angryH, pupilOffsetX, pupilOffsetY);

_eye(EYE_R_X, EYE_Y, angryH, pupilOffsetX, pupilOffsetY);

// Alis marah (miring ke dalam-bawah)

if (openH > 4) {

u8g2.drawLine(EYE_L_X - 12, EYE_Y - 16, EYE_L_X + 4, EYE_Y - 11);

u8g2.drawLine(EYE_L_X - 12, EYE_Y - 15, EYE_L_X + 4, EYE_Y - 10);

u8g2.drawLine(EYE_R_X + 12, EYE_Y - 16, EYE_R_X - 4, EYE_Y - 11);

u8g2.drawLine(EYE_R_X + 12, EYE_Y - 15, EYE_R_X - 4, EYE_Y - 10);

}

}

void _drawScared(int16_t openH) {

// Mata sangat besar + sedikit oval

int16_t bigH = min((int16_t)(openH * 130 / 100), (int16_t)26);

_eye(EYE_L_X, EYE_Y, bigH, 0, 0);

_eye(EYE_R_X, EYE_Y, bigH, 0, 0);

// Mulut gemetar

if (openH > 4) {

for (int x = 44; x < 85; x += 5) {

  u8g2.drawLine(x, 55, x + 2, 58);

  u8g2.drawLine(x + 2, 58, x + 5, 55);

}

}

}

void _drawSleepy(int16_t openH) {

// Sleepy: mata hanya terbuka 35% dari tinggi normal

// Gambar langsung dengan tinggi kecil — tidak pakai eyelid overlay

int16_t sleepH = EYE_H * 35 / 100;

// Gambar mata dengan tinggi sleepH, diposisikan di bagian BAWAH

// (kelopak atas menutup dari atas ke bawah)

int16_t hw = EYE_W / 2;

// Mata kiri

int16_t yBot = EYE_Y + EYE_H / 2;   // batas bawah mata

int16_t yTop = yBot - sleepH;        // batas atas = dari bawah ke atas sebesar sleepH

u8g2.setDrawColor(1);

u8g2.drawRBox(EYE_L_X - hw, yTop, EYE_W, sleepH, 3);

// Pupil

if (sleepH >= 4) {

int16_t pr = max(2, sleepH / 2 - 1);

u8g2.setDrawColor(0);

u8g2.drawDisc(EYE_L_X, yTop + sleepH / 2 + 1, pr);

u8g2.setDrawColor(1);

}

// Mata kanan

u8g2.setDrawColor(1);

u8g2.drawRBox(EYE_R_X - hw, yTop, EYE_W, sleepH, 3);

if (sleepH >= 4) {

int16_t pr = max(2, sleepH / 2 - 1);

u8g2.setDrawColor(0);

u8g2.drawDisc(EYE_R_X, yTop + sleepH / 2 + 1, pr);

u8g2.setDrawColor(1);

}

// ZZZ di pojok kanan atas

u8g2.setFont(u8g2_font_6x10_tr);

u8g2.setDrawColor(1);

u8g2.drawStr(104, 20, "z");

u8g2.drawStr(110, 12, "Z");

}

void _drawConfused(int16_t openH) {

_eye(EYE_L_X, EYE_Y,     openH,          -2, 0);

_eye(EYE_R_X, EYE_Y - 2, openH * 7 / 10,  2, -2);

u8g2.setFont(u8g2_font_6x10_tr);

u8g2.setDrawColor(1);

u8g2.drawStr(60, 58, "?");

}

// ────────────────────────────────────────────

//  PUBLIC API

// ────────────────────────────────────────────

bool faceBegin() {

u8g2.begin();

u8g2.setDrawColor(1);

u8g2.clearBuffer();

u8g2.sendBuffer();

return true;

}

void faceSetPupil(int panAngle, int tiltAngle) {

pupilOffsetX = (int8_t)map(panAngle,  0, 180, -5, 5);

pupilOffsetY = (int8_t)map(tiltAngle, 0, 180, -3, 3);

}

void faceSetExpression(Expression expr) {

currentExpr = expr;

}

void faceBlink() {

if (!isBlinking) {

isBlinking  = true;

blinkPhase  = 0;

lastBlinkMs = millis();

}

}

void faceRender() {

unsigned long now = millis();

// ── Auto blink ──

if (

currentExpr != EXPR_SLEEPY &&

  !isBlinking &&

  (now - lastBlinkMs > blinkInterval)) { 

isBlinking    = true;

blinkPhase    = 0;

lastBlinkMs   = now;

blinkInterval = (unsigned long)random(3500, 6000);

}

// ── Hitung openH saat ini ──

// openH = tinggi bukaan mata dalam pixel (0..EYE_H)

int16_t openH = EYE_H;  // default: penuh terbuka

if (isBlinking) {

unsigned long el = now - lastBlinkMs;

if (blinkPhase == 0) {

  // Tutup: 100ms

  float t = (float)el / 100.0f;

  openH = (int16_t)(EYE_H * (1.0f - t));

  if (el >= 100) { blinkPhase = 1; lastBlinkMs = now; openH = 0; }

} else if (blinkPhase == 1) {

  // Tahan tutup: 60ms

  openH = 0;

  if (el >= 60) { blinkPhase = 2; lastBlinkMs = now; }

} else {

  // Buka: 130ms

  float t = (float)el / 130.0f;

  openH = (int16_t)(EYE_H * t);

  if (el >= 130) { isBlinking = false; openH = EYE_H; }

}

openH = constrain(openH, 0, EYE_H);

}

// ── Draw frame ──

u8g2.clearBuffer();

u8g2.setDrawColor(1);

switch (currentExpr) {

case EXPR_IDLE:     _drawIdle(openH);     break;

case EXPR_HAPPY:    _drawHappy(openH);    break;

case EXPR_SAD:      _drawSad(openH);      break;

case EXPR_ANGRY:    _drawAngry(openH);    break;

case EXPR_SCARED:   _drawScared(openH);   break;

case EXPR_SLEEPY:   _drawSleepy(openH);   break;

case EXPR_CONFUSED: _drawConfused(openH); break;

case EXPR_BLINK:    _drawIdle(openH);     break;

default:            _drawIdle(openH);     break;

}

u8g2.sendBuffer();

}

#endif // FACE_ANIMATOR_H

/*

══════════════════════════════════════════════════════

ESP32-CAM — Face Detect + Live MJPEG Stream

Upload ke board: AI Thinker ESP32-CAM

Koneksi ke ESP32 utama:

ESP32-CAM GPIO1 (TX) → ESP32 GPIO35 (RX)   [data wajah]

GND → GND (wajib common ground!)

5V  → 5V dari LM2596

ESP32-CAM JUGA connect ke WiFi AP "N.O.V.A" sebagai STATION

dengan IP statis 192.168.4.2, supaya dashboard di ESP32 utama

(192.168.4.1) bisa embed live stream dari CAM.

Akses stream langsung: http://192.168.4.2:81/stream

Cara upload: GPIO0 ke GND saat upload, lepas setelah selesai.

══════════════════════════════════════════════════════


*/

#include "esp_camera.h"

#include "esp_timer.h"

#include "img_converters.h"

#include "Arduino.h"

#include "fb_gfx.h"

#include "esp_http_server.h"

#include <WiFi.h>

// ── Kredensial WiFi — HARUS SAMA dengan WiFiController.h ESP32 utama ──

#define WIFI_SSID  "N.O.V.A"

#define WIFI_PASS  "nova12345"

// ── IP statis ESP32-CAM (ESP32 utama = 192.168.4.1) ──

IPAddress camIP(192, 168, 4, 2);

IPAddress camGateway(192, 168, 4, 1);

IPAddress camSubnet(255, 255, 255, 0);

// ── Pin AI Thinker ESP32-CAM ──

#define PWDN_GPIO_NUM     32

#define RESET_GPIO_NUM    -1

#define XCLK_GPIO_NUM      0

#define SIOD_GPIO_NUM     26

#define SIOC_GPIO_NUM     27

#define Y9_GPIO_NUM       35

#define Y8_GPIO_NUM       34

#define Y7_GPIO_NUM       39

#define Y6_GPIO_NUM       36

#define Y5_GPIO_NUM       21

#define Y4_GPIO_NUM       19

#define Y3_GPIO_NUM       18

#define Y2_GPIO_NUM        5

#define VSYNC_GPIO_NUM    25

#define HREF_GPIO_NUM     23

#define PCLK_GPIO_NUM     22

#define LED_GPIO_NUM       4

httpd_handle_t streamServer = NULL;

// ────────────────────────────────────────────

//  INIT CAMERA

//  GRAYSCALE dipakai untuk deteksi blob (ringan)

//  + dikonversi ke JPEG saat streaming (frame2jpg)

// ────────────────────────────────────────────

bool initCamera() {

camera_config_t config;

config.ledc_channel = LEDC_CHANNEL_0;

config.ledc_timer   = LEDC_TIMER_0;

config.pin_d0       = Y2_GPIO_NUM;

config.pin_d1       = Y3_GPIO_NUM;

config.pin_d2       = Y4_GPIO_NUM;

config.pin_d3       = Y5_GPIO_NUM;

config.pin_d4       = Y6_GPIO_NUM;

config.pin_d5       = Y7_GPIO_NUM;

config.pin_d6       = Y8_GPIO_NUM;

config.pin_d7       = Y9_GPIO_NUM;

config.pin_xclk     = XCLK_GPIO_NUM;

config.pin_pclk     = PCLK_GPIO_NUM;

config.pin_vsync    = VSYNC_GPIO_NUM;

config.pin_href     = HREF_GPIO_NUM;

config.pin_sscb_sda = SIOD_GPIO_NUM;

config.pin_sscb_scl = SIOC_GPIO_NUM;

config.pin_pwdn     = PWDN_GPIO_NUM;

config.pin_reset    = RESET_GPIO_NUM;

config.xclk_freq_hz = 20000000;

config.pixel_format = PIXFORMAT_JPEG;

config.frame_size   = FRAMESIZE_QVGA;     // 320x240

config.jpeg_quality = 12;

config.fb_count     = psramFound() ? 2 : 1;

config.fb_location  = psramFound() ? CAMERA_FB_IN_PSRAM : CAMERA_FB_IN_DRAM;

config.grab_mode    = CAMERA_GRAB_LATEST;

esp_err_t err = esp_camera_init(&config);

return (err == ESP_OK);

}

// ────────────────────────────────────────────

//  DETEKSI BLOB TERANG (proxy wajah)

//  Pakai frame buffer yang SAMA dengan yang dikirim ke stream

// ────────────────────────────────────────────

bool detectBrightBlob(camera_fb_t *fb, int &outX, int &outY) {

uint8_t *buf = fb->buf;

int w = fb->width;

int h = fb->height;

const uint8_t THRESH = 140;

long sumX = 0, sumY = 0, count = 0;

for (int y = 20; y < h - 20; y += 4) {

for (int x = 20; x < w - 20; x += 4) {

  uint8_t px = buf[y * w + x];

  if (px > THRESH) {

    sumX += x;

    sumY += y;

    count++;

  }

}

}

if (count > 80) {

outX = (int)(sumX / count);

outY = (int)(sumY / count);

return true;

}

return false;

}

// ────────────────────────────────────────────

//  MJPEG STREAM HANDLER (port 81, endpoint /stream)

//  Setiap frame: ambil dari kamera, jalankan deteksi blob

//  (supaya UART tetap update), convert ke JPEG, kirim chunk.

// ────────────────────────────────────────────

#define PART_BOUNDARY "novacamboundary"

static const char *STREAM_CONTENT_TYPE = "multipart/x-mixed-replace;boundary=" PART_BOUNDARY;

static const char *STREAM_BOUNDARY = "\r\n--" PART_BOUNDARY "\r\n";

static const char *STREAM_PART = "Content-Type: image/jpeg\r\nContent-Length: %u\r\n\r\n";

// Variabel global hasil deteksi terakhir — dibaca loop() untuk kirim UART

volatile bool   gFaceFound = false;

volatile int    gFaceX = 0;

volatile int    gFaceY = 0;

static esp_err_t stream_handler(httpd_req_t *req) {

camera_fb_t *fb = NULL;

esp_err_t res = ESP_OK;

size_t jpgLen = 0;

uint8_t *jpgBuf = NULL;

char part_buf[64];

res = httpd_resp_set_type(req, STREAM_CONTENT_TYPE);

if (res != ESP_OK) return res;

httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");

while (true) {

fb = esp_camera_fb_get();

if (!fb) {

  res = ESP_FAIL;

} else {

  // Update deteksi wajah (dibaca loop() untuk kirim ke ESP32 utama)

  int fx, fy;

  if (detectBrightBlob(fb, fx, fy)) {

    gFaceFound = true;

    gFaceX = fx;

    gFaceY = fy;

  } else {

    gFaceFound = false;

  }



  // Convert grayscale → JPEG untuk dikirim ke browser

  bool ok = frame2jpg(fb, 70, &jpgBuf, &jpgLen);

  esp_camera_fb_return(fb);

  fb = NULL;

  if (!ok) {

    res = ESP_FAIL;

  }

}



if (res == ESP_OK) {

  res = httpd_resp_send_chunk(req, STREAM_BOUNDARY, strlen(STREAM_BOUNDARY));

}

if (res == ESP_OK) {

  size_t hlen = snprintf(part_buf, sizeof(part_buf), STREAM_PART, (unsigned)jpgLen);

  res = httpd_resp_send_chunk(req, part_buf, hlen);

}

if (res == ESP_OK) {

  res = httpd_resp_send_chunk(req, (const char *)jpgBuf, jpgLen);

}

if (jpgBuf) {

  free(jpgBuf);

  jpgBuf = NULL;

}

if (res != ESP_OK) break;



delay(30);  // ~20-25fps target, sesuaikan kalau lag

}

return res;

}

void startStreamServer() {

httpd_config_t config = HTTPD_DEFAULT_CONFIG();

config.server_port = 81;

config.ctrl_port    = 32768;

httpd_uri_t stream_uri = {

.uri      = "/stream",

.method   = HTTP_GET,

.handler  = stream_handler,

.user_ctx = NULL

};

if (httpd_start(&streamServer, &config) == ESP_OK) {

httpd_register_uri_handler(streamServer, &stream_uri);

}

}

// ────────────────────────────────────────────

//  SETUP

// ────────────────────────────────────────────

void setup() {

Serial.begin(115200);  // UART0 — dipakai juga untuk kirim data wajah ke ESP32 utama

pinMode(LED_GPIO_NUM, OUTPUT);

digitalWrite(LED_GPIO_NUM, LOW);

if (!initCamera()) {

Serial.println("Camera init failed");

  ESP.restart();

}

// Connect ke AP ESP32 utama sebagai STATION dengan IP statis

WiFi.mode(WIFI_STA);

WiFi.config(camIP, camGateway, camSubnet);

Serial.println("Connecting WiFi...");

delay(5000);

WiFi.begin(WIFI_SSID, WIFI_PASS);

while (WiFi.status() != WL_CONNECTED) {

Serial.print(".");

  delay(500);

}

Serial.println();

Serial.println("CONNECTED");

Serial.println(WiFi.localIP());

if (WiFi.status() == WL_CONNECTED) {

startStreamServer();

}

// Kalau WiFi gagal connect, kamera tetap jalan untuk deteksi via UART,

// hanya live stream yang tidak tersedia.

}

unsigned long prevSendMs = 0;

// ────────────────────────────────────────────

//  LOOP — kirim hasil deteksi ke ESP32 utama via UART

//  (stream_handler() di atas berjalan otomatis di task terpisah

