// ══════════════════════════════════════════════════════

//  PARSE DATA DARI ESP32-CAM

//  Format: "F,x,y\n"  = wajah ditemukan di koordinat x,y

//          "N\n"       = tidak ada wajah

// ══════════════════════════════════════════════════════

void parseCamData() {

if (!camSerial.available()) return;

String line = camSerial.readStringUntil('\n');

line.trim();

if (line.startsWith("F,")) {

// Parse x,y

int comma1 = line.indexOf(',');

int comma2 = line.indexOf(',', comma1 + 1);

if (comma1 > 0 && comma2 > comma1) {

  int x = line.substring(comma1 + 1, comma2).toInt();

  int y = line.substring(comma2 + 1).toInt();

  faceDetected = true;

  faceX        = x;

  faceY        = y;

}

} else if (line == "N") {

faceDetected = false;

}

}

// ══════════════════════════════════════════════════════

//  SETUP

// ══════════════════════════════════════════════════════

void setup() {

Serial.begin(115200);

Serial.println("\n[N.O.V.A] Booting...");

// UART ke ESP32-CAM

camSerial.begin(115200, SERIAL_8N1, CAM_SERIAL_RX, -1);

// Init OLED

if (!faceBegin()) {

Serial.println("[N.O.V.A] OLED gagal! Cek wiring SDA/SCL dan alamat 0x3C");

} else {

Serial.println("[N.O.V.A] OLED OK");

}

// Init servo

headBegin();

Serial.println("[N.O.V.A] Servo OK");

// Init motor

movementBegin();

Serial.println("[N.O.V.A] Motor OK");

// Init DFPlayer

if (!audioBegin()) {

Serial.println("[N.O.V.A] DFPlayer gagal atau tidak ada SD card");

} else {

Serial.println("[N.O.V.A] DFPlayer OK");

}

// Init state machine

stateMachineBegin();

Serial.println("[N.O.V.A] State machine OK");

// WiFi task di Core 1

xTaskCreatePinnedToCore(

taskWiFi,      // fungsi task

"WiFiTask",    // nama

8192,          // stack size

NULL,          // parameter

1,             // prioritas

NULL,          // handle

1              // Core 1

);

Serial.println("[N.O.V.A] WiFi task started");

Serial.println("[N.O.V.A] SSID: N.O.V.A | Pass: nova12345");

Serial.println("[N.O.V.A] IP: 192.168.4.1");

Serial.println("[N.O.V.A] Ready!");

}

// ══════════════════════════════════════════════════════

//  LOOP — berjalan di Core 0 (Autonomous Core)

// ══════════════════════════════════════════════════════

void loop() {

unsigned long now = millis();

// ── Baca kamera setiap 30ms ──

if (now - prevFaceMs >= 30) {

prevFaceMs = now;

parseCamData();

}

// ── Baca sonar setiap 60ms ──

if (now - prevSonarMs >= 60) {

prevSonarMs = now;

unsigned int dist = sonar.ping_cm();

// Jika gagal baca

if (dist == 0 || dist > 200) {

  dist = 200;

}

// Inisialisasi awal

if (stableDistCm == 999) {

  stableDistCm = dist;

}

// Smooth filter

stableDistCm = (stableDistCm * 3 + dist) / 4;

obstacleDistCm = stableDistCm;

Serial.print("SONAR: ");

Serial.println(obstacleDistCm);

}

// ── Update state machine setiap 50ms ──

if (now - prevStateMs >= 50) {

prevStateMs = now;

stateMachineUpdate();

}

// ── Update servo head setiap 20ms ──

if (now - prevHeadMs >= 20) {

prevHeadMs = now;

headUpdate();

// Sinkronkan pupil dengan posisi servo

faceSetPupil(headGetPan(), headGetTilt());

}

// ── Update motor setiap 30ms ──

if (now - prevMotorMs >= 30) {

prevMotorMs = now;

movementUpdate();

}

// ── Render wajah OLED setiap 50ms (~20fps) ──

if (now - prevFaceRenderMs >= 50) {

prevFaceRenderMs = now;

faceRender();

}

}

#ifndef AUDIO_PLAYER_H

