#ifndef HEAD_MOTION_H

#define HEAD_MOTION_H

#include <ESP32Servo.h>

// ── Pin Servo ──

#define PIN_SERVO_PAN   4

#define PIN_SERVO_TILT  5

// ── Range Sudut ──

#define PAN_MIN    30

#define PAN_MAX   150

#define PAN_CENTER 90

#define TILT_MIN   60

#define TILT_MAX  120

#define TILT_CENTER 90

Servo servoPan;

Servo servoTilt;

// State sudut saat ini & target

static float panCurrent  = PAN_CENTER;

static float tiltCurrent = TILT_CENTER;

static float panTarget   = PAN_CENTER;

static float tiltTarget  = TILT_CENTER;

// Idle motion

static float   idlePanOffset  = 0;

static float   idleTiltOffset = 0;

static int8_t  idlePanDir     = 1;

static int8_t  idleTiltDir    = 1;

static unsigned long lastIdleUpdateMs = 0;

static bool    idleMotionEnabled = true;

// ────────────────────────────────────────────

void headBegin() {

ESP32PWM::allocateTimer(0);

ESP32PWM::allocateTimer(1);

servoPan.setPeriodHertz(50);

servoTilt.setPeriodHertz(50);

servoPan.attach(PIN_SERVO_PAN,   500, 2400);

servoTilt.attach(PIN_SERVO_TILT, 500, 2400);

servoPan.write(PAN_CENTER);

servoTilt.write(TILT_CENTER);

panCurrent  = PAN_CENTER;

tiltCurrent = TILT_CENTER;

panTarget   = PAN_CENTER;

tiltTarget  = TILT_CENTER;

}

// Set target sudut — servo akan bergerak smooth

void headSetTarget(int pan, int tilt) {

panTarget  = constrain(pan,  PAN_MIN,  PAN_MAX);

tiltTarget = constrain(tilt, TILT_MIN, TILT_MAX);

}

void headCenter() {

headSetTarget(PAN_CENTER, TILT_CENTER);

}

void headLookLeft()  { headSetTarget(PAN_MIN + 20, TILT_CENTER); }

void headLookRight() { headSetTarget(PAN_MAX - 20, TILT_CENTER); }

void headLookUp()    { headSetTarget(PAN_CENTER, TILT_MIN + 10); }

void headLookDown()  { headSetTarget(PAN_CENTER, TILT_MAX - 10); }

// Geleng-geleng (untuk state ANNOYED)

static int   shakeCount = 0;

static bool  shakeActive = false;

static unsigned long lastShakeMs = 0;

void headShake() {

shakeActive = true;

shakeCount  = 0;

idleMotionEnabled = false;

}

// Ganti pupil di FaceAnimator sesuai posisi servo

int headGetPan()  { return (int)panCurrent;  }

int headGetTilt() { return (int)tiltCurrent; }

void headEnableIdle(bool en) { idleMotionEnabled = en; }

// ────────────────────────────────────────────

// Update — panggil di loop() setiap ~20ms

// ────────────────────────────────────────────

void headUpdate() {

unsigned long now = millis();

// Shake animation

if (shakeActive) {

if (now - lastShakeMs > 120) {

  lastShakeMs = now;

  shakeCount++;

  if (shakeCount % 2 == 0)

    panTarget = PAN_CENTER - 25;

  else

    panTarget = PAN_CENTER + 25;

  if (shakeCount >= 6) {

    shakeActive = false;

    panTarget   = PAN_CENTER;

    idleMotionEnabled = true;

  }

}

}

// Idle motion (±3° lambat)

if (idleMotionEnabled && !shakeActive && (now - lastIdleUpdateMs > 80)) {

lastIdleUpdateMs = now;

idlePanOffset  += idlePanDir  * 0.4f;

idleTiltOffset += idleTiltDir * 0.2f;

if (idlePanOffset  >  3.0f || idlePanOffset  < -3.0f) idlePanDir  *= -1;

if (idleTiltOffset >  2.0f || idleTiltOffset < -2.0f) idleTiltDir *= -1;

}

float effectivePan  = panTarget  + (idleMotionEnabled ? idlePanOffset  : 0);

float effectiveTilt = tiltTarget + (idleMotionEnabled ? idleTiltOffset : 0);

effectivePan  = constrain(effectivePan,  (float)PAN_MIN,  (float)PAN_MAX);

effectiveTilt = constrain(effectiveTilt, (float)TILT_MIN, (float)TILT_MAX);

// Easing (lerp factor 0.12)

panCurrent  += (effectivePan  - panCurrent)  * 0.12f;

tiltCurrent += (effectiveTilt - tiltCurrent) * 0.12f;

servoPan.write((int)panCurrent);

servoTilt.write((int)tiltCurrent);

}

// Tracking wajah dari koordinat kamera

// faceX, faceY: 0-320, 0-240 (resolusi OV2640 QVGA)

void headTrackFace(int faceX, int faceY) {

idleMotionEnabled = false;

int centerX = 160, centerY = 120;

int errX = faceX - centerX;

int errY = faceY - centerY;

int newPan  = (int)panTarget  - (errX / 20);

int newTilt = (int)tiltTarget + (errY / 25);

headSetTarget(newPan, newTilt);

}

void headStopTracking() {

idleMotionEnabled = true;

}

#endif // HEAD_MOTION_H

#ifndef STATE_MACHINE_H

#define STATE_MACHINE_H

#include "FaceAnimator.h"

#include "HeadMotion.h"

#include "Movement.h"

#include "AudioPlayer.h"

// ── State robot ──

typedef enum {

STATE_IDLE,

STATE_HAPPY,

STATE_LONELY,

STATE_ANNOYED,

STATE_SCARED,

STATE_SLEEPY

} RobotState;

// ── Command queue dari WiFi / HP ──

typedef enum {

CMD_NONE,

CMD_FORWARD,

CMD_BACKWARD,

CMD_LEFT,

CMD_RIGHT,

CMD_STOP,

CMD_COME,

CMD_FOLLOW,

CMD_DANCE,

CMD_EXPR_HAPPY,

CMD_EXPR_SAD,

CMD_EXPR_ANGRY,

CMD_EXPR_SCARED,

CMD_EXPR_SLEEPY

} RobotCommand;

// ── Shared variables (akses dari dua task) ──

volatile RobotState   robotState     = STATE_IDLE;

volatile RobotCommand pendingCommand = CMD_NONE;

volatile bool         faceDetected   = false;

volatile int          faceX          = 160;

volatile int          faceY          = 120;

volatile int          obstacleDistCm = 999;

volatile int          stableDistCm   = 999;

// ── Timer ──

static unsigned long stateEnteredMs  = 0;

static unsigned long lastInteractMs  = 0;

static unsigned long lastIdleSoundMs = 0;

static unsigned long lastSearchMs    = 0;

static unsigned long forcedExprMs    = 0;

static bool          forcedExpr      = false;

// ── Distance Emotion Threshold ──

#define DIST_ANGRY_CM        5     // 1-5 cm

#define DIST_SCARED_CM       10    // 6-10 cm

#define DIST_HAPPY_CM        25    // 11-25 cm

#define DIST_IDLE_CM         50    // 26-50 cm

#define DIST_FOLLOW_STOP_CM  30

#define TIMEOUT_LONELY_MS    20000UL

#define TIMEOUT_SLEEPY_MS    40000UL  // 2 menit  → SLEEPY

#define IDLE_SOUND_MIN_MS    20000UL   // min 20 detik antar suara idle

#define IDLE_SOUND_MAX_MS    60000UL   // max 60 detik

#define FORCED_EXPR_MS        4000UL   // ekspresi dari HP berlaku 4 detik

#define OBSTACLE_BLOCK_COUNT     5     // halangi 5x berturut → ANNOYED

static uint8_t obstacleBlockCount = 0;

static unsigned long nextIdleSoundMs = 30000UL;

static unsigned long lastEmotionChangeMs = 0;

static unsigned long lastHappyMs = 0;

// Follow mode

static bool followMode = false;

// ────────────────────────────────────────────

//  TRANSITIONS

// ────────────────────────────────────────────

void _enterState(RobotState s) {

if (robotState == s) return;

robotState     = s;

stateEnteredMs = millis();

switch (s) {

case STATE_IDLE:

  faceSetExpression(EXPR_IDLE);

  moveStop();

  headEnableIdle(true);

  break;



case STATE_HAPPY:

  faceSetExpression(EXPR_HAPPY);

  moveStop();

  headEnableIdle(true);

  audioPlay(SFX_HAPPY);

  lastInteractMs = millis();

  break;



case STATE_LONELY:

  faceSetExpression(EXPR_SAD);

  moveStop();

  headEnableIdle(true);

  audioPlay(SFX_SAD);

  break;



case STATE_ANNOYED:

  faceSetExpression(EXPR_ANGRY);

  moveStop();

  headShake();

  audioPlay(SFX_ANGRY);

  lastInteractMs = millis();

  break;



case STATE_SCARED:

  faceSetExpression(EXPR_SCARED);

  moveStop();

  headSetTarget(PAN_CENTER, TILT_MIN + 5);  // kepala mundur (tilt)

  audioPlay(SFX_SCARED);

  break;



case STATE_SLEEPY:

  faceBlink();

  faceSetExpression(EXPR_SLEEPY);

  moveStop();

  headSetTarget(PAN_CENTER, TILT_MAX - 5);  // kepala sedikit menunduk

  headEnableIdle(false);

  audioPlay(SFX_SLEEPY);

  break;

}

}

// ────────────────────────────────────────────

//  PROCESS COMMAND DARI HP

// ────────────────────────────────────────────

void _processCommand(RobotCommand cmd) {

if (cmd == CMD_NONE) return;

lastInteractMs = millis();

switch (cmd) {

case CMD_FORWARD:   followMode = false; moveForward();       break;

case CMD_BACKWARD:  followMode = false; moveBackward();      break;

case CMD_LEFT:      followMode = false; turnLeft();          break;

case CMD_RIGHT:     followMode = false; turnRight();         break;

case CMD_STOP:      followMode = false; moveStop();          break;

case CMD_DANCE:

  followMode = false;

  moveDance();

  faceSetExpression(EXPR_HAPPY);

  audioPlay(SFX_HAPPY);

  break;

case CMD_COME:

  followMode = false;

  _enterState(STATE_HAPPY);

  break;

case CMD_FOLLOW:

  followMode = true;

  faceSetExpression(EXPR_HAPPY);

  break;

case CMD_EXPR_HAPPY:

  forcedExpr = true; forcedExprMs = millis();

  faceSetExpression(EXPR_HAPPY); break;

case CMD_EXPR_SAD:

  forcedExpr = true; forcedExprMs = millis();

  faceSetExpression(EXPR_SAD);   break;

case CMD_EXPR_ANGRY:

  forcedExpr = true; forcedExprMs = millis();

  faceSetExpression(EXPR_ANGRY); break;

case CMD_EXPR_SCARED:

  forcedExpr = true; forcedExprMs = millis();

  faceSetExpression(EXPR_SCARED);break;

case CMD_EXPR_SLEEPY:

  forcedExpr = true; forcedExprMs = millis();

  faceSetExpression(EXPR_SLEEPY);break;

default: break;

}

pendingCommand = CMD_NONE;

}

// ────────────────────────────────────────────

//  UPDATE STATE MACHINE — panggil ~50ms

// ────────────────────────────────────────────

void stateMachineUpdate() {

unsigned long now = millis();

// ── 1. Proses command HP (prioritas tertinggi setelah SCARED) ──

RobotCommand cmd = pendingCommand;

if (cmd != CMD_NONE && robotState != STATE_SCARED) {

_processCommand(cmd);

}

// ─────────────────────────────

// DISTANCE EMOTION SYSTEM

// ─────────────────────────────

// Cooldown emosi supaya tidak spam ganti state

if (now - lastEmotionChangeMs < 1500) {

return;

}

if (

!faceDetected &&

  !forcedExpr &&

  robotState != STATE_SLEEPY

) {



  // 1–5 cm = marah

  if (obstacleDistCm > 0 && obstacleDistCm <= 5) {

    if (robotState == STATE_ANNOYED && now - stateEnteredMs > 4000) {

        moveStop();

        _enterState(STATE_IDLE);

        return;

    }

  }



  // 6–10 cm = takut

  else if (obstacleDistCm <= 10) {

      if (robotState != STATE_SCARED) {

          _enterState(STATE_SCARED);

          lastEmotionChangeMs = now;

          return;

      }

  }



  // 11–25 cm = happy

  else if (obstacleDistCm <= 25) {

      if (

          robotState != STATE_HAPPY &&

          now - lastHappyMs > 5000

      ) {

          lastHappyMs = now;

          _enterState(STATE_HAPPY);

          lastEmotionChangeMs = now;

          return;

      }

  }



  // 26–50 cm = idle

  else if (obstacleDistCm <= 50) {

      if (robotState != STATE_IDLE) {

          _enterState(STATE_IDLE);

          lastEmotionChangeMs = now;

          return;

      }

  }



  // >50 cm = lonely

  else {

      if (robotState != STATE_LONELY) {

          _enterState(STATE_LONELY);

          lastEmotionChangeMs = now;

          return;

      }

  }

}

// ── 3. Forced expression timeout ──

if (forcedExpr && (now - forcedExprMs > FORCED_EXPR_MS)) {

forcedExpr = false;

// Kembalikan ekspresi sesuai state

switch (robotState) {

  case STATE_IDLE:    faceSetExpression(EXPR_IDLE);   break;

  case STATE_HAPPY:   faceSetExpression(EXPR_HAPPY);  break;

  case STATE_LONELY:  faceSetExpression(EXPR_SAD);    break;

  case STATE_ANNOYED: faceSetExpression(EXPR_ANGRY);  break;

  case STATE_SCARED:  faceSetExpression(EXPR_SCARED); break;

  case STATE_SLEEPY:  faceSetExpression(EXPR_SLEEPY); break;

}

}

// ── 4. Face detection → update tracking & state ──

if (faceDetected) {

lastInteractMs = millis();



  // Kalau sedang lonely/sleepy lalu melihat orang

  if (

      (robotState == STATE_LONELY ||

      robotState == STATE_SLEEPY) &&



      obstacleDistCm > DIST_SCARED_CM

  ) {



      _enterState(STATE_HAPPY);

  }



  headTrackFace(faceX, faceY);



  // Follow mode

  if (followMode && obstacleDistCm > DIST_FOLLOW_STOP_CM) {



      int errX = faceX - 160;



      if (abs(errX) > 40) {



          if (errX > 0)

              turnRight(SPEED_SLOW);

          else

              turnLeft(SPEED_SLOW);



      } else {



          moveForward(SPEED_SLOW);

      }



  } else if (followMode) {



      moveStop();

  }

} else {

headStopTracking();



  if (followMode)

      moveStop();

}

// ── 5. ANNOYED timeout → IDLE ──

if (robotState == STATE_ANNOYED && now - stateEnteredMs > 4000) {

_enterState(STATE_IDLE);

return;

}

// ── 8. LONELY — robot cari orang dengan gerak kecil ──

if (robotState == STATE_LONELY && !faceDetected) {

if (now - lastSearchMs > 2500) {

  lastSearchMs = now;

  // Scan kiri-kanan dengan servo

  static bool searchLeft = true;

  if (searchLeft)

    headSetTarget(PAN_MIN + 10, TILT_CENTER);

  else

    headSetTarget(PAN_MAX - 10, TILT_CENTER);

  searchLeft = !searchLeft;

  // Gerak maju sedikit tiap 5 detik

  if (random(0, 3) == 0 && obstacleDistCm > 40) {

    moveForward(SPEED_SLOW);

  }

}

}

// ── Sleepy jika lama tidak ada interaksi ──

if (

robotState == STATE_LONELY &&

  !faceDetected &&

  obstacleDistCm > 50 &&

  (now - lastInteractMs > TIMEOUT_SLEEPY_MS)

) {



  _enterState(STATE_SLEEPY);

  return;

}

// ── 9B. Bangunkan dari tidur ──

if (robotState == STATE_SLEEPY) {

if (obstacleDistCm <= 20 || faceDetected) {



      audioPlay(SFX_GREET);



      faceBlink();



      _enterState(STATE_HAPPY);



      lastInteractMs = millis();



      return;

  }

}

// ── 10. Idle sound random ──

if (robotState == STATE_IDLE || robotState == STATE_LONELY) {

if (now - lastIdleSoundMs > nextIdleSoundMs) {

  lastIdleSoundMs  = now;

  nextIdleSoundMs  = random(IDLE_SOUND_MIN_MS, IDLE_SOUND_MAX_MS);

  audioPlayIdle();

}

}

}

// Init state machine

void stateMachineBegin() {

lastInteractMs   = millis();

lastIdleSoundMs  = millis();

nextIdleSoundMs  = random(IDLE_SOUND_MIN_MS, IDLE_SOUND_MAX_MS);

_enterState(STATE_IDLE);

}

