/*

══════════════════════════════════════════════════════

ESP32-CAM — Face Detect + Live MJPEG Stream

Upload ke board: AI Thinker ESP32-CAM

Koneksi ke ESP32 utama:

ESP32-CAM GPIO1 (TX) → ESP32 GPIO35 (RX)   [data wajah]

GND → GND (wajib common ground!)

5V  → 5V dari LM2596

ESP32-CAM JUGA connect ke WiFi AP "N.O.V.A" sebagai STATION

dengan IP statis 192.168.4.2, supaya dashboard di ESP32 utama

(192.168.4.1) bisa embed live stream dari CAM.

Akses stream langsung: http://192.168.4.2:81/stream

Cara upload: GPIO0 ke GND saat upload, lepas setelah selesai.

══════════════════════════════════════════════════════


*/

#include "esp_camera.h"

#include "esp_timer.h"

#include "img_converters.h"

#include "Arduino.h"

#include "fb_gfx.h"

#include "esp_http_server.h"

#include <WiFi.h>

// ── Kredensial WiFi — HARUS SAMA dengan WiFiController.h ESP32 utama ──

#define WIFI_SSID  "N.O.V.A"

#define WIFI_PASS  "nova12345"

// ── IP statis ESP32-CAM (ESP32 utama = 192.168.4.1) ──

IPAddress camIP(192, 168, 4, 2);

IPAddress camGateway(192, 168, 4, 1);

IPAddress camSubnet(255, 255, 255, 0);

// ── Pin AI Thinker ESP32-CAM ──

#define PWDN_GPIO_NUM     32

#define RESET_GPIO_NUM    -1

#define XCLK_GPIO_NUM      0

#define SIOD_GPIO_NUM     26

#define SIOC_GPIO_NUM     27

#define Y9_GPIO_NUM       35

#define Y8_GPIO_NUM       34

#define Y7_GPIO_NUM       39

#define Y6_GPIO_NUM       36

#define Y5_GPIO_NUM       21

#define Y4_GPIO_NUM       19

#define Y3_GPIO_NUM       18

#define Y2_GPIO_NUM        5

#define VSYNC_GPIO_NUM    25

#define HREF_GPIO_NUM     23

#define PCLK_GPIO_NUM     22

#define LED_GPIO_NUM       4

httpd_handle_t streamServer = NULL;

// ────────────────────────────────────────────

//  INIT CAMERA

//  GRAYSCALE dipakai untuk deteksi blob (ringan)

//  + dikonversi ke JPEG saat streaming (frame2jpg)

// ────────────────────────────────────────────

bool initCamera() {

camera_config_t config;

config.ledc_channel = LEDC_CHANNEL_0;

config.ledc_timer   = LEDC_TIMER_0;

config.pin_d0       = Y2_GPIO_NUM;

config.pin_d1       = Y3_GPIO_NUM;

config.pin_d2       = Y4_GPIO_NUM;

config.pin_d3       = Y5_GPIO_NUM;

config.pin_d4       = Y6_GPIO_NUM;

config.pin_d5       = Y7_GPIO_NUM;

config.pin_d6       = Y8_GPIO_NUM;

config.pin_d7       = Y9_GPIO_NUM;

config.pin_xclk     = XCLK_GPIO_NUM;

config.pin_pclk     = PCLK_GPIO_NUM;

config.pin_vsync    = VSYNC_GPIO_NUM;

config.pin_href     = HREF_GPIO_NUM;

config.pin_sscb_sda = SIOD_GPIO_NUM;

config.pin_sscb_scl = SIOC_GPIO_NUM;

config.pin_pwdn     = PWDN_GPIO_NUM;

config.pin_reset    = RESET_GPIO_NUM;

config.xclk_freq_hz = 20000000;

config.pixel_format = PIXFORMAT_JPEG;

config.frame_size   = FRAMESIZE_QVGA;     // 320x240

config.jpeg_quality = 12;

config.fb_count     = psramFound() ? 2 : 1;

config.fb_location  = psramFound() ? CAMERA_FB_IN_PSRAM : CAMERA_FB_IN_DRAM;

config.grab_mode    = CAMERA_GRAB_LATEST;

esp_err_t err = esp_camera_init(&config);

return (err == ESP_OK);

}

// ────────────────────────────────────────────

//  DETEKSI BLOB TERANG (proxy wajah)

//  Pakai frame buffer yang SAMA dengan yang dikirim ke stream

// ────────────────────────────────────────────

bool detectBrightBlob(camera_fb_t *fb, int &outX, int &outY) {

uint8_t *buf = fb->buf;

int w = fb->width;

int h = fb->height;

const uint8_t THRESH = 140;

long sumX = 0, sumY = 0, count = 0;

for (int y = 20; y < h - 20; y += 4) {

for (int x = 20; x < w - 20; x += 4) {

  uint8_t px = buf[y * w + x];

  if (px > THRESH) {

    sumX += x;

    sumY += y;

    count++;

  }

}

}

if (count > 80) {

outX = (int)(sumX / count);

outY = (int)(sumY / count);

return true;

}

return false;

}

// ────────────────────────────────────────────

//  MJPEG STREAM HANDLER (port 81, endpoint /stream)

//  Setiap frame: ambil dari kamera, jalankan deteksi blob

//  (supaya UART tetap update), convert ke JPEG, kirim chunk.

// ────────────────────────────────────────────

#define PART_BOUNDARY "novacamboundary"

static const char *STREAM_CONTENT_TYPE = "multipart/x-mixed-replace;boundary=" PART_BOUNDARY;

static const char *STREAM_BOUNDARY = "\r\n--" PART_BOUNDARY "\r\n";

static const char *STREAM_PART = "Content-Type: image/jpeg\r\nContent-Length: %u\r\n\r\n";

// Variabel global hasil deteksi terakhir — dibaca loop() untuk kirim UART

volatile bool   gFaceFound = false;

volatile int    gFaceX = 0;

volatile int    gFaceY = 0;

static esp_err_t stream_handler(httpd_req_t *req) {

camera_fb_t *fb = NULL;

esp_err_t res = ESP_OK;

size_t jpgLen = 0;

uint8_t *jpgBuf = NULL;

char part_buf[64];

res = httpd_resp_set_type(req, STREAM_CONTENT_TYPE);

if (res != ESP_OK) return res;

httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");

while (true) {

fb = esp_camera_fb_get();

if (!fb) {

  res = ESP_FAIL;

} else {

  // Update deteksi wajah (dibaca loop() untuk kirim ke ESP32 utama)

  int fx, fy;

  if (detectBrightBlob(fb, fx, fy)) {

    gFaceFound = true;

    gFaceX = fx;

    gFaceY = fy;

  } else {

    gFaceFound = false;

  }



  // Convert grayscale → JPEG untuk dikirim ke browser

  bool ok = frame2jpg(fb, 70, &jpgBuf, &jpgLen);

  esp_camera_fb_return(fb);

  fb = NULL;

  if (!ok) {

    res = ESP_FAIL;

  }

}



if (res == ESP_OK) {

  res = httpd_resp_send_chunk(req, STREAM_BOUNDARY, strlen(STREAM_BOUNDARY));

}

if (res == ESP_OK) {

  size_t hlen = snprintf(part_buf, sizeof(part_buf), STREAM_PART, (unsigned)jpgLen);

  res = httpd_resp_send_chunk(req, part_buf, hlen);

}

if (res == ESP_OK) {

  res = httpd_resp_send_chunk(req, (const char *)jpgBuf, jpgLen);

}

if (jpgBuf) {

  free(jpgBuf);

  jpgBuf = NULL;

}

if (res != ESP_OK) break;



delay(30);  // ~20-25fps target, sesuaikan kalau lag

}

return res;

}

void startStreamServer() {

httpd_config_t config = HTTPD_DEFAULT_CONFIG();

config.server_port = 81;

config.ctrl_port    = 32768;

httpd_uri_t stream_uri = {

.uri      = "/stream",

.method   = HTTP_GET,

.handler  = stream_handler,

.user_ctx = NULL

};

if (httpd_start(&streamServer, &config) == ESP_OK) {

httpd_register_uri_handler(streamServer, &stream_uri);

}

}

// ────────────────────────────────────────────

//  SETUP

// ────────────────────────────────────────────

void setup() {

Serial.begin(115200);  // UART0 — dipakai juga untuk kirim data wajah ke ESP32 utama

pinMode(LED_GPIO_NUM, OUTPUT);

digitalWrite(LED_GPIO_NUM, LOW);

if (!initCamera()) {

Serial.println("Camera init failed");

  ESP.restart();

}

// Connect ke AP ESP32 utama sebagai STATION dengan IP statis

WiFi.mode(WIFI_STA);

WiFi.config(camIP, camGateway, camSubnet);

Serial.println("Connecting WiFi...");

delay(5000);

WiFi.begin(WIFI_SSID, WIFI_PASS);

while (WiFi.status() != WL_CONNECTED) {

Serial.print(".");

  delay(500);

}

Serial.println();

Serial.println("CONNECTED");

Serial.println(WiFi.localIP());

if (WiFi.status() == WL_CONNECTED) {

startStreamServer();

}

// Kalau WiFi gagal connect, kamera tetap jalan untuk deteksi via UART,

// hanya live stream yang tidak tersedia.

}

unsigned long prevSendMs = 0;

// ────────────────────────────────────────────

//  LOOP — kirim hasil deteksi ke ESP32 utama via UART

//  (stream_handler() di atas berjalan otomatis di task terpisah

//   milik esp_http_server, tidak perlu dipanggil manual di sini)

// ────────────────────────────────────────────

void loop() {

unsigned long now = millis();

if (now - prevSendMs < 80) return;

prevSendMs = now;

// Kalau stream server aktif, gFaceFound/gFaceX/gFaceY sudah otomatis

// terupdate dari stream_handler(). Kalau WiFi gagal (server tidak jalan),

// jalankan deteksi manual di sini sebagai fallback.

if (streamServer == NULL) {

camera_fb_t *fb = esp_camera_fb_get();

if (fb) {

  int fx, fy;

  if (detectBrightBlob(fb, fx, fy)) {

    gFaceFound = true;

    gFaceX = fx;

    gFaceY = fy;

  } else {

    gFaceFound = false;

  }

  esp_camera_fb_return(fb);

}

}

if (gFaceFound) {

Serial.print("F,");

Serial.print(gFaceX);

Serial.print(",");

Serial.println(gFaceY);

} else {

Serial.println("N");

}

}

