bool audioBegin() {
  dfSerial.begin(9600, SERIAL_8N1, DFPLAYER_RX, DFPLAYER_TX);
  delay(1000);
  if (!dfPlayer.begin(dfSerial, true, true)) {
    dfReady = false;
    return false;
  }
  dfPlayer.volume(20);   // Volume 0-30
  dfReady = true;
  return true;
}

void audioPlay(uint8_t track) {
  if (!dfReady) return;
  dfPlayer.play(track);
}

void audioPlayIdle() {
  if (!dfReady) return;
  // Pilih random dari 3 suara idle
  uint8_t t = random(SFX_IDLE_1, SFX_IDLE_3 + 1);
  dfPlayer.play(t);
}

void audioSetVolume(uint8_t vol) {
  if (!dfReady) return;
  dfPlayer.volume(constrain(vol, 0, 30));
}

void audioStop() {
  if (!dfReady) return;
  dfPlayer.stop();
}

