#ifndef STATE_MACHINE_H
#define STATE_MACHINE_H

#include "FaceAnimator.h"
#include "HeadMotion.h"
#include "Movement.h"
#include "AudioPlayer.h"

// ── State robot ──
typedef enum {
  STATE_IDLE,
  STATE_HAPPY,
  STATE_LONELY,
  STATE_SLEEPY
} RobotState;

// ── Command queue dari WiFi / HP ──
typedef enum {
  CMD_NONE,
  CMD_FORWARD,
  CMD_BACKWARD,
  CMD_LEFT,
  CMD_RIGHT,
  CMD_STOP,
  CMD_EXPR_HAPPY,
  CMD_EXPR_SAD,
  CMD_EXPR_ANGRY,
  CMD_EXPR_SCARED,
  CMD_EXPR_SLEEPY
} RobotCommand;

// ── Shared variables (akses dari dua task) ──
volatile RobotState   robotState     = STATE_IDLE;
volatile RobotCommand pendingCommand = CMD_NONE;
volatile bool         faceDetected   = false;
volatile int          faceX          = 160;
volatile int          faceY          = 120;


// ── Timer ──
static unsigned long stateEnteredMs  = 0;
static unsigned long lastInteractMs  = 0;
static unsigned long lastIdleSoundMs = 0;
static unsigned long lastSearchMs    = 0;
static unsigned long forcedExprMs    = 0;
static bool          forcedExpr      = false;

// ── Distance Emotion Threshold ──


#define TIMEOUT_LONELY_MS    20000UL
#define TIMEOUT_SLEEPY_MS    40000UL  // 2 menit  → SLEEPY
#define IDLE_SOUND_MIN_MS    20000UL   // min 20 detik antar suara idle
#define IDLE_SOUND_MAX_MS    60000UL   // max 60 detik
#define FORCED_EXPR_MS        4000UL   // ekspresi dari HP berlaku 4 detik

static unsigned long nextIdleSoundMs = 30000UL;
static unsigned long lastEmotionChangeMs = 0;
static unsigned long lastHappyMs = 0;


// ────────────────────────────────────────────
//  TRANSITIONS
// ────────────────────────────────────────────
void _enterState(RobotState s) {
  if (robotState == s) return;
  robotState     = s;
  stateEnteredMs = millis();

  switch (s) {
    case STATE_IDLE:
      faceSetExpression(EXPR_IDLE);
      moveStop();
      headEnableIdle(true);
      break;

    case STATE_HAPPY:
      faceSetExpression(EXPR_HAPPY);
      moveStop();
      headEnableIdle(true);
      audioPlay(SFX_HAPPY);
      lastInteractMs = millis();
      break;

    case STATE_LONELY:
      faceSetExpression(EXPR_SAD);
      moveStop();
      headEnableIdle(true);
      audioPlay(SFX_SAD);
      break;

    case STATE_ANNOYED:
      faceSetExpression(EXPR_ANGRY);
      moveStop();
      headShake();
      audioPlay(SFX_ANGRY);
      lastInteractMs = millis();
      break;

    case STATE_SCARED:
      faceSetExpression(EXPR_SCARED);
      moveStop();
      headSetTarget(PAN_CENTER, TILT_MIN + 5);  // kepala mundur (tilt)
      audioPlay(SFX_SCARED);
      break;

    case STATE_SLEEPY:
      faceBlink();
      faceSetExpression(EXPR_SLEEPY);
      moveStop();
      headSetTarget(PAN_CENTER, TILT_MAX - 5);  // kepala sedikit menunduk
      headEnableIdle(false);
      audioPlay(SFX_SLEEPY);
      break;
  }
}

// ────────────────────────────────────────────
//  PROCESS COMMAND DARI HP
// ────────────────────────────────────────────
void _processCommand(RobotCommand cmd) {
  if (cmd == CMD_NONE) return;
  lastInteractMs = millis();

  switch (cmd) {
    case CMD_FORWARD:   followMode = false; moveForward();       break;
    case CMD_BACKWARD:  followMode = false; moveBackward();      break;
    case CMD_LEFT:      followMode = false; turnLeft();          break;
    case CMD_RIGHT:     followMode = false; turnRight();         break;
    case CMD_STOP:      followMode = false; moveStop();          break;
    case CMD_EXPR_HAPPY:
      forcedExpr = true; forcedExprMs = millis();
      faceSetExpression(EXPR_HAPPY); break;
    case CMD_EXPR_SAD:
      forcedExpr = true; forcedExprMs = millis();
      faceSetExpression(EXPR_SAD);   break;
    case CMD_EXPR_ANGRY:
      forcedExpr = true; forcedExprMs = millis();
      faceSetExpression(EXPR_ANGRY); break;
    case CMD_EXPR_SCARED:
      forcedExpr = true; forcedExprMs = millis();
      faceSetExpression(EXPR_SCARED);break;
    case CMD_EXPR_SLEEPY:
      forcedExpr = true; forcedExprMs = millis();
      faceSetExpression(EXPR_SLEEPY);break;
    default: break;
  }
  pendingCommand = CMD_NONE;
}

// ────────────────────────────────────────────
//  UPDATE STATE MACHINE — panggil ~50ms
// ────────────────────────────────────────────
void stateMachineUpdate() {
  unsigned long now = millis();

  // ── 1. Proses command HP (prioritas tertinggi setelah SCARED) ──
  RobotCommand cmd = pendingCommand;
  if (cmd != CMD_NONE && robotState != STATE_SCARED) {
    _processCommand(cmd);
  }

  // ─────────────────────────────
  // DISTANCE EMOTION SYSTEM
  // ─────────────────────────────
// Cooldown emosi supaya tidak spam ganti state
  if (now - lastEmotionChangeMs < 1500) {
      return;
  }
  if (
      !faceDetected &&
      !forcedExpr &&
      robotState != STATE_SLEEPY
    ) {


  // ── 3. Forced expression timeout ──
  if (forcedExpr && (now - forcedExprMs > FORCED_EXPR_MS)) {
    forcedExpr = false;
    // Kembalikan ekspresi sesuai state
    switch (robotState) {
      case STATE_IDLE:    faceSetExpression(EXPR_IDLE);   break;
      case STATE_HAPPY:   faceSetExpression(EXPR_HAPPY);  break;
      case STATE_LONELY:  faceSetExpression(EXPR_SAD);    break;
      case STATE_ANNOYED: faceSetExpression(EXPR_ANGRY);  break;
      case STATE_SCARED:  faceSetExpression(EXPR_SCARED); break;
      case STATE_SLEEPY:  faceSetExpression(EXPR_SLEEPY); break;
    }
  }

  // ── 4. Face detection → update tracking & state ──

  if (faceDetected) {
    lastInteractMs = millis();
    if (robotState == STATE_LONELY || robotState == STATE_SLEEPY) {
      _enterState(STATE_HAPPY);
    }
    headTrackFace(faceX, faceY);   // hanya atur tilt

    // Motor ikuti posisi wajah horizontal
    int errX = faceX - 160;
    if (abs(errX) > 50) {
      if (errX > 0) turnRight(SPEED_SLOW);
      else          turnLeft(SPEED_SLOW);
    } else {
      moveStop();
    }
  } else {
    headStopTracking();
    moveStop();
    if (now - lastInteractMs > TIMEOUT_LONELY_MS) {
      _enterState(STATE_LONELY);
    }
  }
  // ── 5. ANNOYED timeout → IDLE ──
  if (robotState == STATE_ANNOYED && now - stateEnteredMs > 4000) {
    _enterState(STATE_IDLE);
    return;
  }




  // ── Sleepy jika lama tidak ada interaksi ──
  if (
      robotState == STATE_LONELY &&
      !faceDetected &&
      (now - lastInteractMs > TIMEOUT_SLEEPY_MS)
    ) {

      _enterState(STATE_SLEEPY);
      return;
  }
  // ── 9B. Bangunkan dari tidur ──
  if (robotState == STATE_SLEEPY) {

      if (faceDetected) {

          audioPlay(SFX_GREET);

          faceBlink();

          _enterState(STATE_HAPPY);

          lastInteractMs = millis();

          return;
      }
  }

  // ── 10. Idle sound random ──
  if (robotState == STATE_IDLE || robotState == STATE_LONELY) {
    if (now - lastIdleSoundMs > nextIdleSoundMs) {
      lastIdleSoundMs  = now;
      nextIdleSoundMs  = random(IDLE_SOUND_MIN_MS, IDLE_SOUND_MAX_MS);
      audioPlayIdle();
    }
  }
}

// Init state machine
void stateMachineBegin() {
  lastInteractMs   = millis();
  lastIdleSoundMs  = millis();
  nextIdleSoundMs  = random(IDLE_SOUND_MIN_MS, IDLE_SOUND_MAX_MS);
  _enterState(STATE_IDLE);
}

