#ifndef MOVEMENT_H
#define MOVEMENT_H

// ── Pin L298N ──
#define PIN_IN1  14   // Motor kiri
#define PIN_IN2  27
#define PIN_IN3  26   // Motor kanan
#define PIN_IN4  25
#define PIN_ENA  32   // PWM kiri  (opsional — bisa jumper ke 5V di L298N)
#define PIN_ENB  33   // PWM kanan (opsional)

// LEDC channel untuk PWM ESP32
#define PWM_FREQ   1000
#define PWM_RES    8       // 8-bit = 0-255
#define CH_ENA     2
#define CH_ENB     3

// ── Kecepatan ──
#define SPEED_DEFAULT   85
#define SPEED_SLOW      55
#define SPEED_TURN      70

// Koreksi arah lurus
#define MOTOR_LEFT_TRIM    0
#define MOTOR_RIGHT_TRIM  -5

// Ramp
#define RAMP_STEP          2
#define RAMP_INTERVAL_MS  20

static int  currentSpeedL = 0;
static int  currentSpeedR = 0;
static int  targetSpeedL  = 0;
static int  targetSpeedR  = 0;
static unsigned long lastRampMs = 0;

// ────────────────────────────────────────────
void movementBegin() {
  pinMode(PIN_IN1, OUTPUT);
  pinMode(PIN_IN2, OUTPUT);
  pinMode(PIN_IN3, OUTPUT);
  pinMode(PIN_IN4, OUTPUT);

  // ESP32 core v3.x — API baru (ledcAttach menggantikan ledcSetup+ledcAttachPin)
  ledcAttach(PIN_ENA, PWM_FREQ, PWM_RES);
  ledcAttach(PIN_ENB, PWM_FREQ, PWM_RES);

  ledcWrite(PIN_ENA, 0);
  ledcWrite(PIN_ENB, 0);

  digitalWrite(PIN_IN1, LOW);
  digitalWrite(PIN_IN2, LOW);
  digitalWrite(PIN_IN3, LOW);
  digitalWrite(PIN_IN4, LOW);
}

// Mengirim arah dan kecepatan motor ke driver L298N
void _setMotors(int speedL, int speedR) {

  // Motor kiri
  if (speedL > 0) {
    digitalWrite(PIN_IN1, HIGH);
    digitalWrite(PIN_IN2, LOW);
  }
  else if (speedL < 0) {
    digitalWrite(PIN_IN1, LOW);
    digitalWrite(PIN_IN2, HIGH);
  }
  else {
    digitalWrite(PIN_IN1, LOW);
    digitalWrite(PIN_IN2, LOW);
  }

  // Motor kanan
  if (speedR > 0) {
    digitalWrite(PIN_IN3, HIGH);
    digitalWrite(PIN_IN4, LOW);
  }
  else if (speedR < 0) {
    digitalWrite(PIN_IN3, LOW);
    digitalWrite(PIN_IN4, HIGH);
  }
  else {
    digitalWrite(PIN_IN3, LOW);
    digitalWrite(PIN_IN4, LOW);
  }

  int pwmL = constrain(abs(speedL) + MOTOR_LEFT_TRIM, 0, 255);
  int pwmR = constrain(abs(speedR) + MOTOR_RIGHT_TRIM, 0, 255);

  ledcWrite(PIN_ENA, pwmL);
  ledcWrite(PIN_ENB, pwmR);
}

// ────────────────────────────────────────────
// Perintah gerak — set target, ramp dihandle di update()
void moveForward(int speed = SPEED_DEFAULT) {
  targetSpeedL =  speed;
  targetSpeedR =  speed;
}
void moveBackward(int speed = SPEED_DEFAULT) {
  targetSpeedL = -speed;
  targetSpeedR = -speed;
}
void turnLeft(int speed = SPEED_TURN) {
  targetSpeedL = speed * 0.45;
  targetSpeedR = speed;
}
void turnRight(int speed = SPEED_TURN) {
  targetSpeedL = speed;
  targetSpeedR = speed * 0.45;
}
void spinLeft(int speed = SPEED_TURN) {
  targetSpeedL = -speed;
  targetSpeedR = speed;
}
void spinRight(int speed = SPEED_TURN) {
  targetSpeedL = speed;
  targetSpeedR = -speed;
}
void moveStop() {
  targetSpeedL = 0;
  targetSpeedR = 0;
}



// ────────────────────────────────────────────
// Update — panggil di loop() tiap ~30ms
// ────────────────────────────────────────────
void movementUpdate() {
  unsigned long now = millis();


  // Ramp speed (akselerasi halus)
if (now - lastRampMs >= RAMP_INTERVAL_MS) {

  lastRampMs = now;

  if (currentSpeedL < targetSpeedL)
    currentSpeedL = min(currentSpeedL + RAMP_STEP, targetSpeedL);
  else if (currentSpeedL > targetSpeedL)
    currentSpeedL = max(currentSpeedL - RAMP_STEP, targetSpeedL);

  if (currentSpeedR < targetSpeedR)
    currentSpeedR = min(currentSpeedR + RAMP_STEP, targetSpeedR);
  else if (currentSpeedR > targetSpeedR)
    currentSpeedR = max(currentSpeedR - RAMP_STEP, targetSpeedR);

  _setMotors(currentSpeedL, currentSpeedR);
}
}
bool isMoving()  { return (currentSpeedL != 0 || currentSpeedR != 0); }

#endif // MOVEMENT_H
#ifndef FACE_ANIMATOR_H
#define FACE_ANIMATOR_H

#include <Arduino.h>
#include <Wire.h>
#include <U8g2lib.h>

// SH1106 128x64
U8G2_SH1106_128X64_NONAME_F_HW_I2C u8g2(U8G2_R0, U8X8_PIN_NONE);

typedef enum {
  EXPR_IDLE,
  EXPR_HAPPY,
  EXPR_SAD,
  EXPR_ANGRY,
  EXPR_SCARED,
  EXPR_SLEEPY,
  EXPR_BLINK,
  EXPR_CONFUSED
} Expression;

static Expression    currentExpr   = EXPR_IDLE;
static bool          isBlinking    = false;
static uint8_t       blinkPhase    = 0;  // 0=tutup 1=tahan 2=buka
static unsigned long lastBlinkMs   = 0;
static unsigned long blinkInterval = 4000;
static int8_t        pupilOffsetX  = 0;
static int8_t        pupilOffsetY  = 0;

// ── Posisi mata ──
// Layar 128x64, dua mata landscape kiri-kanan
// Mata kiri center: (38, 32)
// Mata kanan center: (90, 32)
#define EYE_L_X  38
#define EYE_R_X  90
#define EYE_Y    32
#define EYE_W    24   // lebar mata
#define EYE_H    20   // tinggi mata saat penuh terbuka

// ────────────────────────────────────────────
// Gambar satu mata dengan eyelid atas-bawah
// openH = tinggi bukaan saat ini (0=tutup, EYE_H=penuh)
// ────────────────────────────────────────────
void _eye(int16_t cx, int16_t cy,
          int16_t openH,
          int8_t  px, int8_t py) {

  if (openH <= 1) {
      u8g2.drawLine(
          cx - EYE_W/2,
          cy,
          cx + EYE_W/2,
          cy
      );
      return;
  }  // MATA TIDAK TERTUTUP TOTAL, ADA GARIS

  int16_t hw = EYE_W / 2;
  int16_t hh = openH / 2;
  if (hh < 1) hh = 1;

  int16_t x0 = cx - hw;
  int16_t y0 = cy - hh;
  int16_t w  = EYE_W;
  int16_t h  = hh * 2;

  // Pastikan tidak keluar layar
  if (y0 < 0) { h += y0; y0 = 0; }
  if (y0 + h > 64) h = 64 - y0;
  if (h <= 0) return;

  // Fill putih (mata terbuka)
  u8g2.setDrawColor(1);
  uint8_t radius = min(4, h / 2);
  if (radius < 1) radius = 1;

  u8g2.drawRBox(x0, y0, w, h, radius);

  // Pupil hitam — hanya gambar kalau mata cukup terbuka
  if (openH >= 6) {
    int16_t pr  = max(2, (int)hh - 3);
    if (pr > 7) pr = 7;
    int16_t pcx = cx + constrain((int)px, -(hw - pr - 2), (hw - pr - 2));
    int16_t pcy = cy + constrain((int)py, -(hh - pr - 1), (hh - pr - 1));

    // Klem pupil agar dalam batas area putih
    if (pcx - pr < x0 + 1)     pcx = x0 + 1 + pr;
    if (pcx + pr > x0 + w - 1) pcx = x0 + w - 1 - pr;
    if (pcy - pr < y0 + 1)     pcy = y0 + 1 + pr;
    if (pcy + pr > y0 + h - 1) pcy = y0 + h - 1 - pr;

    u8g2.setDrawColor(0);
    u8g2.drawDisc(pcx, pcy, pr);

    // Highlight
    u8g2.setDrawColor(1);
    u8g2.drawPixel(pcx + pr / 2, pcy - pr / 2);
  }

  u8g2.setDrawColor(1);
}

// ────────────────────────────────────────────
// Helper: gambar garis eyelid (tutup dari atas)
// fraction 0.0=tidak ada tutup, 1.0=tutup penuh
// ────────────────────────────────────────────
void _eyelid(int16_t cx, int16_t cy, float fraction) {
  if (fraction <= 0.0f) return;
  int16_t hw     = EYE_W / 2;
  int16_t lidH   = (int16_t)(EYE_H * fraction);
  int16_t y0     = cy - EYE_H / 2;
  u8g2.setDrawColor(0);
  u8g2.drawBox(cx - hw, y0, EYE_W, lidH);
  u8g2.setDrawColor(1);
}

// ────────────────────────────────────────────
// EKSPRESI
// ────────────────────────────────────────────

void _drawIdle(int16_t openH) {
  _eye(EYE_L_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);
  _eye(EYE_R_X, EYE_Y, openH, pupilOffsetX, pupilOffsetY);
}

void _drawHappy(int16_t openH) {
  // Mata ^ shape: gambar penuh lalu hapus bagian bawah
  _eye(EYE_L_X, EYE_Y, openH, 0, 0);
  _eye(EYE_R_X, EYE_Y, openH, 0, 0);
  // Hapus bagian bawah → bentuk ^
  int16_t cutY = EYE_Y;
  int16_t cutH = openH / 2 + 2;
  u8g2.setDrawColor(0);
  u8g2.drawBox(EYE_L_X - EYE_W/2, cutY, EYE_W, cutH);
  u8g2.drawBox(EYE_R_X - EYE_W/2, cutY, EYE_W, cutH);
  u8g2.setDrawColor(1);
  // Pipi
  if (openH > 8) {
    u8g2.drawDisc(14, 46, 3);
    u8g2.drawDisc(114, 46, 3);
  }
}

void _drawSad(int16_t openH) {
  int16_t sadH = max((int16_t)2, (int16_t)(openH * 6 / 10));
  _eye(EYE_L_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));
  _eye(EYE_R_X, EYE_Y + 3, sadH, pupilOffsetX, (int8_t)(pupilOffsetY + 2));
  // Alis sedih (miring ke luar-atas)
  if (openH > 6) {
    u8g2.drawLine(EYE_L_X - 10, EYE_Y - 14, EYE_L_X + 2, EYE_Y - 18);
    u8g2.drawLine(EYE_R_X + 10, EYE_Y - 14, EYE_R_X - 2, EYE_Y - 18);
  }
  // Air mata
  if (openH > 4) {
    u8g2.drawLine(EYE_L_X - 4, EYE_Y + sadH/2 + 1, EYE_L_X - 6, EYE_Y + sadH/2 + 8);
    u8g2.drawLine(EYE_R_X - 4, EYE_Y + sadH/2 + 1, EYE_R_X - 6, EYE_Y + sadH/2 + 8);
  }
}

void _drawAngry(int16_t openH) {
  int16_t angryH = max((int16_t)2, (int16_t)(openH * 55 / 100));
  _eye(EYE_L_X, EYE_Y, angryH, pupilOffsetX, pupilOffsetY);
  _eye(EYE_R_X, EYE_Y, angryH, pupilOffsetX, pupilOffsetY);
  // Alis marah (miring ke dalam-bawah)
  if (openH > 4) {
    u8g2.drawLine(EYE_L_X - 12, EYE_Y - 16, EYE_L_X + 4, EYE_Y - 11);
    u8g2.drawLine(EYE_L_X - 12, EYE_Y - 15, EYE_L_X + 4, EYE_Y - 10);
    u8g2.drawLine(EYE_R_X + 12, EYE_Y - 16, EYE_R_X - 4, EYE_Y - 11);
    u8g2.drawLine(EYE_R_X + 12, EYE_Y - 15, EYE_R_X - 4, EYE_Y - 10);
  }
}

void _drawScared(int16_t openH) {
  // Mata sangat besar + sedikit oval
  int16_t bigH = min((int16_t)(openH * 130 / 100), (int16_t)26);
  _eye(EYE_L_X, EYE_Y, bigH, 0, 0);
  _eye(EYE_R_X, EYE_Y, bigH, 0, 0);
  // Mulut gemetar
  if (openH > 4) {
    for (int x = 44; x < 85; x += 5) {
      u8g2.drawLine(x, 55, x + 2, 58);
      u8g2.drawLine(x + 2, 58, x + 5, 55);
    }
  }
}

void _drawSleepy(int16_t openH) {
  // Sleepy: mata hanya terbuka 35% dari tinggi normal
  // Gambar langsung dengan tinggi kecil — tidak pakai eyelid overlay
  int16_t sleepH = EYE_H * 35 / 100;

  // Gambar mata dengan tinggi sleepH, diposisikan di bagian BAWAH
  // (kelopak atas menutup dari atas ke bawah)
  int16_t hw = EYE_W / 2;

  // Mata kiri
  int16_t yBot = EYE_Y + EYE_H / 2;   // batas bawah mata
  int16_t yTop = yBot - sleepH;        // batas atas = dari bawah ke atas sebesar sleepH
  u8g2.setDrawColor(1);
  u8g2.drawRBox(EYE_L_X - hw, yTop, EYE_W, sleepH, 3);
  // Pupil
  if (sleepH >= 4) {
    int16_t pr = max(2, sleepH / 2 - 1);
    u8g2.setDrawColor(0);
    u8g2.drawDisc(EYE_L_X, yTop + sleepH / 2 + 1, pr);
    u8g2.setDrawColor(1);
  }

  // Mata kanan
  u8g2.setDrawColor(1);
  u8g2.drawRBox(EYE_R_X - hw, yTop, EYE_W, sleepH, 3);
  if (sleepH >= 4) {
    int16_t pr = max(2, sleepH / 2 - 1);
    u8g2.setDrawColor(0);
    u8g2.drawDisc(EYE_R_X, yTop + sleepH / 2 + 1, pr);
    u8g2.setDrawColor(1);
  }

  // ZZZ di pojok kanan atas
  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.setDrawColor(1);
  u8g2.drawStr(104, 20, "z");
  u8g2.drawStr(110, 12, "Z");
}

void _drawConfused(int16_t openH) {
  _eye(EYE_L_X, EYE_Y,     openH,          -2, 0);
  _eye(EYE_R_X, EYE_Y - 2, openH * 7 / 10,  2, -2);
  u8g2.setFont(u8g2_font_6x10_tr);
  u8g2.setDrawColor(1);
  u8g2.drawStr(60, 58, "?");
}

// ────────────────────────────────────────────
//  PUBLIC API
// ────────────────────────────────────────────

bool faceBegin() {
  u8g2.begin();
  u8g2.setDrawColor(1);
  u8g2.clearBuffer();
  u8g2.sendBuffer();
  return true;
}

void faceSetPupil(int panAngle, int tiltAngle) {
  pupilOffsetX = (int8_t)map(panAngle,  0, 180, -5, 5);
  pupilOffsetY = (int8_t)map(tiltAngle, 0, 180, -3, 3);
}

void faceSetExpression(Expression expr) {
  currentExpr = expr;
}

void faceBlink() {
  if (!isBlinking) {
    isBlinking  = true;
    blinkPhase  = 0;
    lastBlinkMs = millis();
  }
}

void faceRender() {
  unsigned long now = millis();

  // ── Auto blink ──
  if (
      currentExpr != EXPR_SLEEPY &&
      !isBlinking &&
      (now - lastBlinkMs > blinkInterval)) { 
    isBlinking    = true;
    blinkPhase    = 0;
    lastBlinkMs   = now;
    blinkInterval = (unsigned long)random(3500, 6000);
  }

  // ── Hitung openH saat ini ──
  // openH = tinggi bukaan mata dalam pixel (0..EYE_H)
  int16_t openH = EYE_H;  // default: penuh terbuka

  if (isBlinking) {
    unsigned long el = now - lastBlinkMs;
    if (blinkPhase == 0) {
      // Tutup: 100ms
      float t = (float)el / 100.0f;
      openH = (int16_t)(EYE_H * (1.0f - t));
      if (el >= 100) { blinkPhase = 1; lastBlinkMs = now; openH = 0; }
    } else if (blinkPhase == 1) {
      // Tahan tutup: 60ms
      openH = 0;
      if (el >= 60) { blinkPhase = 2; lastBlinkMs = now; }
    } else {
      // Buka: 130ms
      float t = (float)el / 130.0f;
      openH = (int16_t)(EYE_H * t);
      if (el >= 130) { isBlinking = false; openH = EYE_H; }
    }
    openH = constrain(openH, 0, EYE_H);
  }

  // ── Draw frame ──
  u8g2.clearBuffer();
  u8g2.setDrawColor(1);

  switch (currentExpr) {
    case EXPR_IDLE:     _drawIdle(openH);     break;
    case EXPR_HAPPY:    _drawHappy(openH);    break;
    case EXPR_SAD:      _drawSad(openH);      break;
    case EXPR_ANGRY:    _drawAngry(openH);    break;
    case EXPR_SCARED:   _drawScared(openH);   break;
    case EXPR_SLEEPY:   _drawSleepy(openH);   break;
    case EXPR_CONFUSED: _drawConfused(openH); break;
    case EXPR_BLINK:    _drawIdle(openH);     break;
    default:            _drawIdle(openH);     break;
  }

  u8g2.sendBuffer();
}

#endif // FACE_ANIMATOR_H

