//IPAddress camGateway(10, 137, 98, 222);
//IPAddress camSubnet(255, 255, 255, 0);

#define PWDN_GPIO_NUM     32
#define RESET_GPIO_NUM    -1
#define XCLK_GPIO_NUM      0
#define SIOD_GPIO_NUM     26
#define SIOC_GPIO_NUM     27
#define Y9_GPIO_NUM       35
#define Y8_GPIO_NUM       34
#define Y7_GPIO_NUM       39
#define Y6_GPIO_NUM       36
#define Y5_GPIO_NUM       21
#define Y4_GPIO_NUM       19
#define Y3_GPIO_NUM       18
#define Y2_GPIO_NUM        5
#define VSYNC_GPIO_NUM    25
#define HREF_GPIO_NUM     23
#define PCLK_GPIO_NUM     22
#define LED_GPIO_NUM       4

// ── Dua server terpisah ──
httpd_handle_t streamServer = NULL;   // port 81 → /stream
httpd_handle_t faceServer   = NULL;   // port 80 → /face

// ── Hasil deteksi (ditulis camTask, dibaca face_handler) ──
volatile bool  gFaceFound = false;
volatile int   gFaceX     = 160;
volatile int   gFaceY     = 120;

// ── JPEG terbaru dari camTask, dishare ke stream_handler ──
static uint8_t          *gJpg       = NULL;
static size_t            gJpgLen    = 0;
static SemaphoreHandle_t gJpgMutex  = NULL;
volatile int             gStreamClients = 0;   // >0 = ada yang nonton stream

// Deteksi hanya setiap DETECT_EVERY_N_FRAMES frame camTask — hemat CPU
#define DETECT_EVERY_N_FRAMES  3

bool initCamera() {
  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer   = LEDC_TIMER_0;
  config.pin_d0       = Y2_GPIO_NUM;
  config.pin_d1       = Y3_GPIO_NUM;
  config.pin_d2       = Y4_GPIO_NUM;
  config.pin_d3       = Y5_GPIO_NUM;
  config.pin_d4       = Y6_GPIO_NUM;
  config.pin_d5       = Y7_GPIO_NUM;
  config.pin_d6       = Y8_GPIO_NUM;
  config.pin_d7       = Y9_GPIO_NUM;
  config.pin_xclk     = XCLK_GPIO_NUM;
  config.pin_pclk     = PCLK_GPIO_NUM;
  config.pin_vsync    = VSYNC_GPIO_NUM;
  config.pin_href     = HREF_GPIO_NUM;
  config.pin_sscb_sda = SIOD_GPIO_NUM;
  config.pin_sscb_scl = SIOC_GPIO_NUM;
  config.pin_pwdn     = PWDN_GPIO_NUM;
  config.pin_reset    = RESET_GPIO_NUM;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_RGB565;   // butuh RGB565 untuk deteksi skin
  config.frame_size   = FRAMESIZE_QVGA;     // 320x240
  config.jpeg_quality = 15;                 // tidak dipakai untuk RGB565 (encode via frame2jpg)
  config.fb_count     = psramFound() ? 2 : 1;
  config.fb_location  = psramFound() ? CAMERA_FB_IN_PSRAM : CAMERA_FB_IN_DRAM;
  config.grab_mode    = CAMERA_GRAB_LATEST;

  if (esp_camera_init(&config) != ESP_OK) return false;

  sensor_t *s = esp_camera_sensor_get();
  s->set_hmirror(s, 1);
  s->set_vflip(s, 0);
  s->set_saturation(s, 1);
  s->set_brightness(s, 1);
  s->set_contrast(s, 1);
  s->set_gainceiling(s, GAINCEILING_4X);
  return true;
}

// ────────────────────────────────────────────
//  SKIN DETECTION — tanpa Serial print
// ────────────────────────────────────────────
bool detectSkinBlob(camera_fb_t *fb, int &outX, int &outY) {
  uint16_t *buf = (uint16_t *)fb->buf;
  int w = fb->width;
  int h = fb->height;

  int yStart = h * 10 / 100;
  int yEnd   = h * 75 / 100;

  long sumX = 0, sumY = 0, count = 0;

  for (int y = yStart; y < yEnd; y += 3) {
    for (int x = 10; x < w - 10; x += 3) {
      uint16_t px = buf[y * w + x];
      uint8_t r = ((px >> 11) & 0x1F) << 3;
      uint8_t g = ((px >> 5)  & 0x3F) << 2;
      uint8_t b = ( px        & 0x1F) << 3;

      bool isSkin = (
        r > 50  && r < 250 &&
        g > 20  && g < 220 &&
        b > 10  && b < 200 &&
        r > g   && r > b   &&
        (int)r - (int)g > 8 &&
        (int)r - (int)b > 12
      );

      if (isSkin) { sumX += x; sumY += y; count++; }
    }
  }

  if (count < 80) return false;
  outX = (int)(sumX / count);
  outY = (int)(sumY / count);
  return true;
}

// ────────────────────────────────────────────
//  CAM TASK — SATU-SATUNYA konsumen kamera
//  Selalu jalan: deteksi wajah + siapkan JPEG untuk stream
// ────────────────────────────────────────────
void camTask(void *param) {
  int frameCount = 0;
  for (;;) {
    camera_fb_t *fb = esp_camera_fb_get();
    if (!fb) { vTaskDelay(pdMS_TO_TICKS(10)); continue; }

    // ── Deteksi skin setiap N frame ──
    if (++frameCount >= DETECT_EVERY_N_FRAMES) {
      frameCount = 0;
      int fx = 160, fy = 120;
      if (detectSkinBlob(fb, fx, fy)) {
        gFaceX = fx; gFaceY = fy; gFaceFound = true;
      } else {
        gFaceFound = false;
      }
    }

    // ── Encode JPEG HANYA kalau ada yang nonton stream ──
    if (gStreamClients > 0) {
      uint8_t *out = NULL; size_t outLen = 0;
      bool ok = frame2jpg(fb, 70, &out, &outLen);
      esp_camera_fb_return(fb); fb = NULL;
      if (ok) {
        xSemaphoreTake(gJpgMutex, portMAX_DELAY);
        if (gJpg) free(gJpg);
        gJpg = out; gJpgLen = outLen;
        xSemaphoreGive(gJpgMutex);
      } else if (out) {
        free(out);
      }
    } else {
      esp_camera_fb_return(fb); fb = NULL;
      // Bebaskan JPEG tersimpan saat tak ada penonton → hemat heap
      if (gJpg) {
        xSemaphoreTake(gJpgMutex, portMAX_DELAY);
        if (gJpg) { free(gJpg); gJpg = NULL; gJpgLen = 0; }
        xSemaphoreGive(gJpgMutex);
      }
    }

    vTaskDelay(pdMS_TO_TICKS(20));   // cap ~50fps; deteksi ~ tiap 60ms
  }
}

// ── HTTP /face (port 80) ──
static esp_err_t face_handler(httpd_req_t *req) {
  char buf[64];
  if (gFaceFound)
    snprintf(buf, sizeof(buf),
             "{\"found\":true,\"x\":%d,\"y\":%d}", gFaceX, gFaceY);
  else
    snprintf(buf, sizeof(buf), "{\"found\":false}");
  httpd_resp_set_type(req, "application/json");
  httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
  return httpd_resp_send(req, buf, strlen(buf));
}

// ── MJPEG stream (port 81) ──
#define PART_BOUNDARY "novacamboundary"
static const char *STREAM_CONTENT_TYPE =
    "multipart/x-mixed-replace;boundary=" PART_BOUNDARY;
static const char *STREAM_BOUNDARY = "\r\n--" PART_BOUNDARY "\r\n";
static const char *STREAM_PART =
    "Content-Type: image/jpeg\r\nContent-Length: %u\r\n\r\n";

static esp_err_t stream_handler(httpd_req_t *req) {
  esp_err_t res = ESP_OK;
  char      part_buf[64];

  httpd_resp_set_type(req, STREAM_CONTENT_TYPE);
  httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");

  gStreamClients++;   // beritahu camTask untuk mulai encode JPEG

  while (true) {
    // Ambil salinan JPEG terbaru (copy di PSRAM supaya heap internal aman)
    uint8_t *buf = NULL; size_t len = 0;
    xSemaphoreTake(gJpgMutex, portMAX_DELAY);
    if (gJpg && gJpgLen) {
      buf = (uint8_t *)ps_malloc(gJpgLen);
      if (!buf) buf = (uint8_t *)malloc(gJpgLen);
      if (buf) { memcpy(buf, gJpg, gJpgLen); len = gJpgLen; }
    }
    xSemaphoreGive(gJpgMutex);

    if (!buf) { vTaskDelay(pdMS_TO_TICKS(20)); continue; }   // frame belum siap

    res = httpd_resp_send_chunk(req, STREAM_BOUNDARY, strlen(STREAM_BOUNDARY));
    if (res == ESP_OK) {
      size_t hlen = snprintf(part_buf, sizeof(part_buf),
                             STREAM_PART, (unsigned)len);
      res = httpd_resp_send_chunk(req, part_buf, hlen);
    }
    if (res == ESP_OK)
      res = httpd_resp_send_chunk(req, (const char *)buf, len);

    free(buf);
    if (res != ESP_OK) break;

    vTaskDelay(pdMS_TO_TICKS(33));   // ~30fps target
  }

  gStreamClients--;
  return res;
}

void startServers() {
  // ── Server stream (port 81) ──
  httpd_config_t c1 = HTTPD_DEFAULT_CONFIG();
  c1.server_port = 81;
  c1.ctrl_port   = 32768;
  if (httpd_start(&streamServer, &c1) == ESP_OK) {
    httpd_uri_t stream_uri = {"/stream", HTTP_GET, stream_handler, NULL};
    httpd_register_uri_handler(streamServer, &stream_uri);
    Serial.println("[CAM] Stream server OK port 81");
  }

  // ── Server face (port 80) — dipanggil robot N.O.V.A ──
  httpd_config_t c2 = HTTPD_DEFAULT_CONFIG();
  c2.server_port = 80;
  c2.ctrl_port   = 32769;   // WAJIB beda dari server pertama
  if (httpd_start(&faceServer, &c2) == ESP_OK) {
    httpd_uri_t face_uri = {"/face", HTTP_GET, face_handler, NULL};
    httpd_register_uri_handler(faceServer, &face_uri);
    Serial.println("[CAM] Face server OK port 80");
  }
}

// ── Auto-reconnect saat lepas dari hotspot ──
void onWiFiEvent(WiFiEvent_t event) {
  if (event == ARDUINO_EVENT_WIFI_STA_DISCONNECTED) {
    Serial.println("[WiFi] Putus — reconnect...");
    WiFi.reconnect();
  }
}

void setup() {
  // Matikan brownout detector — cegah reset/putus acak karena tegangan drop
  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0);

  Serial.begin(115200);
  pinMode(LED_GPIO_NUM, OUTPUT);
  digitalWrite(LED_GPIO_NUM, LOW);

  if (!initCamera()) {
    Serial.println("[CAM] GAGAL");
    delay(1000);
    ESP.restart();
  }
  Serial.println("[CAM] OK");

  gJpgMutex = xSemaphoreCreateMutex();

  WiFi.onEvent(onWiFiEvent);
  WiFi.mode(WIFI_STA);
  //WiFi.config(camIP, camGateway, camSubnet);
  WiFi.setSleep(false);          // JANGAN tidur — stream tetap lancar, tak putus
  WiFi.setAutoReconnect(true);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("[CAM] Connecting");
  unsigned long t0 = millis();
  while (WiFi.status() != WL_CONNECTED) {
    Serial.print(".");
    delay(500);
    if (millis() - t0 > 20000) {   // 20 dtk gagal → restart, jangan hang selamanya
      Serial.println("\n[CAM] WiFi timeout — restart");
      ESP.restart();
    }
  }
  Serial.println("\n[CAM] IP: " + WiFi.localIP().toString());

  startServers();

  // camTask = satu-satunya konsumen kamera, di Core 1
  xTaskCreatePinnedToCore(camTask, "camTask", 8192, NULL, 1, NULL, 1);
  Serial.println("[CAM] camTask started di Core 1");
}

void loop() {
  // Jaring pengaman kalau event reconnect gagal
  if (WiFi.status() != WL_CONNECTED) {
    WiFi.reconnect();
    delay(2000);
  }
  delay(1000);
}

/*
 * ══════════════════════════════════════════════════════
 *   N.O.V.A DIY — Main Controller (ESP32)
 *   Hardware:
 *     - ESP32 Dev Module (30-pin)
 *     - OLED 1.3" I2C SH1106 (addr 0x3C)
 *     - Servo SG90 x1 (pan kiri-kanan)
 *     - Motor TT x2 + L298N
 *     - LM2596 step-down → 5V
 *     - ESP32-CAM (WiFi, HTTP polling)
 *
 *   Fix v2:
 *     - parseCamData() dipindah ke Core 1 (tidak blocking Core 0)
 *     - Core 0 murni untuk kontrol hardware
 * ══════════════════════════════════════════════════════
 */

#include "FaceAnimator.h"
#include "HeadMotion.h"
#include "Movement.h"
#include "AudioPlayer.h"
#include "StateMachine.h"
#include "WiFiController.h"

#include <HTTPClient.h>
#define CAM_IP "10.137.98.36"

// ── Timing loop Core 0 ──
unsigned long prevStateMs      = 0;
unsigned long prevHeadMs       = 0;
unsigned long prevFaceRenderMs = 0;
unsigned long prevMotorMs      = 0;

// ══════════════════════════════════════════════════════
//  TASK WIFI + CAM POLL — berjalan di Core 1
//  Semua network di sini, Core 0 bebas untuk hardware
// ══════════════════════════════════════════════════════
void parseCamData() {
  HTTPClient http;
  http.begin("http://" CAM_IP "/face");
  http.setConnectTimeout(150);  // gagal cepat kalau CAM offline
  http.setTimeout(150);
  int code = http.GET();
  if (code == 200) {
    String body = http.getString();
    if (body.indexOf("\"found\":true") >= 0) {
      int xIdx = body.indexOf("\"x\":");
      int yIdx = body.indexOf("\"y\":");
      faceDetected = true;
      faceX = body.substring(xIdx + 4, body.indexOf(',', xIdx)).toInt();
      faceY = body.substring(yIdx + 4, body.indexOf('}', yIdx)).toInt();
    } else {
      faceDetected = false;
    }
  } else {
    // Kalau CAM tidak respond, anggap tidak ada wajah
    faceDetected = false;
  }
  http.end();
}

// Task server: HANYA melayani dashboard. Loop ketat, tidak pernah blocking.
// Prioritas lebih tinggi supaya command HP langsung diproses.
void taskServer(void *param) {
  wifiControllerBegin();
  for (;;) {
    wifiControllerHandle();
    vTaskDelay(2 / portTICK_PERIOD_MS);
  }
}

// Task CAM: polling wajah terpisah. Boleh blocking di sini —
// tidak mengganggu taskServer karena beda task.
void taskCam(void *param) {
  // Tunggu WiFi tersambung dulu (di-set oleh taskServer)
  while (WiFi.status() != WL_CONNECTED) {
    vTaskDelay(100 / portTICK_PERIOD_MS);
  }
  for (;;) {
    parseCamData();
    vTaskDelay(200 / portTICK_PERIOD_MS);   // poll ~5x/detik
  }
}

// ══════════════════════════════════════════════════════
//  SETUP
// ══════════════════════════════════════════════════════
void setup() {
  Serial.begin(115200);
  Serial.println("\n[N.O.V.A] Booting...");

  if (!faceBegin()) {
    Serial.println("[OLED] Gagal — cek wiring SDA/SCL");
  } else {
    Serial.println("[OLED] OK");
  }

  headBegin();
  Serial.println("[HEAD] Servo OK");

  movementBegin();
  Serial.println("[MOVE] Motor OK");

  if (!audioBegin()) {
    Serial.println("[AUDIO] Tidak aktif (dummy)");
  }

  stateMachineBegin();
  Serial.println("[SM] State machine OK");

  // Server dashboard: Core 1, prioritas 2 (lebih tinggi → command responsif)
  xTaskCreatePinnedToCore(
    taskServer, "ServerTask", 8192, NULL, 2, NULL, 1);

  // CAM poll: Core 1, prioritas 1 (boleh blocking, tidak ganggu server)
  xTaskCreatePinnedToCore(
    taskCam, "CamTask", 4096, NULL, 1, NULL, 1);

  Serial.println("[WIFI] Server + CAM task started di Core 1");
}

// ══════════════════════════════════════════════════════
//  LOOP — Core 0, murni hardware
//  Tidak ada network apapun di sini
// ══════════════════════════════════════════════════════
void loop() {
  unsigned long now = millis();

  // State machine + motor tracking: 50ms
  if (now - prevStateMs >= 50) {
    prevStateMs = now;
    stateMachineUpdate();
  }

  // Servo pan update: 20ms
  if (now - prevHeadMs >= 20) {
    prevHeadMs = now;
    headUpdate();
    faceSetPupil(headGetPan(), 90);  // sinkron pupil ke posisi pan
  }

  // Motor ramp: 30ms
  if (now - prevMotorMs >= 30) {
    prevMotorMs = now;
    movementUpdate();
  }

  // Render OLED: 50ms (~20fps)
  if (now - prevFaceRenderMs >= 50) {
    prevFaceRenderMs = now;
    faceRender();
  }
}

