<script>
// ── Kamera ──
let camRetryTimer = null;
function camOnline() {
  document.getElementById('camStatus').textContent = 'LIVE';
  document.getElementById('camStatus').classList.remove('offline');
  if (camRetryTimer) { clearTimeout(camRetryTimer); camRetryTimer = null; }
}
function camOffline() {
  document.getElementById('camStatus').textContent = 'Offline';
  document.getElementById('camStatus').classList.add('offline');
  if (!camRetryTimer) {
    camRetryTimer = setTimeout(() => {
      camRetryTimer = null;
      document.getElementById('camFeed').src =
        'http://10.137.98.36:81/stream?t=' + Date.now();
    }, 3000);
  }
}

// ── Kirim command ──
function send(cmd) {
  fetch('/cmd?action=' + cmd).catch(() => {});
}

// ── D-Pad multi-touch ──
let activeDirs  = new Set();
let holdInterval = null;

function computeCmd() {
  const f = activeDirs.has('forward'),  b = activeDirs.has('backward');
  const l = activeDirs.has('left'),     r = activeDirs.has('right');
  if (f && l) return 'fwd_left';
  if (f && r) return 'fwd_right';
  if (b && l) return 'back_left';
  if (b && r) return 'back_right';
  if (f) return 'forward';
  if (b) return 'backward';
  if (l) return 'left';
  if (r) return 'right';
  return 'stop';
}

function pressDir(dir) {
  activeDirs.add(dir);
  document.getElementById('btn-' +
    (dir === 'forward' ? 'fwd' : dir === 'backward' ? 'back' : dir))
    ?.classList.add('pressed');
  send(computeCmd());
  if (!holdInterval) holdInterval = setInterval(() => send(computeCmd()), 100);
}

function releaseDir(dir) {
  activeDirs.delete(dir);
  document.getElementById('btn-' +
    (dir === 'forward' ? 'fwd' : dir === 'backward' ? 'back' : dir))
    ?.classList.remove('pressed');
  if (activeDirs.size === 0) {
    clearInterval(holdInterval);
    holdInterval = null;
    send('stop');
  } else {
    send(computeCmd());
  }
}

// Lepas semua saat jari keluar layar
document.addEventListener('touchend',   () => { if(activeDirs.size) { activeDirs.clear(); clearInterval(holdInterval); holdInterval=null; send('stop'); }});
document.addEventListener('touchcancel',() => { if(activeDirs.size) { activeDirs.clear(); clearInterval(holdInterval); holdInterval=null; send('stop'); }});

// ── Poll status setiap 1 detik ──
function pollStatus() {
  fetch('/status')
    .then(r => r.json())
    .then(d => {
      document.getElementById('stateText').textContent = d.state;
      document.getElementById('stateVal').textContent  = d.state;
      document.getElementById('faceVal').textContent   = d.face ? 'YA ✓' : 'Tidak';
      document.getElementById('faceText').textContent  = d.face ? 'ada' : 'tidak ada';
    })
    .catch(() => {});
}
setInterval(pollStatus, 1000);
pollStatus();
</script>
