)rawhtml";

// ── HTTP Handlers ──
void handleRoot() {
  server.send_P(200, "text/html", HTML_PAGE);
}

void handleCmd() {
  if (!server.hasArg("action")) { server.send(400, "text/plain", "no action"); return; }
  String a = server.arg("action");
  if      (a == "forward")     pendingCommand = CMD_FORWARD;
  else if (a == "backward")    pendingCommand = CMD_BACKWARD;
  else if (a == "left")        pendingCommand = CMD_LEFT;
  else if (a == "right")       pendingCommand = CMD_RIGHT;
  else if (a == "fwd_left")    pendingCommand = CMD_FWD_LEFT;
  else if (a == "fwd_right")   pendingCommand = CMD_FWD_RIGHT;
  else if (a == "back_left")   pendingCommand = CMD_BACK_LEFT;
  else if (a == "back_right")  pendingCommand = CMD_BACK_RIGHT;
  else if (a == "stop")        pendingCommand = CMD_STOP;
  else if (a == "expr_happy")  pendingCommand = CMD_EXPR_HAPPY;
  else if (a == "expr_sad")    pendingCommand = CMD_EXPR_SAD;
  else if (a == "expr_angry")  pendingCommand = CMD_EXPR_ANGRY;
  else if (a == "expr_scared") pendingCommand = CMD_EXPR_SCARED;
  else if (a == "expr_sleepy") pendingCommand = CMD_EXPR_SLEEPY;
  server.send(200, "text/plain", "ok");
}

void handleStatus() {
  String stateStr;
  switch (robotState) {
    case STATE_IDLE:   stateStr = "IDLE";   break;
    case STATE_HAPPY:  stateStr = "HAPPY";  break;
    case STATE_LONELY: stateStr = "LONELY"; break;
    case STATE_SLEEPY: stateStr = "SLEEPY"; break;
    default:           stateStr = "IDLE";   break;
  }
  String json = "{\"state\":\"" + stateStr + "\",\"face\":"
                + (faceDetected ? "true" : "false") + "}";
  server.send(200, "application/json", json);
}

void handleNotFound() { server.send(404, "text/plain", "not found"); }

void wifiControllerBegin() {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(true);
  delay(1000);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  Serial.print("[WiFi] Connecting");
  while (WiFi.status() != WL_CONNECTED) { Serial.print("."); delay(500); }
  Serial.println("\n[WiFi] Connected: " + WiFi.localIP().toString());

  server.on("/",       handleRoot);
  server.on("/cmd",    handleCmd);
  server.on("/status", handleStatus);
  server.onNotFound(handleNotFound);
  server.begin();
}

void wifiControllerHandle() { server.handleClient(); }

#endif // WIFI_CONTROLLER_H

