      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: "Sistem Informasi Sekolah", size: 28, font: "Arial", color: "595959" })]
      }),
      spacer(), spacer(),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: "Materi: Relasi User, Kolom Level, Role-based Access", size: 22, font: "Arial", color: "595959", italics: true })]
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // ===== TUJUAN PEMBELAJARAN =====
      h1("Tujuan Pembelajaran"),
      p("Setelah mengikuti praktikum ini, mahasiswa diharapkan mampu:"),
      spacer(),
      numbered("Menambahkan kolom level pada tabel users untuk membedakan peran (role) pengguna."),
      numbered("Menambahkan kolom user_id pada tabel persekolahans sebagai foreign key ke tabel users."),
      numbered("Membuat relasi antar model User dan Persekolahan menggunakan Eloquent ORM."),
