namespace App\Http\Controllers;

use Illuminate\Http\Request;
use App\Models\Persekolahan;
use App\Models\Siswa;
use App\Models\Guru;
use App\Models\Matapelajaran;

class PersekolahanController extends Controller
{
    // =============================================
    // INDEX - Menampilkan semua data persekolahan
    // =============================================
    public function index()
    {
        $persekolahan = Persekolahan::with([
            'siswa',
            'guru',
            'matapelajaran',
            'user',        // <-- relasi user yang baru ditambahkan
        ])->get();

        return view('persekolahan.dashboard', compact('persekolahan'));
    }

    // =============================================
    // CREATE - Menampilkan form tambah data
    // =============================================
    public function create()
    {
        $siswas          = Siswa::all();
        $gurus           = Guru::all();
        $matapelajarans  = Matapelajaran::all();

        return view('persekolahan.create', compact(
            'siswas', 'gurus', 'matapelajarans'
        ));
    }

    // =============================================
    // STORE - Menyimpan data baru
    // =============================================
    public function store(Request $request)
    {
        $request->validate([
            'siswa_id'         => 'required',
            'guru_id'          => 'required',
            'matapelajaran_id' => 'required',
        ]);

        Persekolahan::create([
            'siswa_id'         => $request->siswa_id,
            'guru_id'          => $request->guru_id,
            'matapelajaran_id' => $request->matapelajaran_id,
            'user_id'          => auth()->id(),
        ]);

        return redirect()->route('persekolahan.index')
                         ->with('success', 'Data berhasil disimpan!');
    }

    // =============================================
    // EDIT - Menampilkan form edit data
    // =============================================
    public function edit($id)
    {
        $persekolahan    = Persekolahan::findOrFail($id);
        $siswas          = Siswa::all();
        $gurus           = Guru::all();
        $matapelajarans  = Matapelajaran::all();

        return view('persekolahan.edit', compact(
            'persekolahan', 'siswas', 'gurus', 'matapelajarans'
        ));
    }

    // =============================================
    // UPDATE - Menyimpan perubahan data
    // =============================================
    public function update(Request $request, $id)
    {
        $request->validate([
            'siswa_id'         => 'required',
            'guru_id'          => 'required',
            'matapelajaran_id' => 'required',
        ]);

        $persekolahan = Persekolahan::findOrFail($id);
        $persekolahan->update([
            'siswa_id'         => $request->siswa_id,
            'guru_id'          => $request->guru_id,
            'matapelajaran_id' => $request->matapelajaran_id,
            // user_id tidak diupdate, tetap pakai yang pertama input
        ]);

        return redirect()->route('persekolahan.index')
                         ->with('success', 'Data berhasil diupdate!');
    }

    // =============================================
    // DESTROY - Menghapus data
    // =============================================
    public function destroy($id)
    {
        $persekolahan = Persekolahan::findOrFail($id);
        $persekolahan->delete();

        return redirect()->route('persekolahan.index')
                         ->with('success', 'Data berhasil dihapus!');
    }
