    { label: "Error Rate", value: "<0.1%", desc: "Kegagalan transaksi di bawah batas" },
    { label: "Uptime", value: "99.9%", desc: "Sistem tersedia sesuai target" },
    { label: "Zero Data Loss", value: "✅", desc: "Tidak ada data hilang (retry/queue)" },
