const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Quiz 2 – Project Integration System";
pres.author = "Abdan Rifai";

// Color palette: Dark navy + teal + white
const C = {
  navy:    "0A1931",
  teal:    "028090",
  mint:    "02C39A",
  white:   "FFFFFF",
  light:   "F0F7F8",
  gray:    "64748B",
  darkgray:"334155",
  accent:  "F9A825",
};

// ─────────────────────────────────────────────
// SLIDE 1 – COVER
// ─────────────────────────────────────────────
{
  const s = pres.addSlide();
  s.background = { color: C.navy };

  // Top-left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Bottom accent strip
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Label tag
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 0.7, w: 2.6, h: 0.45,
    fill: { color: C.mint }, line: { color: C.mint }
  });
  s.addText("PROJECT INTEGRATION SYSTEM", {
    x: 0.7, y: 0.7, w: 2.6, h: 0.45,
    fontSize: 7, bold: true, color: C.navy, align: "center", valign: "middle", margin: 0
  });

  // Main title
  s.addText("QUIZ 2", {
    x: 0.7, y: 1.3, w: 9, h: 1.1,
    fontSize: 60, bold: true, color: C.white, fontFace: "Calibri", margin: 0
  });
  s.addText("Project Integration System", {
    x: 0.7, y: 2.45, w: 8, h: 0.7,
    fontSize: 24, color: C.mint, fontFace: "Calibri", margin: 0
  });

  // Divider
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 3.25, w: 4, h: 0.05,
    fill: { color: C.gray }, line: { color: C.gray }
  });

  // Student info
  s.addText([
    { text: "Abdan Rifai", options: { bold: true, breakLine: true } },
    { text: "NPM: 2301170017  |  Teknologi Informasi", options: { color: C.gray, breakLine: true } },
    { text: "Mata Kuliah: Project Integration System", options: { color: C.gray } }
  ], {
    x: 0.7, y: 3.45, w: 7, h: 1.35,
    fontSize: 14, color: C.white, fontFace: "Calibri", margin: 0
  });

  // Bottom label
  s.addText("5 SOAL  |  ANALISIS MENDALAM", {
    x: 0.35, y: 5.0, w: 9.65, h: 0.625,
    fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
  });
}

// ─────────────────────────────────────────────
// Helper: section cover slide
// ─────────────────────────────────────────────
function addSectionSlide(num, title, subtitle) {
  const s = pres.addSlide();
  s.background = { color: C.teal };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 1.0,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.8, w: 10, h: 0.825,
    fill: { color: C.navy }, line: { color: C.navy }
  });

  s.addText(`SOAL ${num}`, {
    x: 0.5, y: 0, w: 9, h: 1.0,
    fontSize: 13, bold: true, color: C.mint, align: "left", valign: "middle", charSpacing: 4, margin: 0
  });

  s.addText(title, {
    x: 0.6, y: 1.2, w: 8.8, h: 2.2,
    fontSize: 30, bold: true, color: C.white, fontFace: "Calibri", valign: "middle", margin: 0
  });

  s.addText(subtitle, {
    x: 0.6, y: 3.6, w: 8.8, h: 1.0,
    fontSize: 15, color: C.navy, fontFace: "Calibri", margin: 0
  });

  return s;
}

// Helper: content slide
function addContentSlide(title, soalLabel) {
  const s = pres.addSlide();
  s.background = { color: C.light };

  // Top bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.75,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addText(soalLabel, {
    x: 0.2, y: 0, w: 2, h: 0.75,
    fontSize: 10, bold: true, color: C.mint, valign: "middle", margin: 0
  });
  s.addText(title, {
    x: 2.0, y: 0, w: 7.8, h: 0.75,
    fontSize: 13, bold: true, color: C.white, valign: "middle", margin: 0
  });

  return s;
}

// ─────────────────────────────────────────────
// SLIDE 2 – SOAL 1 SECTION
// ─────────────────────────────────────────────
addSectionSlide("01", "Analisis Kebutuhan\nSebelum Integrasi Sistem", "Langkah-langkah & Risiko jika tidak dilakukan dengan tepat");

// ─────────────────────────────────────────────
// SLIDE 3 – Langkah Analisis Kebutuhan
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Langkah-langkah Analisis Kebutuhan", "SOAL 01");

  const steps = [
    { num: "1", label: "Identifikasi Stakeholder", desc: "Tentukan pihak berkepentingan (user, manajemen, IT) dan kumpulkan kebutuhan tiap pihak." },
    { num: "2", label: "Inventarisasi Sistem", desc: "Pelajari sistem yang akan diintegrasikan: teknologi, format data, kapasitas, dan batasannya." },
    { num: "3", label: "Definisi Scope", desc: "Tentukan sistem mana yang diintegrasikan, data apa yang dipertukarkan, dan proses bisnis terdampak." },
    { num: "4", label: "Analisis Kebutuhan", desc: "Fungsional: alur data, transformasi, trigger. Non-fungsional: keamanan, performa, ketersediaan." },
    { num: "5", label: "Dokumentasi & Validasi", desc: "Buat dokumen kebutuhan dan validasi bersama stakeholder sebelum implementasi dimulai." },
  ];

  steps.forEach((st, i) => {
    const x = 0.3;
    const y = 0.95 + i * 0.88;
    const w = 9.4;
    const h = 0.78;

    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: h, h,
      fill: { color: i % 2 === 0 ? C.teal : C.navy }, line: { color: i % 2 === 0 ? C.teal : C.navy }
    });
    s.addText(st.num, {
      x, y, w: h, h,
      fontSize: 20, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });

    s.addShape(pres.shapes.RECTANGLE, {
      x: x + h, y, w: w - h, h,
      fill: { color: C.white }, line: { color: "D1D5DB" }
    });
    s.addText([
      { text: st.label + "  ", options: { bold: true, color: C.navy } },
      { text: st.desc, options: { color: C.darkgray } }
    ], {
      x: x + h + 0.12, y, w: w - h - 0.12, h,
      fontSize: 11, valign: "middle", margin: 0
    });
  });
}

// ─────────────────────────────────────────────
// SLIDE 4 – Risiko jika Analisis Tidak Tepat
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Risiko jika Analisis Kebutuhan Tidak Tepat", "SOAL 01");

  const risks = [
    { icon: "⚠", title: "Inkompatibilitas Data", desc: "Sistem tidak bisa saling membaca format data satu sama lain (JSON vs XML)." },
    { icon: "📈", title: "Scope Creep", desc: "Pembengkakan biaya dan waktu akibat permintaan yang terus berubah." },
    { icon: "🔓", title: "Celah Keamanan", desc: "Data sensitif terekspos karena kebutuhan keamanan tidak teridentifikasi." },
    { icon: "⏱", title: "Downtime Sistem", desc: "Operasional terganggu karena integrasi yang tidak stabil." },
    { icon: "❌", title: "Kegagalan Proyek", desc: "Proyek gagal total karena fondasi analisis yang lemah." },
  ];

  // 2-col grid
  const cols = [
    { x: 0.3, y: 0.9,  w: 4.5, h: 0.9 },
    { x: 5.1, y: 0.9,  w: 4.5, h: 0.9 },
    { x: 0.3, y: 1.95, w: 4.5, h: 0.9 },
    { x: 5.1, y: 1.95, w: 4.5, h: 0.9 },
  ];

  risks.slice(0, 4).forEach((r, i) => {
    const pos = cols[i];
    s.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: pos.w, h: pos.h,
      fill: { color: C.white },
      line: { color: "E2E8F0", pt: 1 },
      shadow: { type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.08 }
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: 0.07, h: pos.h,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(r.icon + " " + r.title, {
      x: pos.x + 0.15, y: pos.y + 0.05, w: pos.w - 0.2, h: 0.32,
      fontSize: 11, bold: true, color: C.navy, margin: 0
    });
    s.addText(r.desc, {
      x: pos.x + 0.15, y: pos.y + 0.38, w: pos.w - 0.2, h: 0.48,
      fontSize: 10, color: C.darkgray, margin: 0
    });
  });

  // 5th risk – full width
  const r5 = risks[4];
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 3.0, w: 9.3, h: 0.85,
    fill: { color: "FEF2F2" }, line: { color: "FECACA" }
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 3.0, w: 0.07, h: 0.85,
    fill: { color: "DC2626" }, line: { color: "DC2626" }
  });
  s.addText(r5.icon + " " + r5.title + " — ", {
    x: 0.45, y: 3.0, w: 2.5, h: 0.85,
    fontSize: 12, bold: true, color: "DC2626", valign: "middle", margin: 0
  });
  s.addText(r5.desc, {
    x: 2.85, y: 3.0, w: 6.7, h: 0.85,
    fontSize: 12, color: C.darkgray, valign: "middle", margin: 0
  });

  // Example callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 4.0, w: 9.3, h: 1.25,
    fill: { color: "EFF6FF" }, line: { color: "BFDBFE" }
  });
  s.addText("💡 Contoh Nyata:", {
    x: 0.5, y: 4.05, w: 2, h: 0.35,
    fontSize: 10, bold: true, color: C.navy, margin: 0
  });
  s.addText(
    "Jika kebutuhan format data tidak dianalisis, sistem penjualan (JSON) tidak dapat berkomunikasi dengan sistem akuntansi (XML), sehingga data dapat hilang atau rusak saat dipertukarkan.",
    {
      x: 0.5, y: 4.38, w: 9, h: 0.78,
      fontSize: 10.5, color: C.darkgray, margin: 0
    }
  );
}

// ─────────────────────────────────────────────
// SLIDE 5 – SOAL 2 SECTION
// ─────────────────────────────────────────────
addSectionSlide("02", "Transformasi Data\nAntar Sistem", "Proses ETL & Studi Kasus Rumah Sakit");

// ─────────────────────────────────────────────
// SLIDE 6 – ETL Process
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Proses Transformasi Data (ETL)", "SOAL 02");

  // ETL boxes
  const etl = [
    { letter: "E", word: "Extract", color: C.navy, desc: "Data diambil dari sistem sumber: file CSV, REST API, atau database." },
    { letter: "T", word: "Transform", color: C.teal, desc: "Data dikonversi: ubah format, mapping field berbeda nama, validasi, bersihkan duplikat." },
    { letter: "L", word: "Load", color: C.mint, desc: "Data yang sudah ditransformasi dimuat ke sistem tujuan (database, ERP, dsb.)." },
  ];

  etl.forEach((e, i) => {
    const x = 0.5 + i * 3.1;
    const y = 0.9;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 2.8, h: 2.4,
      fill: { color: e.color }, line: { color: e.color },
      shadow: { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.15 }
    });
    s.addText(e.letter, {
      x, y: y + 0.1, w: 2.8, h: 1.0,
      fontSize: 52, bold: true, color: C.white, align: "center", margin: 0
    });
    s.addText(e.word, {
      x, y: y + 1.05, w: 2.8, h: 0.45,
      fontSize: 16, bold: true, color: C.white, align: "center", margin: 0
    });
    s.addText(e.desc, {
      x, y: y + 1.55, w: 2.8, h: 0.75,
      fontSize: 10, color: C.white, align: "center", margin: 4
    });

    // Arrow
    if (i < 2) {
      s.addShape(pres.shapes.RECTANGLE, {
        x: x + 2.82, y: y + 1.0, w: 0.25, h: 0.08,
        fill: { color: C.gray }, line: { color: C.gray }
      });
    }
  });

  // Techniques
  s.addText("Teknik Transformasi Umum", {
    x: 0.4, y: 3.45, w: 9, h: 0.4,
    fontSize: 13, bold: true, color: C.navy, margin: 0
  });

  const techniques = [
    "📋  Parsing & Serialisasi — Data di-parse lalu di-serialize ulang ke format tujuan (CSV → XML)",
    "🔗  Mapping Field — Field berbeda nama dipetakan (nama_pasien → <PatientName>)",
    "🔄  Middleware / ESB — Software seperti MuleSoft atau Apache Camel sebagai jembatan antar sistem",
    "✅  Validasi Data — Data dicek kelengkapan dan kebenaran format sebelum dimuat",
  ];

  techniques.forEach((t, i) => {
    const x = i < 2 ? 0.4 : 5.1;
    const y = 3.9 + (i % 2) * 0.65;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 4.4, h: 0.55,
      fill: { color: C.white }, line: { color: "E2E8F0" }
    });
    s.addText(t, { x: x + 0.1, y, w: 4.2, h: 0.55, fontSize: 10, color: C.darkgray, valign: "middle", margin: 0 });
  });
}

// ─────────────────────────────────────────────
// SLIDE 7 – Studi Kasus RS
// ─────────────────────────────────────────────
{
