    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addText("📋  SKENARIO: Klinik/Puskesmas (CSV)  →  Middleware  →  Rumah Sakit (XML)", {
    x: 0.3, y: 0.85, w: 9.4, h: 0.55,
    fontSize: 11, bold: true, color: C.mint, align: "center", valign: "middle", margin: 0
  });

  const flowSteps = [
    { n: "1", t: "Terima CSV", d: "Middleware menerima file CSV dari klinik.\nContoh: 1001, Budi Santoso, 45, Hipertensi" },
    { n: "2", t: "Parsing", d: "Setiap baris CSV di-parse menjadi struktur data internal (object/dict)." },
    { n: "3", t: "Mapping", d: "Field CSV dipetakan ke elemen XML:\nnama → <PatientName>, usia → <Age>" },
    { n: "4", t: "Validasi", d: "Cek kelengkapan field wajib, format usia (angka), dsb." },
    { n: "5", t: "Serialisasi", d: "Data dikonversi menjadi dokumen XML terstruktur sesuai skema RS." },
    { n: "6", t: "Load ke RS", d: "Dokumen XML dikirim dan disimpan ke database rekam medis RS." },
  ];

  flowSteps.forEach((f, i) => {
    const x = 0.3 + (i % 3) * 3.15;
    const y = 1.55 + Math.floor(i / 3) * 1.45;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 2.9, h: 1.28,
      fill: { color: C.white }, line: { color: "D1D5DB" },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.42, h: 0.42,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(f.n, {
      x, y, w: 0.42, h: 0.42,
      fontSize: 14, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(f.t, {
      x: x + 0.48, y: y + 0.05, w: 2.35, h: 0.35,
      fontSize: 11, bold: true, color: C.navy, margin: 0
    });
    s.addText(f.d, {
      x: x + 0.08, y: y + 0.44, w: 2.75, h: 0.78,
      fontSize: 9.5, color: C.darkgray, margin: 0
    });
  });

  // Benefit callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 4.85, w: 9.4, h: 0.63,
    fill: { color: "ECFDF5" }, line: { color: C.mint }
  });
  s.addText("✅  Manfaat: Sistem klinik tidak perlu diubah. RS tetap pakai standar XML. Transformasi otomatis, cepat, dan minim human error.", {
    x: 0.5, y: 4.85, w: 9.1, h: 0.63,
    fontSize: 10.5, color: C.darkgray, valign: "middle", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 8 – SOAL 3 SECTION
// ─────────────────────────────────────────────
addSectionSlide("03", "API vs Integrasi\nDatabase Langsung", "Perbandingan dari sisi Keamanan, Fleksibilitas & Kemudahan Pengembangan");

// ─────────────────────────────────────────────
// SLIDE 9 – Comparison Table
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Perbandingan API vs Database Langsung", "SOAL 03");

  const rows = [
    ["Aspek", "API", "Database Langsung"],
    ["Keamanan", "✅ Tinggi — akses dikontrol via token/OAuth, hanya endpoint tertentu terbuka", "⚠ Risiko — akses penuh ke DB, rentan SQL injection & kebocoran data"],
    ["Fleksibilitas", "✅ Sangat fleksibel — bisa dipakai platform apapun (web, mobile, IoT)", "❌ Terbatas — hanya sistem dengan driver & akses jaringan ke DB yang sama"],
    ["Kemudahan Dev", "✅ Mudah — ada dokumentasi, versioning API memudahkan update", "❌ Sulit — perubahan skema DB berdampak ke semua sistem terhubung"],
    ["Performa", "⚠ Ada overhead HTTP, latency lebih tinggi", "✅ Lebih cepat untuk query besar di jaringan internal"],
    ["Skalabilitas", "✅ Mudah diskalakan, bisa load balancing", "❌ Sulit — koneksi DB jadi bottleneck saat trafik tinggi"],
  ];

  const colW = [1.8, 3.75, 3.75];
  const rowH = 0.69;
  const startX = 0.35;
  const startY = 0.85;

  rows.forEach((row, ri) => {
    row.forEach((cell, ci) => {
      const x = startX + colW.slice(0, ci).reduce((a, b) => a + b, 0);
      const y = startY + ri * rowH;
      const isHeader = ri === 0;
      const isAspect = ci === 0;

      const bg = isHeader ? C.navy : isAspect ? C.teal : (ri % 2 === 0 ? C.white : "F8FAFC");
      s.addShape(pres.shapes.RECTANGLE, {
        x, y, w: colW[ci], h: rowH,
        fill: { color: bg }, line: { color: "D1D5DB" }
      });
      s.addText(cell, {
        x: x + 0.08, y, w: colW[ci] - 0.1, h: rowH,
        fontSize: isHeader ? 12 : 10.5,
        bold: isHeader || isAspect,
        color: (isHeader || isAspect) ? C.white : C.darkgray,
        valign: "middle", margin: 0
      });
    });
  });

  // Conclusion
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 5.05, w: 9.3, h: 0.47,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addText("💡 Kesimpulan: API lebih direkomendasikan untuk integrasi sistem modern. Database langsung hanya tepat untuk kebutuhan internal performa tinggi & lingkungan sangat terkontrol.", {
    x: 0.5, y: 5.05, w: 9.1, h: 0.47,
    fontSize: 10, color: C.white, valign: "middle", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 10 – SOAL 4 SECTION
// ─────────────────────────────────────────────
addSectionSlide("04", "Rancangan Integrasi\nTiga Sistem Perusahaan", "Penjualan ↔ Gudang ↔ Akuntansi via Middleware");

// ─────────────────────────────────────────────
// SLIDE 11 – Architecture & Data Flow
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Arsitektur & Alur Data Integrasi", "SOAL 04");

  // Draw 3 system boxes
  const systems = [
    { label: "PENJUALAN", items: ["Input pesanan", "Data pelanggan", "Status transaksi"], x: 0.3, color: C.navy },
    { label: "GUDANG", items: ["Stok barang", "Pengiriman", "Retur barang"], x: 3.65, color: C.teal },
    { label: "AKUNTANSI", items: ["Jurnal otomatis", "Laporan keuangan", "Rekonsiliasi stok"], x: 7.0, color: C.mint },
  ];

  systems.forEach((sys) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: sys.x, y: 0.85, w: 2.6, h: 0.42,
      fill: { color: sys.color }, line: { color: sys.color }
    });
    s.addText(sys.label, {
      x: sys.x, y: 0.85, w: 2.6, h: 0.42,
      fontSize: 12, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: sys.x, y: 1.27, w: 2.6, h: 1.15,
      fill: { color: C.white }, line: { color: "D1D5DB" }
    });
    sys.items.forEach((item, ii) => {
      s.addText("▸  " + item, {
        x: sys.x + 0.1, y: 1.32 + ii * 0.37, w: 2.45, h: 0.35,
        fontSize: 10, color: C.darkgray, margin: 0
      });
    });
  });

  // Middleware box center
  s.addShape(pres.shapes.RECTANGLE, {
    x: 3.35, y: 2.62, w: 3.3, h: 0.62,
    fill: { color: C.accent }, line: { color: C.accent },
    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.15 }
  });
  s.addText("⚙  MIDDLEWARE / INTEGRATION LAYER", {
    x: 3.35, y: 2.62, w: 3.3, h: 0.62,
    fontSize: 11, bold: true, color: C.navy, align: "center", valign: "middle", margin: 0
  });

  // Flow steps
  const flows = [
    { n: "1", t: "Pesanan Masuk", d: "Penjualan → Gudang: Order baru → notifikasi gudang, stok diperbarui otomatis." },
    { n: "2", t: "Konfirmasi Pengiriman", d: "Gudang → Penjualan: Barang terkirim → status pesanan & notifikasi pelanggan diperbarui." },
    { n: "3", t: "Pencatatan Keuangan", d: "Penjualan → Akuntansi: Data transaksi → jurnal debit/kredit otomatis, laporan real-time." },
    { n: "4", t: "Rekonsiliasi Stok", d: "Gudang → Akuntansi: Nilai stok dicocokkan dengan nilai aset di neraca secara berkala." },
  ];

  flows.forEach((f, i) => {
    const x = i < 2 ? 0.3 : 5.05;
    const y = 3.4 + (i % 2) * 0.97;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 4.4, h: 0.85,
      fill: { color: C.white }, line: { color: "E2E8F0" }
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.38, h: 0.38,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(f.n, { x, y, w: 0.38, h: 0.38, fontSize: 13, bold: true, color: C.white, align: "center", valign: "middle", margin: 0 });
    s.addText(f.t, { x: x + 0.45, y: y + 0.04, w: 3.85, h: 0.3, fontSize: 10.5, bold: true, color: C.navy, margin: 0 });
    s.addText(f.d, { x: x + 0.1, y: y + 0.38, w: 4.22, h: 0.44, fontSize: 9.5, color: C.darkgray, margin: 0 });
  });
}

// ─────────────────────────────────────────────
// SLIDE 12 – Manfaat Integrasi
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Manfaat Integrasi Tiga Sistem bagi Perusahaan", "SOAL 04");

  const benefits = [
    { icon: "⏱", title: "Hemat Waktu & SDM", desc: "Eliminasi input data manual, menghemat waktu dan sumber daya manusia secara signifikan." },
    { icon: "📊", title: "Data Real-Time", desc: "Data tersedia di semua sistem secara real-time, mendukung pengambilan keputusan yang lebih cepat." },
