      shadow: { type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
    });
    // icon bg
    s.addShape(pres.shapes.RECTANGLE, {
      x: x + 0.1, y: y + 0.12, w: 0.6, h: 0.6,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(b.icon, {
      x: x + 0.1, y: y + 0.12, w: 0.6, h: 0.6,
      fontSize: 18, align: "center", valign: "middle", margin: 0
    });
    s.addText(b.title, {
      x: x + 0.78, y: y + 0.15, w: 2.1, h: 0.55,
      fontSize: 11.5, bold: true, color: C.navy, margin: 0
    });
    s.addText(b.desc, {
      x: x + 0.1, y: y + 0.82, w: 2.75, h: 0.95,
      fontSize: 10, color: C.darkgray, margin: 0
    });
  });
}

// ─────────────────────────────────────────────
// SLIDE 13 – SOAL 5 SECTION
// ─────────────────────────────────────────────
addSectionSlide("05", "Pengujian Sistem\nTerintegrasi", "Metode, Indikator Keberhasilan & Dampak Kualitas");

// ─────────────────────────────────────────────
// SLIDE 14 – Testing Methods
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Metode Pengujian Sistem Terintegrasi", "SOAL 05");

  const methods = [
    { n: "01", name: "Integration Testing", desc: "Menguji interaksi dua atau lebih komponen/sistem saat digabungkan. Fokus pada antarmuka & pertukaran data.", color: C.navy },
    { n: "02", name: "End-to-End (E2E) Testing", desc: "Mensimulasikan alur bisnis nyata dari awal hingga akhir untuk memastikan seluruh proses berjalan lintas sistem.", color: C.teal },
    { n: "03", name: "API Testing", desc: "Menggunakan Postman/Newman untuk menguji endpoint, response code, format data, dan autentikasi API.", color: C.mint },
    { n: "04", name: "Performance Testing", desc: "Menguji kecepatan respons, throughput, dan stabilitas di bawah beban tinggi (load testing, stress testing).", color: "7C3AED" },
    { n: "05", name: "Regression Testing", desc: "Memastikan perubahan pada satu sistem tidak merusak fungsionalitas sistem lain yang terintegrasi.", color: "D97706" },
    { n: "06", name: "Security Testing", desc: "Menguji keamanan titik integrasi: autentikasi, enkripsi data, proteksi injeksi dan akses tidak sah.", color: "DC2626" },
  ];

  methods.forEach((m, i) => {
    const x = 0.3 + (i % 2) * 4.8;
    const y = 0.88 + Math.floor(i / 2) * 1.55;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 4.45, h: 1.38,
      fill: { color: C.white }, line: { color: "E2E8F0" },
      shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
    });
    s.addShape(pres.shapes.RECTANGLE, {
