      x: x + 0.13, y: y + 0.1, w: 0.58, h: 0.38,
      fill: { color: m.color }, line: { color: m.color }
    });
    s.addText(m.n, {
      x: x + 0.13, y: y + 0.1, w: 0.58, h: 0.38,
      fontSize: 11, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(m.name, {
      x: x + 0.78, y: y + 0.1, w: 3.55, h: 0.4,
      fontSize: 11, bold: true, color: C.navy, margin: 0
    });
    s.addText(m.desc, {
      x: x + 0.15, y: y + 0.58, w: 4.18, h: 0.72,
      fontSize: 10, color: C.darkgray, margin: 0
    });
  });
}

// ─────────────────────────────────────────────
// SLIDE 15 – KPI & Quality Impact
// ─────────────────────────────────────────────
{
  const s = addContentSlide("Indikator Keberhasilan & Dampak Kualitas", "SOAL 05");

  // KPI section
  s.addText("📊  Indikator Keberhasilan (KPI)", {
