  });

  const impacts = [
    "🔒  Meningkatkan keandalan (reliability) dan integritas data sistem.",
    "🐛  Bug ditemukan lebih awal (shift-left testing) sehingga biaya perbaikan jauh lebih rendah.",
    "🤝  Meningkatkan kepercayaan pengguna dan memastikan sistem memenuhi standar kualitas.",
    "🔧  Sistem lebih mudah di-maintain karena masalah terdeteksi sebelum go-live.",
  ];

  impacts.forEach((imp, i) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.3, y: 4.1 + i * 0.34, w: 9.4, h: 0.3,
