// ============================================================
//  IoT Dashboard - server.js
//  Smart Greenhouse Simulator
//  Node.js + Express + Socket.io
// ============================================================

const express  = require('express');
const http     = require('http');
const socketIo = require('socket.io');
const path     = require('path');

const app    = express();
const server = http.createServer(app);
const io     = socketIo(server);

// Serve static files from /public
app.use(express.static(path.join(__dirname, 'public')));

// ── State perangkat (untuk tombol kontrol) ──────────────────
let lampuStatus = false;   // ON/OFF lampu
let pumpStatus  = false;   // ON/OFF pompa air

// ── Simulasi nilai sensor dengan variasi realistis ──────────
let suhu        = 27.0;
let kelembaban  = 65.0;
let cahaya      = 500;

function simulateSensor() {
  // Drift kecil agar data terasa nyata
  suhu       += (Math.random() - 0.48) * 0.8;
  kelembaban += (Math.random() - 0.50) * 1.2;
  cahaya     += (Math.random() - 0.50) * 30;

  // Clamp ke rentang wajar
  suhu       = Math.min(45, Math.max(18, suhu));
  kelembaban = Math.min(100, Math.max(30, kelembaban));
  cahaya     = Math.min(1200, Math.max(50, cahaya));

  return {
    timestamp  : new Date().toISOString(),
    suhu       : parseFloat(suhu.toFixed(1)),
    kelembaban : parseFloat(kelembaban.toFixed(1)),
    cahaya     : Math.round(cahaya),
    lampu      : lampuStatus,
    pompa      : pumpStatus
  };
}

// ── Kirim data setiap 2 detik ───────────────────────────────
setInterval(() => {
  const data = simulateSensor();
  io.emit('sensor-update', data);
  console.log(`[${new Date().toLocaleTimeString()}] Suhu:${data.suhu}°C  Lembab:${data.kelembaban}%  Cahaya:${data.cahaya}lx  Lampu:${data.lampu ? 'ON':'OFF'}  Pompa:${data.pompa ? 'ON':'OFF'}`);
}, 2000);

// ── Terima perintah kontrol dari dashboard ──────────────────
io.on('connection', (socket) => {
  console.log(`[+] Client terhubung: ${socket.id}`);

  // Kirim status saat ini ke client baru
  socket.emit('sensor-update', simulateSensor());

  // Toggle lampu
  socket.on('toggle-lampu', () => {
    lampuStatus = !lampuStatus;
    io.emit('device-status', { lampu: lampuStatus, pompa: pumpStatus });
    console.log(`[CMD] Lampu → ${lampuStatus ? 'ON' : 'OFF'}`);
  });

  // Toggle pompa
  socket.on('toggle-pompa', () => {
    pumpStatus = !pumpStatus;
    io.emit('device-status', { lampu: lampuStatus, pompa: pumpStatus });
    console.log(`[CMD] Pompa → ${pumpStatus ? 'ON' : 'OFF'}`);
  });

  socket.on('disconnect', () => {
    console.log(`[-] Client terputus: ${socket.id}`);
  });
});

// ── Start server ────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log('');
  console.log('╔══════════════════════════════════════╗');
  console.log('║   IoT Dashboard - Smart Greenhouse   ║');
  console.log(`║   http://localhost:${PORT}              ║`);
  console.log('╚══════════════════════════════════════╝');
  console.log('');
});

