/* ============================================================
   IoT Dashboard — style.css
   Dark industrial theme
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=DM+Sans:wght@300;400;500;700&display=swap');

:root {
  --bg:       #0d0f14;
  --surface:  #161922;
  --surface2: #1e2330;
  --border:   #2a2f3e;
  --accent1:  #00e5ff;   /* cyan  */
  --accent2:  #7c4dff;   /* purple */
  --green:    #00e676;
  --yellow:   #ffea00;
  --red:      #ff5252;
  --orange:   #ff6d00;
  --text:     #e8eaf0;
  --muted:    #7a8299;
  --radius:   12px;
  --bar-color: #00e676;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'DM Sans', sans-serif;
  min-height: 100vh;
}

/* ── Header ─────────────────────────────────────────────── */
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-icon {
  font-size: 26px;
  line-height: 1;
}

header h1 {
  font-family: 'Space Mono', monospace;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.3px;
}

.header-sub {
  font-size: 11px;
  color: var(--muted);
  margin-top: 1px;
}

.status-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-family: 'Space Mono', monospace;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 5px 12px;
  color: var(--muted);
  transition: all 0.3s;
}

.status-pill.connected {
  border-color: var(--green);
  color: var(--green);
}

.dot-pulse {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: var(--muted);
  animation: pulse 1.5s infinite;
  flex-shrink: 0;
}

.status-pill.connected .dot-pulse {
  background: var(--green);
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.7); }
}

/* ── Main layout ─────────────────────────────────────────── */
main {
  padding: 16px;
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Metric Cards ────────────────────────────────────────── */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.metric-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  position: relative;
  transition: border-color 0.3s;
}

.metric-card.alert {
  border-color: var(--red);
  box-shadow: 0 0 12px rgba(255,82,82,0.2);
}

.card-label {
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}

.card-value {
  font-family: 'Space Mono', monospace;
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  transition: color 0.3s;
}

.card-unit {
  font-size: 12px;
  color: var(--muted);
  margin-top: 3px;
}

.card-bar-wrap {
  height: 4px;
  background: var(--border);
  border-radius: 2px;
  margin-top: 12px;
  overflow: hidden;
}

.card-bar {
  height: 100%;
  width: 0%;
  border-radius: 2px;
  background: var(--bar-color);
  transition: width 0.6s ease;
}

.card-alert {
  font-size: 10px;
  color: var(--red);
  margin-top: 6px;
  min-height: 14px;
  font-weight: 600;
}

/* ── Charts ──────────────────────────────────────────────── */
.charts-section {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 12px;
}

.chart-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
}

.chart-title {
  font-family: 'Space Mono', monospace;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.5px;
  margin-bottom: 14px;
  text-transform: uppercase;
}

/* ── Gauge + Controls section ────────────────────────────── */
.gauge-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.gauge-card {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.gauge-card canvas {
  max-width: 200px;
  max-height: 110px;
}

.gauge-label {
  font-family: 'Space Mono', monospace;
  font-size: 24px;
  font-weight: 700;
  color: var(--accent1);
  margin-top: 8px;
}

/* ── Kontrol Aktuator ────────────────────────────────────── */
.control-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.control-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 14px;
}

.control-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.control-icon { font-size: 20px; }

.control-name {
  font-size: 13px;
  font-weight: 600;
}

.control-sub {
  font-size: 10px;
  color: var(--muted);
  font-family: 'Space Mono', monospace;
  margin-top: 2px;
}

.toggle-btn {
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--muted);
  font-family: 'Space Mono', monospace;
  font-size: 11px;
  font-weight: 700;
  padding: 8px 16px;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
  min-width: 56px;
}

.toggle-btn:hover {
  border-color: var(--accent1);
  color: var(--accent1);
}

.toggle-btn.on {
  background: rgba(0,230,118,0.15);
  border-color: var(--green);
  color: var(--green);
}

/* ── Log Box ─────────────────────────────────────────────── */
.log-box {
  background: #0a0c10;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
  flex: 1;
  overflow: hidden;
}

.log-title {
  font-family: 'Space Mono', monospace;
  font-size: 10px;
  color: var(--muted);
  letter-spacing: 1px;
  margin-bottom: 8px;
  text-transform: uppercase;
}

#logList {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 110px;
  overflow-y: auto;
}

.log-entry {
  font-family: 'Space Mono', monospace;
  font-size: 10px;
  color: var(--muted);
  padding: 2px 0;
  border-bottom: 1px solid var(--border);
  display: flex;
  gap: 6px;
}

.log-entry .log-time { color: var(--accent2); flex-shrink: 0; }
.log-entry .log-msg.on  { color: var(--green); }
.log-entry .log-msg.off { color: var(--red); }
.log-entry .log-msg.alert { color: var(--orange); }

/* ── Footer ──────────────────────────────────────────────── */
footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  font-size: 10px;
  font-family: 'Space Mono', monospace;
  color: var(--muted);
  border-top: 1px solid var(--border);
  background: var(--surface);
  margin-top: 8px;
}

/* ── Responsive ──────────────────────────────────────────── */
@media (max-width: 768px) {
  .cards-grid    { grid-template-columns: 1fr 1fr; }
  .charts-section{ grid-template-columns: 1fr; }
  .gauge-section { grid-template-columns: 1fr; }
  .card-value    { font-size: 26px; }
}

@media (max-width: 480px) {
  .cards-grid { grid-template-columns: 1fr; }
  header h1   { font-size: 13px; }
}

