// ============================================================
//  IoT Dashboard — script.js
//  Socket.io client + Chart.js realtime
// ============================================================

const socket = io();

// ── Connection status ──────────────────────────────────────
const connEl = document.getElementById('connStatus');

socket.on('connect', () => {
  connEl.textContent = '';
  const dot = document.createElement('span');
  dot.className = 'dot-pulse';
  connEl.appendChild(dot);
  connEl.append(' Connected');
  connEl.classList.add('connected');
  addLog('sistem', 'Dashboard terhubung ke server', 'on');
});

socket.on('disconnect', () => {
  connEl.className = 'status-pill';
  connEl.textContent = '⚠ Disconnected';
  addLog('sistem', 'Koneksi terputus!', 'off');
});

// ── Chart.js defaults ─────────────────────────────────────
Chart.defaults.color = '#7a8299';
Chart.defaults.borderColor = '#2a2f3e';
Chart.defaults.font.family = "'DM Sans', sans-serif";

// ── 1. Line Chart — Suhu real-time ────────────────────────
const suhuCtx = document.getElementById('suhuChart').getContext('2d');
const suhuChart = new Chart(suhuCtx, {
  type: 'line',
  data: {
    labels: [],
    datasets: [{
      label: 'Suhu (°C)',
      data: [],
      borderColor: '#00e676',
      backgroundColor: 'rgba(0,230,118,0.08)',
      borderWidth: 2,
      pointRadius: 2,
      pointHoverRadius: 5,
      tension: 0.4,
      fill: true
    }]
  },
  options: {
    responsive: true,
    animation: false,
    plugins: {
      legend: { display: false }
    },
    scales: {
      x: {
        title: { display: true, text: 'Waktu', color: '#7a8299' },
        ticks: { maxTicksLimit: 6, maxRotation: 0 }
      },
      y: {
        title: { display: true, text: '°C', color: '#7a8299' },
        min: 15,
        max: 50,
        ticks: {
          callback: v => v + '°'
        }
      }
    }
  }
});

// ── 2. Bar Chart — perbandingan sensor terkini ─────────────
const barCtx = document.getElementById('barChart').getContext('2d');
const barChart = new Chart(barCtx, {
  type: 'bar',
  data: {
    labels: ['Suhu\n(°C)', 'Lembab\n(%)', 'Cahaya\n(/10)'],
    datasets: [{
      label: 'Nilai Sensor',
      data: [0, 0, 0],
      backgroundColor: [
        'rgba(0,230,118,0.5)',
        'rgba(0,229,255,0.5)',
        'rgba(255,234,0,0.5)'
      ],
      borderColor: [
        '#00e676',
        '#00e5ff',
        '#ffea00'
      ],
      borderWidth: 1,
      borderRadius: 4
    }]
  },
  options: {
    responsive: true,
    animation: { duration: 500 },
    plugins: {
      legend: { display: false }
    },
    scales: {
      y: { min: 0, max: 130 }
    }
  }
});

// ── 3. Gauge (Doughnut) — Kelembaban tanah ─────────────────
const gaugeCtx = document.getElementById('gaugeChart').getContext('2d');
const gaugeChart = new Chart(gaugeCtx, {
  type: 'doughnut',
  data: {
    datasets: [{
      data: [65, 35],
      backgroundColor: ['#00e5ff', '#1e2330'],
      borderWidth: 0,
      circumference: 180,
      rotation: 270
    }]
  },
  options: {
    responsive: true,
    cutout: '72%',
    plugins: {
      legend: { display: false },
      tooltip: { enabled: false }
    }
  }
});

// ── Terima data sensor ─────────────────────────────────────
const MAX_POINTS = 20;

socket.on('sensor-update', (data) => {
  const timeStr = new Date(data.timestamp).toLocaleTimeString('id-ID', {
    hour: '2-digit', minute: '2-digit', second: '2-digit'
  });

  // Update metric cards
  updateCard('valSuhu',   data.suhu,       'barSuhu',   data.suhu,   18, 45,  'card-suhu');
  updateCard('valLembab', data.kelembaban, 'barLembab', data.kelembaban, 30, 100, 'card-lembab');
  updateCard('valCahaya', data.cahaya,     'barCahaya', data.cahaya, 50, 1200, 'card-cahaya');

  // Threshold alerts
  checkAlert('alertSuhu',   data.suhu > 35,       '⚠ Suhu terlalu tinggi!', 'card-suhu');
  checkAlert('alertLembab', data.kelembaban < 40,  '⚠ Kelembaban rendah!',  'card-lembab');
  checkAlert('alertCahaya', data.cahaya > 1000,    '⚠ Cahaya terlalu terang!', 'card-cahaya');

  // Line chart — max 20 poin
  suhuChart.data.labels.push(timeStr);
  suhuChart.data.datasets[0].data.push(data.suhu);
  if (suhuChart.data.labels.length > MAX_POINTS) {
    suhuChart.data.labels.shift();
    suhuChart.data.datasets[0].data.shift();
  }
  suhuChart.update();

  // Bar chart — nilai saat ini (cahaya dibagi 10 agar sekala sama)
  barChart.data.datasets[0].data = [
    data.suhu,
    data.kelembaban,
    parseFloat((data.cahaya / 10).toFixed(1))
  ];
  barChart.update();

  // Gauge kelembaban
  const pct = Math.min(100, Math.max(0, data.kelembaban));
  gaugeChart.data.datasets[0].data = [pct, 100 - pct];
  gaugeChart.update();
  document.getElementById('gaugeLabel').textContent = pct.toFixed(1) + ' %';

  // Status tombol
  updateButton('btnLampu', 'subLampu', data.lampu, 'Lampu');
  updateButton('btnPompa', 'subPompa', data.pompa, 'Pompa');

  // Footer timestamp
  document.getElementById('lastUpdate').textContent = 'Update: ' + timeStr;

  // Alert log
  if (data.suhu > 35) addLog(timeStr, `⚠ Suhu ${data.suhu}°C melebihi threshold!`, 'alert');
});

// ── Terima status device ───────────────────────────────────
socket.on('device-status', (status) => {
  updateButton('btnLampu', 'subLampu', status.lampu, 'Lampu');
  updateButton('btnPompa', 'subPompa', status.pompa, 'Pompa');
});

// ── Helper: update metric card ─────────────────────────────
function updateCard(valId, value, barId, rawVal, min, max, cardId) {
  document.getElementById(valId).textContent = value;
  const pct = ((rawVal - min) / (max - min)) * 100;
  document.getElementById(barId).style.width = Math.min(100, Math.max(0, pct)) + '%';
}

// ── Helper: threshold alert ────────────────────────────────
function checkAlert(alertId, condition, message, cardId) {
  const alertEl = document.getElementById(alertId);
  const cardEl  = document.getElementById(cardId);
  if (condition) {
    alertEl.textContent = message;
    cardEl.classList.add('alert');
  } else {
    alertEl.textContent = '';
    cardEl.classList.remove('alert');
  }
}

// ── Helper: toggle button state ───────────────────────────
function updateButton(btnId, subId, isOn, name) {
  const btn = document.getElementById(btnId);
  const sub = document.getElementById(subId);
  if (isOn) {
    btn.textContent = 'ON';
    btn.classList.add('on');
  } else {
    btn.textContent = 'OFF';
    btn.classList.remove('on');
  }
  sub.textContent = `Status: ${isOn ? 'ON ✅' : 'OFF'}`;
}

// ── Toggle aktuator ────────────────────────────────────────
function toggleDevice(device) {
  const timeStr = new Date().toLocaleTimeString('id-ID');
  if (device === 'lampu') {
    socket.emit('toggle-lampu');
    addLog(timeStr, 'Perintah toggle Lampu dikirim', 'on');
  } else {
    socket.emit('toggle-pompa');
    addLog(timeStr, 'Perintah toggle Pompa dikirim', 'on');
  }
}

// ── Event log ─────────────────────────────────────────────
const MAX_LOG = 8;

function addLog(time, msg, type) {
  const logList = document.getElementById('logList');
  const entry = document.createElement('div');
  entry.className = 'log-entry';
  entry.innerHTML = `<span class="log-time">[${time}]</span><span class="log-msg ${type}">${msg}</span>`;
  logList.prepend(entry);

  // Limit entries
  while (logList.children.length > MAX_LOG) {
    logList.removeChild(logList.lastChild);
  }
}

