/*
 * ============================================================
 *  Smart Greenhouse — ESP32 (Wokwi Simulator)
 *  Sensor  : DHT22 (suhu & kelembaban) + LDR (cahaya)
 *  Aktuator: Relay Lampu (LED simulasi)
 *  Protokol: MQTT over TCP → broker.emqx.io:1883
 *  Cloud   : ThingsBoard (telemetry via MQTT)
 * ============================================================
 *
 *  TOPIK MQTT:
 *    PUBLISH  greenhouse/sensor     → data sensor JSON
 *    SUBSCRIBE greenhouse/lampu/cmd → perintah ON/OFF lampu
 *    PUBLISH  v1/devices/me/telemetry → ThingsBoard telemetry
 *
 * ============================================================
 */

#include <WiFi.h>
#include <PubSubClient.h>
#include <DHTesp.h>
#include <ArduinoJson.h>

// ── WiFi (Wokwi pakai Wokwi-GUEST) ────────────────────────
const char* WIFI_SSID = "Wokwi-GUEST";
const char* WIFI_PASS = "";

// ── Public MQTT Broker (gratis, no auth) ──────────────────
const char* MQTT_HOST   = "broker.emqx.io";
const int   MQTT_PORT   = 1883;
const char* MQTT_CLIENT = "esp32-greenhouse-001";  // unik per device

// ── ThingsBoard Cloud ──────────────────────────────────────
// Ganti TOKEN dengan Access Token device di ThingsBoard Cloud
const char* TB_HOST   = "mqtt.thingsboard.cloud";
const int   TB_PORT   = 1883;
const char* TB_TOKEN  = "YOUR_THINGSBOARD_ACCESS_TOKEN";  // ← GANTI INI
const char* TB_CLIENT = "esp32-tb-greenhouse-001";

// ── Topic ──────────────────────────────────────────────────
const char* TOPIC_SENSOR   = "greenhouse/sensor";
const char* TOPIC_LAMP_CMD = "greenhouse/lampu/cmd";
const char* TOPIC_TB_TELE  = "v1/devices/me/telemetry";

// ── Pin ────────────────────────────────────────────────────
#define DHT_PIN     15
#define LDR_PIN     34   // ADC input
#define LAMP_PIN    26   // LED/Relay simulasi lampu
#define PUMP_PIN    27   // LED/Relay simulasi pompa

// ── Interval kirim data ────────────────────────────────────
const unsigned long SEND_INTERVAL = 2000;  // 2 detik
unsigned long lastSend = 0;

// ── Objects ────────────────────────────────────────────────
DHTesp    dht;
WiFiClient   wifiClient1;
WiFiClient   wifiClient2;
PubSubClient mqttPublic(wifiClient1);   // broker.emqx.io
PubSubClient mqttTB(wifiClient2);       // ThingsBoard

bool lampState = false;
bool pumpState = false;

// ── Callback: terima perintah dari dashboard ───────────────
void onMqttMessage(char* topic, byte* payload, unsigned int length) {
  String msg = "";
  for (int i = 0; i < length; i++) msg += (char)payload[i];
  msg.trim();

  Serial.printf("[MQTT] Topic: %s  Msg: %s\n", topic, msg.c_str());

  String t = String(topic);

  if (t == "greenhouse/lampu/cmd") {
    lampState = (msg == "ON" || msg == "1" || msg == "true");
    digitalWrite(LAMP_PIN, lampState ? HIGH : LOW);
    Serial.printf("[ACT] Lampu → %s\n", lampState ? "ON" : "OFF");
  }

  if (t == "greenhouse/pompa/cmd") {
    pumpState = (msg == "ON" || msg == "1" || msg == "true");
    digitalWrite(PUMP_PIN, pumpState ? HIGH : LOW);
    Serial.printf("[ACT] Pompa → %s\n", pumpState ? "ON" : "OFF");
  }
}

// ── WiFi Connect ───────────────────────────────────────────
void connectWiFi() {
  Serial.print("[WiFi] Connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\n[WiFi] Connected! IP: " + WiFi.localIP().toString());
}

// ── Connect ke public broker ───────────────────────────────
void connectMQTT() {
  mqttPublic.setServer(MQTT_HOST, MQTT_PORT);
  mqttPublic.setCallback(onMqttMessage);

  while (!mqttPublic.connected()) {
    Serial.print("[MQTT] Connecting to broker.emqx.io...");
    if (mqttPublic.connect(MQTT_CLIENT)) {
      Serial.println(" OK");
      mqttPublic.subscribe("greenhouse/lampu/cmd");
      mqttPublic.subscribe("greenhouse/pompa/cmd");
      Serial.println("[MQTT] Subscribed: greenhouse/lampu/cmd");
      Serial.println("[MQTT] Subscribed: greenhouse/pompa/cmd");
    } else {
      Serial.printf(" FAIL rc=%d — retry 3s\n", mqttPublic.state());
      delay(3000);
    }
  }
}

// ── Connect ke ThingsBoard ─────────────────────────────────
void connectTB() {
  mqttTB.setServer(TB_HOST, TB_PORT);

  while (!mqttTB.connected()) {
    Serial.print("[TB] Connecting to ThingsBoard...");
    // Username = Access Token, Password = ""
    if (mqttTB.connect(TB_CLIENT, TB_TOKEN, "")) {
      Serial.println(" OK");
    } else {
      Serial.printf(" FAIL rc=%d — retry 3s\n", mqttTB.state());
      delay(3000);
    }
  }
}

// ── Baca LDR → lux (approx) ───────────────────────────────
float readLux() {
  int raw = analogRead(LDR_PIN);  // 0–4095
  // Konversi sederhana: raw → lux (estimasi)
  float voltage = raw * (3.3f / 4095.0f);
  float resistance = (3.3f - voltage) / voltage * 10000.0f;  // 10k pull-down
  float lux = 500.0f / (resistance / 1000.0f);               // approx
  return constrain(lux, 0, 1500);
}

// ── Setup ──────────────────────────────────────────────────
void setup() {
  Serial.begin(115200);
  delay(500);

  // Pin setup
  dht.setup(DHT_PIN, DHTesp::DHT22);
  pinMode(LAMP_PIN, OUTPUT);
  pinMode(PUMP_PIN, OUTPUT);
  digitalWrite(LAMP_PIN, LOW);
  digitalWrite(PUMP_PIN, LOW);

  // Connect
  connectWiFi();
  connectMQTT();
  connectTB();

  Serial.println("\n[READY] Smart Greenhouse aktif!");
  Serial.println("[INFO] Data dikirim setiap 2 detik");
}

// ── Loop ───────────────────────────────────────────────────
void loop() {
  // Jaga koneksi MQTT
  if (!mqttPublic.connected()) connectMQTT();
  if (!mqttTB.connected())     connectTB();

  mqttPublic.loop();
  mqttTB.loop();

  // Kirim data setiap SEND_INTERVAL
  unsigned long now = millis();
  if (now - lastSend >= SEND_INTERVAL) {
    lastSend = now;

    // Baca sensor
    TempAndHumidity th = dht.getTempAndHumidity();
    float suhu      = isnan(th.temperature) ? 25.0f : th.temperature;
    float kelembaban = isnan(th.humidity)   ? 60.0f : th.humidity;
    float cahaya    = readLux();

    // ── Publish ke broker.emqx.io ─────────────────────────
    StaticJsonDocument<256> doc;
    doc["suhu"]       = round(suhu * 10) / 10.0;
    doc["kelembaban"] = round(kelembaban * 10) / 10.0;
    doc["cahaya"]     = (int)cahaya;
    doc["lampu"]      = lampState;
    doc["pompa"]      = pumpState;
    doc["device"]     = "esp32-greenhouse";

    char buf[256];
    serializeJson(doc, buf);
    mqttPublic.publish(TOPIC_SENSOR, buf);
    Serial.printf("[PUB] %s → %s\n", TOPIC_SENSOR, buf);

    // ── Publish ke ThingsBoard telemetry ──────────────────
    StaticJsonDocument<200> tbDoc;
    tbDoc["temperature"] = doc["suhu"];
    tbDoc["humidity"]    = doc["kelembaban"];
    tbDoc["light"]       = doc["cahaya"];
    tbDoc["lamp"]        = lampState ? 1 : 0;
    tbDoc["pump"]        = pumpState ? 1 : 0;

    char tbBuf[200];
    serializeJson(tbDoc, tbBuf);
    mqttTB.publish(TOPIC_TB_TELE, tbBuf);
    Serial.printf("[TB]  telemetry → %s\n", tbBuf);
  }
}

