// ============================================================
//  IoT Dashboard — server.js  (v2 — MQTT + ThingsBoard)
//  Alur: Wokwi ESP32 → broker.emqx.io → server.js
//                                      → Socket.io → Browser
//                     (ESP32 juga kirim langsung ke ThingsBoard)
// ============================================================

const express  = require('express');
const http     = require('http');
const socketIo = require('socket.io');
const mqtt     = require('mqtt');
const path     = require('path');

const app    = express();
const server = http.createServer(app);
const io     = socketIo(server);

app.use(express.static(path.join(__dirname, 'public')));

// ── Konfigurasi MQTT Broker (emqx publik, gratis) ──────────
const MQTT_BROKER = 'mqtt://broker.emqx.io:1883';
const TOPIC_SUB   = 'greenhouse/sensor';     // data dari ESP32
const TOPIC_LAMP  = 'greenhouse/lampu/cmd';  // perintah ke ESP32
const TOPIC_PUMP  = 'greenhouse/pompa/cmd';  // perintah ke ESP32

// ── Koneksi ke MQTT Broker ─────────────────────────────────
const mqttClient = mqtt.connect(MQTT_BROKER, {
  clientId: `dashboard-server-${Math.random().toString(16).slice(2, 8)}`,
  clean: true,
  reconnectPeriod: 3000
});

mqttClient.on('connect', () => {
  console.log('[MQTT] Terhubung ke broker.emqx.io');
  mqttClient.subscribe(TOPIC_SUB, (err) => {
    if (err) console.error('[MQTT] Subscribe gagal:', err);
    else     console.log(`[MQTT] Subscribe: ${TOPIC_SUB}`);
  });
});

mqttClient.on('error', (err) => {
  console.error('[MQTT] Error:', err.message);
});

mqttClient.on('reconnect', () => {
  console.log('[MQTT] Mencoba reconnect...');
});

// ── Terima data dari ESP32, teruskan ke browser ────────────
mqttClient.on('message', (topic, message) => {
  try {
    const data = JSON.parse(message.toString());
    data.timestamp = data.timestamp || new Date().toISOString();

    console.log(`[DATA] Suhu:${data.suhu}°C  Lembab:${data.kelembaban}%  Cahaya:${data.cahaya}lx  Lampu:${data.lampu ? 'ON':'OFF'}`);

    // Broadcast ke semua client browser via Socket.io
    io.emit('sensor-update', data);

  } catch (e) {
    console.warn('[MQTT] Pesan tidak valid JSON:', message.toString());
  }
});

// ── Fallback: simulasi data jika ESP32 belum terhubung ─────
let simMode = true;
let simSuhu = 27, simLembab = 65, simCahaya = 500;
let lampState = false, pumpState = false;

// Cek apakah sudah ada data real masuk dalam 5 detik
let lastRealData = 0;
mqttClient.on('message', () => { lastRealData = Date.now(); });

setInterval(() => {
  const noRealData = (Date.now() - lastRealData) > 5000;

  if (noRealData) {
    // Mode simulasi (ESP32 belum connect)
    simSuhu    += (Math.random() - 0.48) * 0.8;
    simLembab  += (Math.random() - 0.50) * 1.2;
    simCahaya  += (Math.random() - 0.50) * 30;
    simSuhu    = Math.min(45, Math.max(18, simSuhu));
    simLembab  = Math.min(100, Math.max(30, simLembab));
    simCahaya  = Math.min(1200, Math.max(50, simCahaya));

    const data = {
      timestamp  : new Date().toISOString(),
      suhu       : parseFloat(simSuhu.toFixed(1)),
      kelembaban : parseFloat(simLembab.toFixed(1)),
      cahaya     : Math.round(simCahaya),
      lampu      : lampState,
      pompa      : pumpState,
      simulated  : true    // flag bagi frontend
    };
    io.emit('sensor-update', data);
  }
}, 2000);

// ── Socket.io — terima perintah dari browser ───────────────
io.on('connection', (socket) => {
  console.log(`[WS] Client terhubung: ${socket.id}`);

  // Kirim status MQTT ke client baru
  socket.emit('mqtt-status', {
    connected: mqttClient.connected,
    broker: 'broker.emqx.io'
  });

  // Toggle lampu — publish ke MQTT → diterima ESP32
  socket.on('toggle-lampu', () => {
    lampState = !lampState;
    const cmd = lampState ? 'ON' : 'OFF';
    mqttClient.publish(TOPIC_LAMP, cmd, { retain: true });
    io.emit('device-status', { lampu: lampState, pompa: pumpState });
    console.log(`[CMD] Publish ${TOPIC_LAMP} → ${cmd}`);
  });

  // Toggle pompa
  socket.on('toggle-pompa', () => {
    pumpState = !pumpState;
    const cmd = pumpState ? 'ON' : 'OFF';
    mqttClient.publish(TOPIC_PUMP, cmd, { retain: true });
    io.emit('device-status', { lampu: lampState, pompa: pumpState });
    console.log(`[CMD] Publish ${TOPIC_PUMP} → ${cmd}`);
  });

  socket.on('disconnect', () => {
    console.log(`[WS] Client terputus: ${socket.id}`);
  });
});

// ── REST API — cek status server ───────────────────────────
app.get('/api/status', (req, res) => {
  res.json({
    server  : 'running',
    mqtt    : mqttClient.connected ? 'connected' : 'disconnected',
    broker  : MQTT_BROKER,
    topic   : TOPIC_SUB,
    clients : io.engine.clientsCount
  });
});

// ── Start ──────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log('');
  console.log('╔══════════════════════════════════════════╗');
  console.log('║   IoT Dashboard v2 — MQTT + ThingsBoard  ║');
  console.log(`║   http://localhost:${PORT}                ║`);
  console.log('║   broker.emqx.io  topic: greenhouse/#    ║');
  console.log('╚══════════════════════════════════════════╝');
  console.log('');
  console.log('[INFO] Menunggu data dari Wokwi ESP32...');
  console.log('[INFO] Mode simulasi aktif sampai ESP32 connect\n');
});

