let lampState = false, pumpState = false;

// Cek apakah sudah ada data real masuk dalam 5 detik
let lastRealData = 0;
mqttClient.on('message', () => { lastRealData = Date.now(); });

setInterval(() => {
  const noRealData = (Date.now() - lastRealData) > 5000;

  if (noRealData) {
    // Mode simulasi (ESP32 belum connect)
    simSuhu    += (Math.random() - 0.48) * 0.8;
    simLembab  += (Math.random() - 0.50) * 1.2;
    simCahaya  += (Math.random() - 0.50) * 30;
    simSuhu    = Math.min(45, Math.max(18, simSuhu));
    simLembab  = Math.min(100, Math.max(30, simLembab));
    simCahaya  = Math.min(1200, Math.max(50, simCahaya));

    const data = {
      timestamp  : new Date().toISOString(),
      suhu       : parseFloat(simSuhu.toFixed(1)),
      kelembaban : parseFloat(simLembab.toFixed(1)),
      cahaya     : Math.round(simCahaya),
      lampu      : lampState,
      pompa      : pumpState,
      simulated  : true    // flag bagi frontend
    };
    io.emit('sensor-update', data);
  }
}, 2000);

// ── Socket.io — terima perintah dari browser ───────────────
io.on('connection', (socket) => {
  console.log(`[WS] Client terhubung: ${socket.id}`);

  // Kirim status MQTT ke client baru
  socket.emit('mqtt-status', {
    connected: mqttClient.connected,
    broker: 'broker.emqx.io'
  });

  // Toggle lampu — publish ke MQTT → diterima ESP32
  socket.on('toggle-lampu', () => {
    lampState = !lampState;
    const cmd = lampState ? 'ON' : 'OFF';
    mqttClient.publish(TOPIC_LAMP, cmd, { retain: true });
    io.emit('device-status', { lampu: lampState, pompa: pumpState });
    console.log(`[CMD] Publish ${TOPIC_LAMP} → ${cmd}`);
  });

  // Toggle pompa
  socket.on('toggle-pompa', () => {
    pumpState = !pumpState;
    const cmd = pumpState ? 'ON' : 'OFF';
    mqttClient.publish(TOPIC_PUMP, cmd, { retain: true });
    io.emit('device-status', { lampu: lampState, pompa: pumpState });
    console.log(`[CMD] Publish ${TOPIC_PUMP} → ${cmd}`);
  });

  socket.on('disconnect', () => {
    console.log(`[WS] Client terputus: ${socket.id}`);
  });
});

// ── REST API — cek status server ───────────────────────────
app.get('/api/status', (req, res) => {
  res.json({
    server  : 'running',
    mqtt    : mqttClient.connected ? 'connected' : 'disconnected',
    broker  : MQTT_BROKER,
    topic   : TOPIC_SUB,
    clients : io.engine.clientsCount
  });
});

// ── Start ──────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log('');
  console.log('╔══════════════════════════════════════════╗');
  console.log('║   IoT Dashboard v2 — MQTT + ThingsBoard  ║');
  console.log(`║   http://localhost:${PORT}                ║`);
  console.log('║   broker.emqx.io  topic: greenhouse/#    ║');
  console.log('╚══════════════════════════════════════════╝');
  console.log('');
  console.log('[INFO] Menunggu data dari Wokwi ESP32...');
  console.log('[INFO] Mode simulasi aktif sampai ESP32 connect\n');
});

