const mqttClient = mqtt.connect(MQTT_BROKER, {
  clientId: `dashboard-server-${Math.random().toString(16).slice(2, 8)}`,
  clean: true,
  reconnectPeriod: 3000
});

mqttClient.on('connect', () => {
  console.log('[MQTT] Terhubung ke broker.emqx.io');
  mqttClient.subscribe(TOPIC_SUB, (err) => {
    if (err) console.error('[MQTT] Subscribe gagal:', err);
    else     console.log(`[MQTT] Subscribe: ${TOPIC_SUB}`);
  });
});

mqttClient.on('error', (err) => {
  console.error('[MQTT] Error:', err.message);
});

mqttClient.on('reconnect', () => {
  console.log('[MQTT] Mencoba reconnect...');
});

// ── Terima data dari ESP32, teruskan ke browser ────────────
let lastRealData = 0;

mqttClient.on('message', (topic, message) => {
  try {
    const data = JSON.parse(message.toString());
    data.timestamp = data.timestamp || new Date().toISOString();
