//  IoT Dashboard — server.js  (v2 — MQTT + ThingsBoard)
//  Alur: Wokwi ESP32 → broker.emqx.io → server.js
//                                      → Socket.io → Browser
//                     (ESP32 juga kirim langsung ke ThingsBoard)
// ============================================================

const express  = require('express');
const http     = require('http');
const socketIo = require('socket.io');
const mqtt     = require('mqtt');
const path     = require('path');

const app    = express();
const server = http.createServer(app);
const io     = socketIo(server);

app.use(express.static(path.join(__dirname, 'public')));

// ── Konfigurasi MQTT Broker (emqx publik, gratis) ──────────
const MQTT_BROKER = 'mqtt://broker.emqx.io:1883';
const TOPIC_SUB   = 'greenhouse/sensor';     // data dari ESP32
const TOPIC_LAMP  = 'greenhouse/lampu/cmd';  // perintah ke ESP32
const TOPIC_PUMP  = 'greenhouse/pompa/cmd';  // perintah ke ESP32

", "filename": "/home/claude/iot-dashboard/server.js"}

