const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const {
  FaCompass, FaUsers, FaBook, FaClipboardList,
  FaQuestionCircle, FaChartBar, FaComments, FaRobot,
  FaShieldAlt, FaLock, FaMobileAlt, FaGlobe,
  FaCheckCircle, FaExclamationTriangle, FaGraduationCap,
  FaChalkboardTeacher, FaUserShield, FaStar
} = require("react-icons/fa");

// ─── BRAND COLORS ────────────────────────────────────────────────
const C = {
  dark:   "3D2B1F",  // tanah tua
  mid:    "5C3D2E",  // kayu jati
  gold:   "C4956A",  // emas tua
  cream:  "F5E6C8",  // kulit lontar
  forest: "2C5F2E",  // hutan rimba
  red:    "8B1A1A",  // merah saga
  white:  "FFFFFF",
  light:  "FDF6EC",  // off-white warm
  gray:   "9B8B7A",
  cardBg: "F7EFE2",
};

async function iconPng(IconComponent, color, size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color: `#${color}`, size: String(size) })
  );
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "Jejak Nusantara";
  pres.author = "Jejak Nusantara Team";

  // ─── SLIDE 1: COVER ──────────────────────────────────────────────
  {
    const sl = pres.addSlide();
    sl.background = { color: C.dark };

    // Left decorative block
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 0.08, h: 5.625,
      fill: { color: C.gold }, line: { color: C.gold }
    });

    // Compass icon
    const compassPng = await iconPng(FaCompass, C.gold, 512);
    sl.addImage({ data: compassPng, x: 7.2, y: 0.6, w: 2.4, h: 2.4 });

    // Tagline top
    sl.addText("PLATFORM BELAJAR SEJARAH INDONESIA", {
      x: 0.5, y: 0.5, w: 6.5, h: 0.4,
      fontSize: 10, color: C.gold, bold: true,
      charSpacing: 4, fontFace: "Calibri", margin: 0
    });

    // Main title
    sl.addText("Jejak", {
      x: 0.5, y: 1.0, w: 6.5, h: 1.0,
      fontSize: 64, color: C.cream, bold: true,
      fontFace: "Georgia", margin: 0
    });
    sl.addText("Nusantara", {
      x: 0.5, y: 1.85, w: 6.5, h: 1.0,
      fontSize: 64, color: C.gold, bold: true,
      fontFace: "Georgia", margin: 0
    });

    // Subtitle
    sl.addText("Learning Management System untuk Sejarah Indonesia\nSD · SMP · SMA", {
      x: 0.5, y: 3.0, w: 6.5, h: 0.9,
      fontSize: 15, color: C.cream, fontFace: "Calibri",
      lineSpacingMultiple: 1.4, margin: 0
    });

    // Bottom band
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 4.9, w: 10, h: 0.725,
      fill: { color: C.mid }, line: { color: C.mid }
    });
    sl.addText("Jelajahi · Pelajari · Ingat", {
      x: 0.5, y: 4.95, w: 9, h: 0.6,
      fontSize: 13, color: C.gold, fontFace: "Calibri",
      italic: true, align: "center", margin: 0
    });
  }

  // ─── SLIDE 2: AGENDA ─────────────────────────────────────────────
  {
    const sl = pres.addSlide();
    sl.background = { color: C.light };

    // Title area
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 1.1,
      fill: { color: C.dark }, line: { color: C.dark }
    });
    sl.addText("Agenda Presentasi", {
      x: 0.5, y: 0.15, w: 9, h: 0.8,
      fontSize: 28, color: C.cream, bold: true,
      fontFace: "Georgia", margin: 0
    });

    const items = [
      { num: "01", title: "Latar Belakang", desc: "Mengapa LMS sejarah dibutuhkan?" },
      { num: "02", title: "Tentang Jejak Nusantara", desc: "Visi, misi, dan identitas brand" },
      { num: "03", title: "Fitur Utama", desc: "9 fitur unggulan aplikasi" },
      { num: "04", title: "Sistem Multi-Role", desc: "Siswa, Guru, dan Admin" },
      { num: "05", title: "Keamanan & Anti-Cheat", desc: "Sistem pengamanan berlapis" },
      { num: "06", title: "Tech Stack", desc: "Teknologi yang digunakan" },
      { num: "07", title: "Roadmap", desc: "Timeline pengembangan 4 bulan" },
    ];

    items.forEach((item, i) => {
      const col = i < 4 ? 0 : 1;
      const row = i < 4 ? i : i - 4;
      const x = col === 0 ? 0.4 : 5.3;
      const y = 1.4 + row * 0.95;
      const w = 4.6;

      sl.addShape(pres.shapes.RECTANGLE, {
        x, y, w, h: 0.75,
        fill: { color: C.white },
        shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.07 },
        line: { color: "E8DFD0", width: 0.5 }
      });
      sl.addShape(pres.shapes.RECTANGLE, {
        x, y, w: 0.48, h: 0.75,
        fill: { color: C.dark }, line: { color: C.dark }
      });
      sl.addText(item.num, {
        x, y, w: 0.48, h: 0.75,
        fontSize: 13, color: C.gold, bold: true,
        fontFace: "Georgia", align: "center", valign: "middle", margin: 0
      });
      sl.addText(item.title, {
        x: x + 0.58, y: y + 0.06, w: w - 0.65, h: 0.3,
        fontSize: 13, color: C.dark, bold: true,
        fontFace: "Calibri", margin: 0
      });
      sl.addText(item.desc, {
        x: x + 0.58, y: y + 0.38, w: w - 0.65, h: 0.28,
        fontSize: 10, color: C.gray,
        fontFace: "Calibri", margin: 0
      });
    });
  }

  // ─── SLIDE 3: LATAR BELAKANG ─────────────────────────────────────
  {
    const sl = pres.addSlide();
    sl.background = { color: C.light };

    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 1.1,
      fill: { color: C.dark }, line: { color: C.dark }
    });
    sl.addText("Latar Belakang", {
      x: 0.5, y: 0.15, w: 9, h: 0.8,
      fontSize: 28, color: C.cream, bold: true,
      fontFace: "Georgia", margin: 0
    });

    const problems = [
      { icon: FaBook, color: C.red, title: "Materi Tersebar", desc: "Siswa harus mencari materi dari berbagai sumber yang tidak terstruktur" },
      { icon: FaClipboardList, color: C.gold, title: "Tugas Manual", desc: "Pengumpulan tugas masih via WhatsApp atau kertas, sulit dilacak guru" },
      { icon: FaQuestionCircle, color: C.forest, title: "Kuis Rawan Curang", desc: "Ujian online mudah dicurangi dengan buka tab atau aplikasi lain" },
      { icon: FaChartBar, color: C.mid, title: "Nilai Tidak Terpantau", desc: "Tidak ada dashboard terpusat untuk guru memantau perkembangan siswa" },
    ];

    for (let i = 0; i < problems.length; i++) {
      const p = problems[i];
      const col = i % 2;
      const row = Math.floor(i / 2);
      const x = col === 0 ? 0.4 : 5.3;
      const y = 1.35 + row * 1.85;

      sl.addShape(pres.shapes.RECTANGLE, {
        x, y, w: 4.5, h: 1.6,
        fill: { color: C.white },
        shadow: { type: "outer", blur: 5, offset: 2, angle: 135, color: "000000", opacity: 0.08 },
        line: { color: "E8DFD0", width: 0.5 }
      });

      const iconPng = await iconPng(p.icon, p.color, 256);
      sl.addImage({ data: iconPng, x: x + 0.2, y: y + 0.18, w: 0.5, h: 0.5 });

      sl.addText(p.title, {
        x: x + 0.85, y: y + 0.15, w: 3.5, h: 0.35,
        fontSize: 14, color: C.dark, bold: true,
        fontFace: "Calibri", margin: 0
      });
      sl.addText(p.desc, {
        x: x + 0.2, y: y + 0.75, w: 4.1, h: 0.7,
        fontSize: 11, color: C.gray, fontFace: "Calibri",
        lineSpacingMultiple: 1.3, margin: 0
      });
    }
  }

  // ─── SLIDE 4: TENTANG APLIKASI ───────────────────────────────────
  {
    const sl = pres.addSlide();
    sl.background = { color: C.dark };

    // Left panel
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 4.2, h: 5.625,
      fill: { color: C.mid }, line: { color: C.mid }
    });

    const compassPng = await iconPng(FaCompass, C.gold, 512);
    sl.addImage({ data: compassPng, x: 0.85, y: 0.5, w: 2.5, h: 2.5 });

    sl.addText("Jejak\nNusantara", {
      x: 0.3, y: 3.1, w: 3.6, h: 1.4,
      fontSize: 32, color: C.cream, bold: true,
      fontFace: "Georgia", align: "center",
      lineSpacingMultiple: 1.2, margin: 0
    });
    sl.addText("Jelajahi · Pelajari · Ingat", {
      x: 0.3, y: 4.55, w: 3.6, h: 0.5,
      fontSize: 11, color: C.gold, fontFace: "Calibri",
      align: "center", italic: true, margin: 0
    });

    // Right content
    sl.addText("Tentang Aplikasi", {
      x: 4.6, y: 0.3, w: 5.1, h: 0.6,
      fontSize: 26, color: C.gold, bold: true,
      fontFace: "Georgia", margin: 0
    });

    const facts = [
      { label: "Nama", value: "Jejak Nusantara" },
      { label: "Kategori", value: "LMS Sejarah Indonesia" },
      { label: "Target", value: "Siswa & Guru SD–SMA" },
      { label: "Platform", value: "Android + Web" },
      { label: "Maskot", value: "Mpu — penjelajah Bugis" },
      { label: "Chatbot AI", value: "Gemini (dev) → Claude Sonnet" },
    ];

    facts.forEach((f, i) => {
      const y = 1.1 + i * 0.68;
      sl.addShape(pres.shapes.RECTANGLE, {
        x: 4.6, y, w: 5.0, h: 0.55,
        fill: { color: C.mid }, line: { color: C.mid }
      });
      sl.addText(f.label, {
        x: 4.75, y: y + 0.09, w: 1.5, h: 0.35,
        fontSize: 10, color: C.gold, fontFace: "Calibri",
        bold: true, margin: 0
      });
      sl.addText(f.value, {
        x: 6.3, y: y + 0.09, w: 3.1, h: 0.35,
        fontSize: 11, color: C.cream, fontFace: "Calibri", margin: 0
      });
    });
  }

  // ─── SLIDE 5: COLOR PALETTE ──────────────────────────────────────
  {
    const sl = pres.addSlide();
    sl.background = { color: C.light };

    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 1.1,
      fill: { color: C.dark }, line: { color: C.dark }
    });
    sl.addText("Identitas Visual", {
      x: 0.5, y: 0.15, w: 9, h: 0.8,
      fontSize: 28, color: C.cream, bold: true,
      fontFace: "Georgia", margin: 0
    });

    const colors = [
      { hex: C.dark,   name: "Tanah Tua",   desc: "Akar sejarah,\nbumi pertiwi",   textColor: C.cream, goldColor: C.gold },
      { hex: C.mid,    name: "Kayu Jati",   desc: "Kekuatan &\nkekokohan adat",   textColor: C.cream, goldColor: C.gold },
      { hex: C.gold,   name: "Emas Tua",    desc: "Kejayaan\nkerajaan Nusantara", textColor: C.dark,  goldColor: C.dark  },
      { hex: C.cream,  name: "Kulit Lontar", desc: "Ilmu &\nwarisan budaya",      textColor: C.dark,  goldColor: C.mid   },
      { hex: C.forest, name: "Hutan Rimba", desc: "Kekayaan\nalam archipelago",   textColor: C.cream, goldColor: C.cream },
      { hex: C.red,    name: "Merah Saga",  desc: "Keberanian\npara pahlawan",    textColor: C.cream, goldColor: C.cream },
    ];

    colors.forEach((c, i) => {
      const x = 0.4 + i * 1.55;
      sl.addShape(pres.shapes.RECTANGLE, {
        x, y: 1.3, w: 1.35, h: 3.0,
        fill: { color: c.hex }, line: { color: c.hex }
      });
      sl.addText(`#${c.hex}`, {
        x, y: 1.35, w: 1.35, h: 0.3,
        fontSize: 8, color: c.goldColor, fontFace: "Calibri",
        align: "center", margin: 0
