class UserModel {
  final String uid;
  final String nama;
  final String email;
  final String role; // 'siswa', 'guru', 'admin'
  final String? kelasId;
  final String status; // 'active', 'pending'
  final DateTime createdAt;

  UserModel({
    required this.uid,
    required this.nama,
    required this.email,
    required this.role,
    this.kelasId,
    this.status = 'active',
    required this.createdAt,
  });

  factory UserModel.fromMap(Map<String, dynamic> map, String uid) {
    return UserModel(
      uid: uid,
      nama: map['nama'] ?? '',
      email: map['email'] ?? '',
      role: map['role'] ?? 'siswa',
      kelasId: map['kelasId'],
      status: map['status'] ?? 'active',
      createdAt: map['createdAt'] != null
          ? DateTime.parse(map['createdAt'])
          : DateTime.now(),
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'nama': nama,
      'email': email,
      'role': role,
      'kelasId': kelasId,
      'status': status,
      'createdAt': createdAt.toIso8601String(),
    };
  }
}
```

