```dart
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../../shared/models/user_model.dart';

class AuthService {
  final FirebaseAuth _auth = FirebaseAuth.instance;
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;

  // Cek user yang sedang login
  User? get currentUser => _auth.currentUser;

  // Stream untuk memantau status login realtime
  Stream<User?> get authStateChanges => _auth.authStateChanges();

  // LOGIN
  Future<UserModel?> login(String email, String password) async {
    try {
      final credential = await _auth.signInWithEmailAndPassword(
        email: email,
        password: password,
      );

      final uid = credential.user!.uid;
      final doc = await _firestore.collection('users').doc(uid).get();

      if (!doc.exists) {
        throw Exception('Data user tidak ditemukan');
      }

      final userModel = UserModel.fromMap(doc.data()!, uid);

      // Cek apakah guru masih pending
      if (userModel.role == 'guru' && userModel.status == 'pending') {
        await _auth.signOut();
        throw Exception('Akun guru kamu masih menunggu approval admin');
      }

      return userModel;
    } on FirebaseAuthException catch (e) {
      throw Exception(_mapFirebaseError(e.code));
    }
  }

  // REGISTER
  Future<UserModel?> register({
    required String nama,
    required String email,
    required String password,
    required String role, // 'siswa' atau 'guru'
    String? kelasId,
  }) async {
    try {
      final credential = await _auth.createUserWithEmailAndPassword(
        email: email,
        password: password,
      );

      final uid = credential.user!.uid;

      final newUser = UserModel(
        uid: uid,
        nama: nama,
        email: email,
        role: role,
        kelasId: kelasId,
        status: role == 'guru' ? 'pending' : 'active',
        createdAt: DateTime.now(),
      );

      await _firestore.collection('users').doc(uid).set(newUser.toMap());

      // Kalau guru, langsung sign out karena harus approval dulu
      if (role == 'guru') {
        await _auth.signOut();
      }

      return newUser;
    } on FirebaseAuthException catch (e) {
      throw Exception(_mapFirebaseError(e.code));
    }
  }

  // LOGOUT
  Future<void> logout() async {
    await _auth.signOut();
  }

  // Ambil data user dari Firestore
  Future<UserModel?> getUserData(String uid) async {
    final doc = await _firestore.collection('users').doc(uid).get();
    if (!doc.exists) return null;
    return UserModel.fromMap(doc.data()!, uid);
  }

  // Mapping error Firebase ke Bahasa Indonesia
  String _mapFirebaseError(String code) {
    switch (code) {
      case 'user-not-found':
        return 'Email tidak ditemukan';
      case 'wrong-password':
        return 'Password salah';
      case 'invalid-email':
        return 'Format email tidak valid';
      case 'email-already-in-use':
        return 'Email sudah terdaftar';
      case 'weak-password':
        return 'Password terlalu lemah, minimal 6 karakter';
      case 'invalid-credential':
        return 'Email atau password salah';
      default:
        return 'Terjadi kesalahan: $code';
    }
  }
}
```

