class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _authService = AuthService();
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();

  bool _isLoading = false;
  String? _errorMessage;

  // Palet warna Jejak Nusantara
  static const Color dark = Color(0xFF3D2B1F);
  static const Color mid = Color(0xFF5C3D2E);
  static const Color gold = Color(0xFFC4956A);
  static const Color cream = Color(0xFFF5E6C8);

  Future<void> _handleLogin() async {
    setState(() {
      _isLoading = true;
      _errorMessage = null;
    });

    try {
      final user = await _authService.login(
        _emailController.text.trim(),
        _passwordController.text.trim(),
      );

      if (user == null || !mounted) return;

      // Routing berdasarkan role
      if (user.role == 'siswa') {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(builder: (_) => const SiswaHomeScreen()),
