    super.initState();
    _loadData();
  }

  Future<void> _loadData() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;

    final userDoc = await FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .get();

    final babSnap = await FirebaseFirestore.instance
        .collection('bab')
        .where('published', isEqualTo: true)
        .get();

    if (mounted) {
      setState(() {
        _user = UserModel.fromMap(userDoc.data()!, uid);
        _totalBab = babSnap.docs.length;
        _isLoading = false;
      });
    }
