import 'package:flutter/material.dart';
import '../../shared/models/bab_model.dart';

class BabDetailScreen extends StatelessWidget {
  final BabModel bab;
  const BabDetailScreen({super.key, required this.bab});

  static const Color dark = Color(0xFF3D2B1F);
  static const Color mid = Color(0xFF5C3D2E);
  static const Color gold = Color(0xFFC4956A);
  static const Color cream = Color(0xFFF5E6C8);
  static const Color forest = Color(0xFF2C5F2E);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: dark,
      appBar: AppBar(
        backgroundColor: dark,
        elevation: 0,
        iconTheme: const IconThemeData(color: cream),
        title: Text(
          'Bab ${bab.nomorBab}',
          style: const TextStyle(color: cream, fontWeight: FontWeight.bold),
        ),
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Header bab
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(20),
              decoration: BoxDecoration(
                color: mid,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 10, vertical: 4),
                    decoration: BoxDecoration(
                      color: gold.withValues(alpha: 0.2),
                      borderRadius: BorderRadius.circular(20),
                    ),
                    child: Text(
                      'Bab ${bab.nomorBab}',
                      style: const TextStyle(color: gold, fontSize: 11),
                    ),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    bab.judul,
                    style: const TextStyle(
                      color: cream,
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    bab.deskripsi,
                    style: TextStyle(
                      color: gold.withValues(alpha: 0.8),
                      fontSize: 13,
                      height: 1.5,
                    ),
                  ),
                ],
              ),
            ),

            const SizedBox(height: 20),
            const Text(
              'Materi Tersedia',
              style: TextStyle(
                color: cream,
                fontSize: 15,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 12),

            // Tombol Video
            _buildMaterialButton(
              icon: Icons.play_circle_filled,
              label: 'Tonton Video',
              sublabel: bab.videoUrl.isNotEmpty
                  ? 'Video tersedia'
                  : 'Belum ada video',
              color: forest,
              available: bab.videoUrl.isNotEmpty,
              onTap: () {
                if (bab.videoUrl.isNotEmpty) {
                  _showVideoDialog(context);
                }
              },
            ),

            const SizedBox(height: 10),

            // Tombol PDF
            _buildMaterialButton(
              icon: Icons.picture_as_pdf,
              label: 'Buka PDF',
              sublabel: bab.pdfUrl.isNotEmpty
                  ? 'PDF tersedia'
                  : 'Belum ada PDF',
              color: const Color(0xFF8B1A1A),
              available: bab.pdfUrl.isNotEmpty,
              onTap: () {
                if (bab.pdfUrl.isNotEmpty) {
                  // nanti integrasi PDF viewer
                }
              },
            ),

            const SizedBox(height: 24),

            // Tombol Mulai Kuis
            SizedBox(
              width: double.infinity,
              height: 50,
              child: ElevatedButton.icon(
                onPressed: () {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('Kuis akan tersedia segera!'),
                    ),
                  );
                },
                icon: const Icon(Icons.quiz, color: dark),
                label: const Text(
                  'Mulai Kuis Bab Ini',
                  style: TextStyle(
                    color: dark,
                    fontWeight: FontWeight.bold,
                    fontSize: 15,
                  ),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: gold,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildMaterialButton({
    required IconData icon,
    required String label,
    required String sublabel,
    required Color color,
    required bool available,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: mid,
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: available
                ? color.withValues(alpha: 0.5)
                : gold.withValues(alpha: 0.1),
          ),
        ),
        child: Row(
          children: [
            Container(
              width: 44,
              height: 44,
              decoration: BoxDecoration(
                color: available
                    ? color.withValues(alpha: 0.2)
                    : gold.withValues(alpha: 0.1),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Icon(
                icon,
                color: available ? color : gold.withValues(alpha: 0.3),
                size: 24,
              ),
            ),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    label,
                    style: TextStyle(
                      color: available ? cream : cream.withValues(alpha: 0.4),
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  Text(
                    sublabel,
                    style: TextStyle(
                      color: available
                          ? gold.withValues(alpha: 0.8)
                          : gold.withValues(alpha: 0.3),
                      fontSize: 11,
                    ),
                  ),
                ],
              ),
            ),
            Icon(
              available ? Icons.arrow_forward_ios : Icons.lock_outline,
              color: available ? gold : gold.withValues(alpha: 0.3),
              size: 14,
            ),
          ],
        ),
      ),
    );
  }

  void _showVideoDialog(BuildContext context) {
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        backgroundColor: mid,
        title: const Text('Video Materi',
            style: TextStyle(color: cream)),
        content: Text(
          'Link video:\n${bab.videoUrl}',
          style: const TextStyle(color: gold, fontSize: 12),
