{"returncode":0,"stdout":"import 'dart:math';
import 'package:flutter/material.dart';
import '../../../shared/models/bab_model.dart';
import '../../../shared/models/question_model.dart';
import '../../../shared/models/quiz_result_model.dart';
import '../../../shared/services/quiz_service.dart';
import '../../auth/auth_service.dart';

class QuizScreen extends StatefulWidget {
  final BabModel bab;
  const QuizScreen({super.key, required this.bab});

  @override
  State<QuizScreen> createState() => _QuizScreenState();
}

class _QuizScreenState extends State<QuizScreen> with WidgetsBindingObserver {
  static const Color dark = Color(0xFF3D2B1F);
  static const Color mid = Color(0xFF5C3D2E);
  static const Color gold = Color(0xFFC4956A);
  static const Color cream = Color(0xFFF5E6C8);
  static const Color forest = Color(0xFF2C5F2E);
  static const Color danger = Color(0xFF8B1A1A);

  final QuizService _quizService = QuizService();
  final AuthService _authService = AuthService();

  List<QuestionModel> _questions = [];
  Map<String, String> _answers = {}; // questionId -> jawaban siswa
  bool _isLoading = true;
  int _currentIndex = 0;
  bool _isSubmitting = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _loadQuestions();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // Saat tab/app jadi tidak aktif (pindah tab, minimize, dll)
    if (state == AppLifecycleState.hidden ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive) {
      if (!_isLoading && !_isSubmitting && mounted) {
        _resetQuiz();
      }
    }
  }

  Future<void> _loadQuestions() async {
    setState(() => _isLoading = true);
    final questions = await _quizService.getQuestions(widget.bab.id);
    questions.shuffle(Random());

    // Acak juga urutan pilihan untuk tipe 'pg'
    for (var q in questions) {
      if (q.tipe == 'pg') {
        q.pilihan.shuffle(Random());
      }
    }

    setState(() {
      _questions = questions;
      _answers = {};
      _currentIndex = 0;
      _isLoading = false;
    });
  }

  void _resetQuiz() {
    if (!mounted) return;
    _loadQuestions();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Kuis di-reset karena kamu keluar dari tab/aplikasi!',
            ),
            backgroundColor: danger,
            duration: Duration(seconds: 3),
          ),
        );
      }
    });
  }

  void _selectAnswer(String questionId, String answer) {
    setState(() {
      _answers[questionId] = answer;
    });
  }

  bool get _isLastQuestion => _currentIndex == _questions.length - 1;
  bool get _isCurrentAnswered =>
      _answers.containsKey(_questions[_currentIndex].id);

  void _nextQuestion() {
    if (_isLastQuestion) {
      _submitQuiz();
    } else {
      setState(() => _currentIndex++);
    }
  }

  Future<void> _submitQuiz() async {
    setState(() => _isSubmitting = true);

    int jumlahBenar = 0;
    for (var q in _questions) {
      final jawabanSiswa = _answers[q.id] ?? '';
      if (jawabanSiswa.trim().toLowerCase() ==
          q.jawabanBenar.trim().toLowerCase()) {
        jumlahBenar++;
      }
    }

    final skor = ((jumlahBenar / _questions.length) * 100).round();
    final lulus = skor >= 75;

    final user = _authService.currentUser;
    if (user != null) {
      final result = QuizResultModel(
        id: '',
        userId: user.uid,
        babId: widget.bab.id,
        skor: skor,
        totalSoal: _questions.length,
        jumlahBenar: jumlahBenar,
        lulus: lulus,
        waktuSelesai: DateTime.now(),
      );
      await _quizService.saveQuizResult(result);
    }

    if (mounted) {
      setState(() => _isSubmitting = false);
      _showResultDialog(skor, jumlahBenar, lulus);
    }
  }

  void _showResultDialog(int skor, int jumlahBenar, bool lulus) {
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => AlertDialog(
        backgroundColor: mid,
        title: Text(
          lulus ? '🎉 Selamat, Lulus!' : '😔 Belum Lulus',
          style: const TextStyle(color: cream, fontWeight: FontWeight.bold),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Nilai: $skor',
              style: const TextStyle(
                color: gold,
                fontSize: 18,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              'Benar: $jumlahBenar dari ${_questions.length} soal',
              style: TextStyle(color: gold.withValues(alpha: 0.8)),
            ),
            const SizedBox(height: 6),
            Text(
              'Minimum kelulusan: 75',
              style: TextStyle(
                color: gold.withValues(alpha: 0.6),
                fontSize: 12,
              ),
            ),
          ],
        ),
        actions: [
          if (!lulus)
            TextButton(
              onPressed: () {
                Navigator.pop(context);
                _loadQuestions();
              },
              child: const Text('Coba Lagi', style: TextStyle(color: gold)),
            ),
          ElevatedButton(
            onPressed: () {
              Navigator.pop(context); // tutup dialog
              Navigator.pop(context); // balik ke bab detail
            },
            style: ElevatedButton.styleFrom(backgroundColor: gold),
            child: const Text('Selesai', style: TextStyle(color: dark)),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return Scaffold(
        backgroundColor: dark,
        body: const Center(child: CircularProgressIndicator(color: gold)),
      );
    }

    if (_questions.isEmpty) {
      return Scaffold(
        backgroundColor: dark,
        appBar: AppBar(
          backgroundColor: dark,
          elevation: 0,
          iconTheme: const IconThemeData(color: cream),
        ),
        body: Center(
          child: Text(
            'Belum ada soal kuis untuk bab ini',
            style: TextStyle(color: gold.withValues(alpha: 0.6)),
          ),
        ),
      );
    }

    final question = _questions[_currentIndex];

    return Scaffold(
      backgroundColor: dark,
      appBar: AppBar(
        backgroundColor: dark,
        elevation: 0,
        automaticallyImplyLeading: false,
        iconTheme: const IconThemeData(color: cream),
        title: Text(
          'Soal ${_currentIndex + 1} dari ${_questions.length}',
          style: const TextStyle(color: cream, fontWeight: FontWeight.bold),
        ),
      ),
      body: SafeArea(
        child: Column(
          children: [
            // Progress bar
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
              child: LinearProgressIndicator(
                value: (_currentIndex + 1) / _questions.length,
                backgroundColor: mid,
                color: gold,
                minHeight: 6,
                borderRadius: BorderRadius.circular(10),
              ),
            ),

            Expanded(
              child: SingleChildScrollView(
                padding: const EdgeInsets.all(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Pertanyaan
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(18),
                      decoration: BoxDecoration(
                        color: mid,
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: Text(
                        question.pertanyaan,
                        style: const TextStyle(
                          color: cream,
                          fontSize: 16,
                          fontWeight: FontWeight.w600,
                          height: 1.4,
                        ),
                      ),
                    ),

                    const SizedBox(height: 20),

                    // Opsi jawaban sesuai tipe soal
                    _buildAnswerOptions(question),
                  ],
                ),
              ),
            ),

            // Tombol lanjut
            Padding(
              padding: const EdgeInsets.all(20),
              child: SizedBox(
                width: double.infinity,
                height: 50,
                child: ElevatedButton(
                  onPressed: _isCurrentAnswered && !_isSubmitting
                      ? _nextQuestion
                      : null,
                  style: ElevatedButton.styleFrom(
                    backgroundColor: gold,
                    disabledBackgroundColor: gold.withValues(alpha: 0.3),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  child: _isSubmitting
                      ? const CircularProgressIndicator(color: dark)
                      : Text(
                          _isLastQuestion ? 'Selesai' : 'Lanjut',
                          style: const TextStyle(
                            color: dark,
                            fontWeight: FontWeight.bold,
                            fontSize: 15,
                          ),
                        ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildAnswerOptions(QuestionModel question) {
    final selected = _answers[question.id];

    if (question.tipe == 'pg') {
      return Column(
        children: question.pilihan.map((opsi) {
          final isSelected = selected == opsi;
          return Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: GestureDetector(
              onTap: () => _selectAnswer(question.id, opsi),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: isSelected ? gold.withValues(alpha: 0.2) : mid,
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(
                    color: isSelected ? gold : gold.withValues(alpha: 0.15),
                    width: isSelected ? 2 : 1,
                  ),
                ),
                child: Text(
                  opsi,
                  style: TextStyle(
                    color: isSelected ? gold : cream,
                    fontWeight: isSelected
                        ? FontWeight.bold
                        : FontWeight.normal,
                  ),
                ),
              ),
            ),
          );
        }).toList(),
      );
    }

    if (question.tipe == 'benar_salah') {
      return Row(
        children: ['Benar', 'Salah'].map((opsi) {
          final isSelected = selected == opsi;
          return Expanded(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 6),
              child: GestureDetector(
                onTap: () => _selectAnswer(question.id, opsi),
                child: Container(
                  padding: const EdgeInsets.symmetric(vertical: 16),
                  decoration: BoxDecoration(
                    color: isSelected
                        ? (opsi == 'Benar' ? forest : danger).withValues(
                            alpha: 0.3,
                          )
                        : mid,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: isSelected
                          ? (opsi == 'Benar' ? forest : danger)
                          : gold.withValues(alpha: 0.15),
                      width: isSelected ? 2 : 1,
                    ),
                  ),
                  child: Text(
                    opsi,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: cream,
                      fontWeight: isSelected
                          ? FontWeight.bold
                          : FontWeight.normal,
                    ),
                  ),
                ),
              ),
            ),
          );
        }).toList(),
      );
    }

    // tipe == 'isian'
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 14),
      decoration: BoxDecoration(
        color: mid,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: gold.withValues(alpha: 0.3)),
