          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return Scaffold(
        backgroundColor: dark,
        body: const Center(child: CircularProgressIndicator(color: gold)),
      );
    }

    if (_questions.isEmpty) {
      return Scaffold(
        backgroundColor: dark,
        appBar: AppBar(
          backgroundColor: dark,
          elevation: 0,
          iconTheme: const IconThemeData(color: cream),
        ),
        body: Center(
          child: Text(
            'Belum ada soal kuis untuk bab ini',
            style: TextStyle(color: gold.withValues(alpha: 0.6)),
          ),
