import 'package:flutter/material.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../../shared/models/user_model.dart';
import '../auth/login_screen.dart';
import 'guru_siswa_screen.dart';
import 'guru_materi_screen.dart';

class GuruHomeScreen extends StatefulWidget {
  const GuruHomeScreen({super.key});

  @override
  State<GuruHomeScreen> createState() => _GuruHomeScreenState();
}

class _GuruHomeScreenState extends State<GuruHomeScreen> {
  static const Color dark = Color(0xFF3D2B1F);
  static const Color mid = Color(0xFF5C3D2E);
  static const Color gold = Color(0xFFC4956A);
  static const Color cream = Color(0xFFF5E6C8);
  static const Color forest = Color(0xFF2C5F2E);

  UserModel? _guru;
  int _totalSiswa = 0;
  int _totalBab = 0;
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _loadData();
  }

  Future<void> _loadData() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) return;

    try {
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .get();

      final siswaSnap = await FirebaseFirestore.instance
          .collection('users')
          .where('role', isEqualTo: 'siswa')
          .get();

      final babSnap = await FirebaseFirestore.instance
          .collection('bab')
          .where('published', isEqualTo: true)
          .get();

      if (mounted) {
        setState(() {
          if (userDoc.exists && userDoc.data() != null) {
            _guru = UserModel.fromMap(userDoc.data()!, uid);
          }
          _totalSiswa = siswaSnap.docs.length;
          _totalBab = babSnap.docs.length;
          _isLoading = false;
        });
      }
    } catch (e) {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();
    if (mounted) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return const Scaffold(
        backgroundColor: dark,
        body: Center(child: CircularProgressIndicator(color: gold)),
      );
    }

    return Scaffold(
      backgroundColor: dark,
      body: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _buildHeader(),
              const SizedBox(height: 20),
              _buildStatRow(),
              const SizedBox(height: 20),
              _buildSectionTitle('Aktivitas Siswa'),
              const SizedBox(height: 10),
              _buildSiswaStream(),
              const SizedBox(height: 20),
              _buildSectionTitle('Akses Cepat'),
              const SizedBox(height: 10),
              _buildMenuGrid(),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildHeader() {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Halo, ${_guru?.nama.split(' ').first ?? 'Guru'}!',
              style: const TextStyle(
                color: cream,
                fontSize: 22,
                fontWeight: FontWeight.bold,
              ),
            ),
            Text(
              'Dashboard Guru',
              style: TextStyle(
                color: gold.withValues(alpha: 0.8),
                fontSize: 13,
              ),
            ),
          ],
        ),
        IconButton(
          icon: const Icon(Icons.logout, color: gold),
          onPressed: _logout,
        ),
      ],
    );
  }

  Widget _buildStatRow() {
    return Row(
      children: [
        _buildStatCard('$_totalSiswa', 'Total Siswa', Icons.people_outline),
        const SizedBox(width: 10),
        _buildStatCard('$_totalBab', 'Total Bab', Icons.book_outlined),
        const SizedBox(width: 10),
        _buildStatCard('0', 'Avg Nilai', Icons.bar_chart),
      ],
    );
  }

  Widget _buildStatCard(String value, String label, IconData icon) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: mid,
          borderRadius: BorderRadius.circular(10),
        ),
        child: Column(
          children: [
            Icon(icon, color: gold, size: 20),
            const SizedBox(height: 6),
            Text(
              value,
              style: const TextStyle(
                color: cream,
                fontSize: 20,
                fontWeight: FontWeight.bold,
              ),
            ),
            Text(
