import 'package:flutter/material.dart';
import '../../../shared/services/mpu_service.dart';

class MpuChatScreen extends StatefulWidget {
  const MpuChatScreen({super.key});

  @override
  State<MpuChatScreen> createState() => _MpuChatScreenState();
}

class _MpuChatScreenState extends State<MpuChatScreen> {
  static const Color dark = Color(0xFF3D2B1F);
  static const Color mid = Color(0xFF5C3D2E);
  static const Color gold = Color(0xFFC4956A);
  static const Color cream = Color(0xFFF5E6C8);
  static const Color forest = Color(0xFF2C5F2E);

  final MpuService _mpuService = MpuService();
  final TextEditingController _controller = TextEditingController();
  final ScrollController _scrollController = ScrollController();

  final List<Map<String, String>> _messages = [];
  bool _isTyping = false;

  @override
  void initState() {
    super.initState();
    // Pesan sambutan Mpu
    _messages.add({
      'role': 'mpu',
      'text': 'Hei! Aku Mpu, pemandumu dalam perjalanan menjelajahi sejarah Indonesia! 🗺️\n\nAda yang ingin kamu tanyakan tentang sejarah? Aku siap membantu!',
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  Future<void> _sendMessage() async {
    final text = _controller.text.trim();
    if (text.isEmpty || _isTyping) return;

    setState(() {
      _messages.add({'role': 'siswa', 'text': text});
      _isTyping = true;
    });

    _controller.clear();
    _scrollToBottom();

    final response = await _mpuService.kirimPesan(text);

    if (mounted) {
      setState(() {
        _messages.add({'role': 'mpu', 'text': response});
        _isTyping = false;
      });
      _scrollToBottom();
    }
  }

  void _scrollToBottom() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scrollController.hasClients) {
        _scrollController.animateTo(
          _scrollController.position.maxScrollExtent,
          duration: const Duration(milliseconds: 300),
          curve: Curves.easeOut,
        );
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: dark,
      appBar: AppBar(
        backgroundColor: dark,
        elevation: 0,
        iconTheme: const IconThemeData(color: cream),
        title: Row(
          children: [
            Container(
              width: 36,
              height: 36,
              decoration: const BoxDecoration(
                color: gold,
                shape: BoxShape.circle,
              ),
              child: const Icon(Icons.explore, color: dark, size: 20),
            ),
            const SizedBox(width: 10),
            const Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Mpu',
                  style: TextStyle(
                    color: cream,
                    fontSize: 15,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                Text(
                  'Pemandu Sejarah Indonesia',
                  style: TextStyle(color: gold, fontSize: 10),
                ),
              ],
            ),
          ],
        ),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh, color: gold),
            onPressed: () {
              _mpuService.resetChat();
              setState(() {
                _messages.clear();
                _messages.add({
                  'role': 'mpu',
                  'text': 'Chat di-reset! Ayo mulai perjalanan baru menjelajahi sejarah Indonesia! 🗺️',
                });
              });
            },
          ),
        ],
      ),
      body: Column(
        children: [
          Expanded(
            child: ListView.builder(
              controller: _scrollController,
              padding: const EdgeInsets.all(16),
              itemCount: _messages.length + (_isTyping ? 1 : 0),
              itemBuilder: (context, index) {
                if (index == _messages.length && _isTyping) {
                  return _buildTypingIndicator();
                }
                final msg = _messages[index];
                return _buildBubble(msg['role']!, msg['text']!);
              },
            ),
          ),
          _buildInputBar(),
        ],
      ),
    );
  }

  Widget _buildBubble(String role, String text) {
    final isMpu = role == 'mpu';
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment:
            isMpu ? MainAxisAlignment.start : MainAxisAlignment.end,
        children: [
          if (isMpu) ...[
            Container(
              width: 32,
              height: 32,
              decoration: const BoxDecoration(
                color: gold,
                shape: BoxShape.circle,
              ),
              child: const Icon(Icons.explore, color: dark, size: 18),
            ),
            const SizedBox(width: 8),
          ],
          Flexible(
            child: Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: isMpu ? mid : gold.withValues(alpha: 0.2),
                borderRadius: BorderRadius.only(
                  topLeft: Radius.circular(isMpu ? 0 : 12),
                  topRight: Radius.circular(isMpu ? 12 : 0),
                  bottomLeft: const Radius.circular(12),
                  bottomRight: const Radius.circular(12),
                ),
                border: isMpu
                    ? null
                    : Border.all(color: gold.withValues(alpha: 0.4)),
              ),
              child: Text(
                text,
                style: TextStyle(
                  color: isMpu ? cream : cream,
                  fontSize: 13,
                  height: 1.5,
                ),
              ),
            ),
          ),
          if (!isMpu) const SizedBox(width: 8),
        ],
      ),
    );
  }

  Widget _buildTypingIndicator() {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: 32,
            height: 32,
            decoration: const BoxDecoration(
              color: gold,
              shape: BoxShape.circle,
            ),
            child: const Icon(Icons.explore, color: dark, size: 18),
          ),
          const SizedBox(width: 8),
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: mid,
              borderRadius: const BorderRadius.only(
                topRight: Radius.circular(12),
                bottomLeft: Radius.circular(12),
                bottomRight: Radius.circular(12),
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildDot(0),
                const SizedBox(width: 4),
                _buildDot(1),
                const SizedBox(width: 4),
                _buildDot(2),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildDot(int index) {
    return TweenAnimationBuilder<double>(
      tween: Tween(begin: 0.0, end: 1.0),
      duration: Duration(milliseconds: 600 + (index * 200)),
      builder: (context, value, child) {
        return Container(
          width: 8,
          height: 8,
          decoration: BoxDecoration(
            color: gold.withValues(alpha: 0.4 + (value * 0.6)),
            shape: BoxShape.circle,
          ),
        );
      },
    );
  }

  Widget _buildInputBar() {
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: mid,
        border: Border(
          top: BorderSide(color: gold.withValues(alpha: 0.2)),
        ),
      ),
      child: Row(
        children: [
          Expanded(
            child: TextField(
              controller: _controller,
              style: const TextStyle(color: cream, fontSize: 13),
              maxLines: null,
              textCapitalization: TextCapitalization.sentences,
              decoration: InputDecoration(
                hintText: 'Tanya Mpu tentang sejarah...',
                hintStyle: TextStyle(
                  color: cream.withValues(alpha: 0.4),
                  fontSize: 13,
                ),
                border: InputBorder.none,
                contentPadding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 8,
                ),
                filled: true,
                fillColor: dark,
                enabledBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(20),
                  borderSide: BorderSide.none,
                ),
                focusedBorder: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(20),
                  borderSide:
                      BorderSide(color: gold.withValues(alpha: 0.5)),
                ),
              ),
              onSubmitted: (_) => _sendMessage(),
            ),
          ),
          const SizedBox(width: 8),
          GestureDetector(
            onTap: _sendMessage,
            child: Container(
              width: 42,
              height: 42,
              decoration: BoxDecoration(
                color: _isTyping
                    ? gold.withValues(alpha: 0.3)
                    : gold,
                shape: BoxShape.circle,
              ),
              child: Icon(
                Icons.send_rounded,
                color: _isTyping ? gold : dark,
                size: 20,
              ),
            ),
          ),
        ],
      ),
    );
  }
}
```

